#requires -Version 5.0
# Bootstrap: force Windows PowerShell 5.1 + STA so WPF actually shows
if ($PSVersionTable.PSEdition -eq 'Core') {
    try {
        $desktop = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $self = if ($PSCommandPath) { $PSCommandPath } else { $MyInvocation.MyCommand.Path }
        Start-Process -FilePath $desktop -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-STA','-File', $self) -WorkingDirectory (Split-Path $self)
        exit
    } catch {}
}
if ($env:UG_STA_OK -ne '1') {
    try {
        if ([System.Threading.Thread]::CurrentThread.ApartmentState -ne [System.Threading.ApartmentState]::STA) {
            $env:UG_STA_OK = '1'

# CLI args: -Mode Setting|Network|All|Restore  (skips UI)
if (-not $env:UG_CLI_MODE) {
    foreach ($a in $args) {
        if ($a -match '^(Setting|Network|All|Restore|Internet)$') {
            $env:UG_CLI_MODE = $(if ($a -eq 'Internet') { 'Network' } else { $a })
        }
    }
    # also support named-like: -Mode Network passed as separate tokens
    for ($i = 0; $i -lt $args.Count; $i++) {
        if ($args[$i] -eq '-Mode' -and ($i + 1) -lt $args.Count) {
            $v = $args[$i + 1]
            if ($v -eq 'Internet') { $v = 'Network' }
            if ($v -in @('Setting','Network','All','Restore')) { $env:UG_CLI_MODE = $v }
        }
    }
}


            $self = if ($PSCommandPath) { $PSCommandPath } else { $MyInvocation.MyCommand.Path }
            $psExe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
            Start-Process -FilePath $psExe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-STA','-File', $self) -WorkingDirectory (Split-Path $self)
            exit
        }
    } catch {}
}

$env:UG_STA_OK = '1'

# Prevent PSReadLine cursor crash after large script / failed UI
try {
    Remove-Module PSReadLine -Force -ErrorAction SilentlyContinue
} catch {}
try {
    $w = [Math]::Max(120, [int]$Host.UI.RawUI.WindowSize.Width)
    $h = [Math]::Max(50, [int]$Host.UI.RawUI.WindowSize.Height)
    $bh = [Math]::Max(3000, [int]$Host.UI.RawUI.BufferSize.Height)
    $Host.UI.RawUI.BufferSize = New-Object System.Management.Automation.Host.Size($w, $bh)
} catch {}


Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase

function Clear-UGLeftovers {
    # Delete any log/temp leftovers — never leave log files behind
    $patterns = @(
        (Join-Path $env:TEMP "UG_*.log"),
        (Join-Path $env:TEMP "UG_*.txt"),
        (Join-Path $env:TEMP "*Underground*.log"),
        (Join-Path $env:TEMP "*ProjectSync*.log"),
        (Join-Path $env:TEMP "ChrisTitus_WinUtil_*.ps1"),
        (Join-Path $env:TEMP "UndergroundPrime_NetworkTweaker_*.ps1"),
        (Join-Path $env:TEMP "TCPOptimizer*.exe"),
        (Join-Path $env:TEMP "UG_Splash_*.gif"),
        (Join-Path $env:TEMP "*ui-error.log"),
        (Join-Path $PWD "*.log"),
        (Join-Path $PWD "*Underground*.log")
    )
    foreach ($pat in $patterns) {
        try {
            Get-ChildItem -Path $pat -ErrorAction SilentlyContinue | ForEach-Object {
                try { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue } catch {}
            }
        } catch {}
    }
    # CitizenFX bak if any
    try {
        $cfx = Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app\CitizenFX.ini.bak"
        if (Test-Path -LiteralPath $cfx) { Remove-Item -LiteralPath $cfx -Force -ErrorAction SilentlyContinue }
        Get-ChildItem -Path (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app\CitizenFX.ini.bak*") -ErrorAction SilentlyContinue |
            ForEach-Object { try { Remove-Item -LiteralPath $_.FullName -Force -EA SilentlyContinue } catch {} }
    } catch {}
}


# Hide the hosting PowerShell console while the WPF application is running.
if (-not ('ProjectUndergroundPrime.ConsoleWindow' -as [type])) {
    Add-Type @'
using System;
using System.Runtime.InteropServices;
namespace ProjectUndergroundPrime {
    public static class ConsoleWindow {
        [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
        [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
        public static void Hide() { var h = GetConsoleWindow(); if (h != IntPtr.Zero) ShowWindow(h, 0); }
        public static void Show() { var h = GetConsoleWindow(); if (h != IntPtr.Zero) ShowWindow(h, 5); }
    }
}
'@
}
# Console hide deferred until UI is ready: [ProjectUndergroundPrime.ConsoleWindow]::Hide()



