# ===== CLI entry (no WPF) =====
if ($env:UG_CLI_MODE -and $env:UG_CLI_MODE -ne '') {
    $cliMode = $env:UG_CLI_MODE
    $env:UG_CLI_MODE = ''
    $ErrorActionPreference = 'SilentlyContinue'
    if (-not (Get-Command Write-LogTime -EA SilentlyContinue)) {
        function Write-LogTime { param([string]$Text,[string]$Color='#FFFFFF') Write-Host ("  {0}" -f $Text) -ForegroundColor Gray }
    }
    if (-not (Get-Command Log-Name -EA SilentlyContinue)) {
        function Log-Name {
            param([string]$Name,[string]$Status='ok')
            if ($null -eq $script:Ok) { $script:Ok = 0 }
            if ($Status -ne 'ok') { return }
            $script:Ok++
        }
    }
    $script:Ok = 0
    $script:Fail = 0
    Write-Host ("  Running Mode={0} ..." -f $cliMode) -ForegroundColor Cyan
    try {
        if ($cliMode -eq 'Restore') {
            # light restore if dedicated restore not present
            try {
                if (Get-Command Apply-UserLockedRegs -EA SilentlyContinue) { } # no-op marker
                $null = & powercfg.exe -restoredefaultschemes 2>&1
                $null = & netsh.exe int tcp reset 2>&1
                Write-LogTime 'Restore baseline done' '#14eb00'
            } catch {}
        } else {
            $m = $cliMode
            if ($m -eq 'Internet') { $m = 'Network' }
            if (Get-Command Invoke-MergedAllSources -EA SilentlyContinue) {
                Invoke-MergedAllSources -Mode $m
            } else {
                Write-LogTime 'Invoke-MergedAllSources missing' '#FF0000'
            }
        }
    } catch {
        Write-Host ("  ERROR: {0}" -f $_.Exception.Message) -ForegroundColor Red
    }
    Write-Host ("  Done. applied={0}" -f [int]$script:Ok) -ForegroundColor Green
    exit 0
}


