function Test-Admin {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $p  = New-Object Security.Principal.WindowsPrincipal($id)
    return $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

if (-not (Test-Admin)) {
    $newProcess = New-Object System.Diagnostics.ProcessStartInfo "PowerShell"
    $newProcess.Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`""
    $newProcess.Verb = "RunAs"
    [System.Diagnostics.Process]::Start($newProcess) | Out-Null
    exit
}

# ============================================================
#  Background artwork, embedded as base64 so the whole app is
#  still a single .ps1 file with no external image to lose.
# ============================================================
function Get-BitmapFromBase64 {
    param([string]$Base64)
    $bytes  = [Convert]::FromBase64String($Base64)
    $stream = New-Object System.IO.MemoryStream(,$bytes)
    $bmp    = New-Object System.Windows.Media.Imaging.BitmapImage
    $bmp.BeginInit()
    $bmp.CacheOption   = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
    $bmp.StreamSource  = $stream
    $bmp.EndInit()
    $bmp.Freeze()
    return $bmp
}

$script:BgImageBase64 = ""
$script:SplashGifBase64 = ""


# Guard against empty/invalid image data. Decoding "" still produces a
# BitmapImage object that LOOKS fine at creation time, but has no real
# pixel data — WPF only discovers this later, deep in its render/composition
# pipeline, and throws PixelFormat.CreatePixelFormatInfo: "No information
# was found about this pixel format", crashing the whole app on first paint.
# Skipping the decode when there's nothing to decode avoids that entirely;
# a null Image.Source is completely safe and just renders nothing.
if ([string]::IsNullOrWhiteSpace($script:BgImageBase64)) {
    $script:BgBitmap = $null
} else {
    try {
        $script:BgBitmap = Get-BitmapFromBase64 -Base64 $script:BgImageBase64
    } catch {
        $script:BgBitmap = $null
    }
}

# ============================================================
#  Profile avatar picture (optional). Paste a base64-encoded
#  image string here to show a real photo in the profile circle
#  instead of the fallback icon. Leave empty to keep the icon.
#  How to generate the base64 string from your own image, run
#  this in a PowerShell window:
#    [Convert]::ToBase64String([IO.File]::ReadAllBytes("C:\path\to\photo.jpg")) | Set-Clipboard
#  then paste the clipboard contents between the quotes below.
# ============================================================
$script:AvatarImageBase64 = ""

if ([string]::IsNullOrWhiteSpace($script:AvatarImageBase64)) {
    $script:AvatarBitmap = $null
} else {
    try {
        $script:AvatarBitmap = Get-BitmapFromBase64 -Base64 $script:AvatarImageBase64
    } catch {
        $script:AvatarBitmap = $null
    }
}

