            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'LeaseTerminatesTime' -Value 0 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'LeaseTerminatesTime' } else { $script:Ok++ }
