            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'MTU' -Value 1 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'MTU' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'MTU' 'fail' } }
        try {
