            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'NameServer' -Value '' -PropertyType 'String' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'NameServer' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'NameServer' 'fail' } }
        try {
            if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}')) { New-Item -Path 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'RegisterAdapterName' -Value 0 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'RegisterAdapterName' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'RegisterAdapterName' 'fail' } }
        try {
            if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}')) { New-Item -Path 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'RegistrationEnabled' -Value 1 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'RegistrationEnabled' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'RegistrationEnabled' 'fail' } }
        try {
            if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}')) { New-Item -Path 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'T1' -Value 0 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'T1' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'T1' 'fail' } }
        try {
            if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}')) { New-Item -Path 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'T2' -Value 0 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'T2' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'T2' 'fail' } }
        try {
            if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}')) { New-Item -Path 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'TCPNoDelay' -Value 1 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'TCPNoDelay' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'TCPNoDelay' 'fail' } }
        try {
            if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}')) { New-Item -Path 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'TcpAckFrequency' -Value 1 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'TcpAckFrequency' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'TcpAckFrequency' 'fail' } }
        try {
            if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}')) { New-Item -Path 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\ControlSet002\services\Tcpip\Parameters\Interfaces\{F73B9E00-323A-451D-B553-FEB28BFCC91E}' -Name 'UseZeroBroadcast' -Value 0 -PropertyType 'DWord' -Force -ErrorAction SilentlyContinue | Out-Null
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'UseZeroBroadcast' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'UseZeroBroadcast' 'fail' } }
        foreach ($root in @('HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces','HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces')) {
            if (-not (Test-Path $root)) { continue }
            Get-ChildItem $root -ErrorAction SilentlyContinue | ForEach-Object {
                foreach ($pair in @(@{N='TcpAckFrequency';V=1},@{N='TCPNoDelay';V=1},@{N='TcpDelAckTicks';V=0})) {
                    try {
                        New-ItemProperty -LiteralPath $_.PSPath -Name $pair.N -Value $pair.V -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
                        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name $pair.N } else { $script:Ok++ }
                    } catch {}
                }
            }
        }
    }
    if (Get-Command Write-LogTime -ErrorAction SilentlyContinue) {
        Write-LogTime ("CoreRegistryBulk Mode=$Mode markers=$script:Ok") '#14eb00'
    }
}




function Apply-TopUfaAntiKai {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # UFA FULL x3: (1) UFASTEPHOD  (2) Internet UFA  (3) GPEdit-style  + ANTI + Kai
    function _Tk([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }
    if ($Mode -in @('Setting','All')) {
        try {
            # --- UFA 1: STEPHOD 1.reg core ---
            $pc = 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl'
            if (-not (Test-Path $pc)) { New-Item -Path $pc -Force | Out-Null }
            New-ItemProperty -Path $pc -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0x2E -Force -EA SilentlyContinue | Out-Null
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force | Out-Null }
            New-ItemProperty -Path $mm -Name 'AlwaysOn' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mm -Name 'NoLazyMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $games = "$mm\Tasks\Games"
            if (-not (Test-Path $games)) { New-Item -Path $games -Force | Out-Null }
            New-ItemProperty -Path $games -Name 'Affinity' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            # Queue 20 (UFA 0x14)
            foreach ($pair in @(
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize'),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize'),
                @('HKLM:\SYSTEM\ControlSet001\Services\mouclass\Parameters','MouseDataQueueSize'),
                @('HKLM:\SYSTEM\ControlSet001\Services\kbdclass\Parameters','KeyboardDataQueueSize')
            )) {
                if (-not (Test-Path $pair[0])) { New-Item -Path $pair[0] -Force | Out-Null }
                New-ItemProperty -Path $pair[0] -Name $pair[1] -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
            }
            # GPU low latency (display class)
            $gpuClass = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $gpuClass) {
                Get-ChildItem $gpuClass -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d+$' } | ForEach-Object {
                    foreach ($n in @('LOWLATENCY','Node3DLowLatency','D3PCLatency')) {
                        try { New-ItemProperty -LiteralPath $_.PSPath -Name $n -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null } catch {}
                    }
                }
            }
            $desk = 'HKLM:\SYSTEM\CurrentControlSet\Control\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force | Out-Null }
            New-ItemProperty -Path $desk -Name 'MenuShowDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $pwr = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power'
            if (-not (Test-Path $pwr)) { New-Item -Path $pwr -Force | Out-Null }
            New-ItemProperty -Path $pwr -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $pwr -Name 'CsEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $pwr -Name 'PlatformAoAcOverride' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $pwr -Name 'CStatePolicy' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $smp = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power'
            if (-not (Test-Path $smp)) { New-Item -Path $smp -Force | Out-Null }
            New-ItemProperty -Path $smp -Name 'CoalescingTimerInterval' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _Tk 'UFA_STEPHOD_Reg'
            # --- UFA 3: GPEdit-style policies ---
            foreach ($row in @(
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy','LetAppsRunInBackground',2),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU','NoAutoUpdate',1),
                @('HKCU:\System\GameConfigStore','GameDVR_Enabled',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR','AppCaptureEnabled',0)
            )) {
                if (-not (Test-Path $row[0])) { New-Item -Path $row[0] -Force | Out-Null }
                New-ItemProperty -Path $row[0] -Name $row[1] -PropertyType DWord -Value $row[2] -Force -EA SilentlyContinue | Out-Null
            }
            _Tk 'UFA_GPEdit'
            # ANTI input + timer + power (keep)
            if (-not (Test-Path $kr)) { New-Item -Path $kr -Force | Out-Null }
            $ba = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications'
            if (-not (Test-Path $ba)) { New-Item -Path $ba -Force | Out-Null }
            New-ItemProperty -Path $ba -Name 'GlobalUserDisabled' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformclock no 2>&1
            try {
                $active = (powercfg /getactivescheme) 2>$null
                if ($active -match '([0-9a-fA-F-]{36})') {
                    $guid = $Matches[1]
                    foreach ($src in @('/setacvalueindex','/setdcvalueindex')) {
                        $null = & powercfg.exe $src $guid SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1
                        $null = & powercfg.exe $src $guid SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1
                        $null = & powercfg.exe $src $guid SUB_PROCESSOR PERFBOOSTMODE 2 2>&1
                        $null = & powercfg.exe $src $guid SUB_DISK DISKIDLE 0 2>&1
                        $null = & powercfg.exe $src $guid SUB_USB USBSELECTIVESUSPEND 0 2>&1
                        $null = & powercfg.exe $src $guid SUB_PCIEXPRESS ASPM 0 2>&1
                    }
                    $null = & powercfg.exe /setactive $guid 2>&1
                }
            } catch {}
            foreach ($app in @('FiveM.exe','FiveM_GTAProcess.exe','FiveM_b3258_GTAProcess.exe','FiveM_b3095_GTAProcess.exe','FiveM_b2944_GTAProcess.exe')) {
                $ifeo = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$app\PerfOptions"
                if (-not (Test-Path $ifeo)) { New-Item -Path $ifeo -Force | Out-Null }
                New-ItemProperty -Path $ifeo -Name 'CpuPriorityClass' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $ifeo -Name 'IoPriority' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
            }
            $gpu = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
            if (-not (Test-Path $gpu)) { New-Item -Path $gpu -Force | Out-Null }
            foreach ($app in @('FiveM.exe','FiveM_GTAProcess.exe','GTA5.exe')) {
                New-ItemProperty -Path $gpu -Name $app -PropertyType String -Value 'GpuPreference=2;' -Force -EA SilentlyContinue | Out-Null
            }
            _Tk 'UFA_ANTI_Kai_Setting'
        } catch { _Tk 'UFA_Setting' 'fail' }
    }
    if ($Mode -in @('Network','All')) {
        try {
            # --- UFA 2: Internet UFA registry roots ---
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
            New-ItemProperty -Path $tp -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $tp6 = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters'
            if (-not (Test-Path $tp6)) { New-Item -Path $tp6 -Force | Out-Null }
            New-ItemProperty -Path $tp6 -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp6 -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force | Out-Null }
            New-ItemProperty -Path $afd -Name 'FastSendDatagramThreshold' -PropertyType DWord -Value 1500 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $afd -Name 'DefaultSendWindow' -PropertyType DWord -Value 262144 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $afd -Name 'DefaultReceiveWindow' -PropertyType DWord -Value 262144 -Force -EA SilentlyContinue | Out-Null
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force | Out-Null }
            New-ItemProperty -Path $dns -Name 'MaxCacheTtl' -PropertyType DWord -Value 86400 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'MaxNegativeCacheTtl' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $ps = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $ps)) { New-Item -Path $ps -Force | Out-Null }
            New-ItemProperty -Path $ps -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $ndis = 'HKLM:\SYSTEM\CurrentControlSet\Services\NDIS\Parameters'
            if (-not (Test-Path $ndis)) { New-Item -Path $ndis -Force | Out-Null }
            New-ItemProperty -Path $ndis -Name 'NetworkDirectDisable' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $tcpIf = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
            if (Test-Path $tcpIf) {
                Get-ChildItem $tcpIf -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                }
            }
            # NIC class (Internet UFA + Kai)
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d+$' } | ForEach-Object {
                    $nic = $_.PSPath
                    try { New-ItemProperty -LiteralPath $nic -Name 'PnPCapabilities' -PropertyType DWord -Value 24 -Force -EA SilentlyContinue | Out-Null } catch {}
                    foreach ($kv in @{
                        '*FlowControl'='0'; '*InterruptModeration'='0'; '*LsoV2IPv4'='0'; '*LsoV2IPv6'='0'
                        '*RSS'='1'; '*EEE'='0'; '*DeviceSleepOnDisconnect'='0'
                    }.GetEnumerator()) {
                        try { New-ItemProperty -LiteralPath $nic -Name $kv.Key -PropertyType String -Value $kv.Value -Force -EA SilentlyContinue | Out-Null } catch {}
                    }
                }
            }
            # Kai QoS
            foreach ($pair in @(@('UFAFiveM','FiveM.exe'),@('UFAFiveMGTA','FiveM_GTAProcess.exe'))) {
                $qos = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\$($pair[0])"
                if (-not (Test-Path $qos)) { New-Item -Path $qos -Force | Out-Null }
                New-ItemProperty -Path $qos -Name 'Version' -PropertyType String -Value '1.0' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'Application Name' -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'DSCP Value' -PropertyType String -Value '46' -Force -EA SilentlyContinue | Out-Null
                foreach ($v in @('Protocol','Local Port','Local IP','Local IP Prefix Length','Remote Port','Remote IP','Remote IP Prefix Length')) {
                    New-ItemProperty -Path $qos -Name $v -PropertyType String -Value '*' -Force -EA SilentlyContinue | Out-Null
                }
            }
            _Tk 'UFA_Internet_Reg'
        } catch { _Tk 'UFA_Internet' 'fail' }
        # --- UFA STEPHOD 27 netsh style ---
        foreach ($c in @(
            'int tcp set global rss=enabled',
            'int tcp set global dca=enabled',
            'int tcp set global netdma=enabled',
            'int tcp set global chimney=disabled',
            'int tcp set global rsc=disabled',
            'int tcp set global ecncapability=disabled',
            'int tcp set global timestamps=disabled',
            'int tcp set global nonsackrttresiliency=disabled',
            'int tcp set global autotuninglevel=disabled',
            'int tcp set global fastopen=enabled',
            'int tcp set global fastopenfallback=enabled',
            'int tcp set global maxsynretransmissions=2',
            'int tcp set global initialRto=2000',
            'int tcp set heuristics disabled',
            'int tcp set global memoryprofile=normal',
            'int ip set global taskoffload=enabled',
            'int ip set global multicastforwarding=disabled',
            'int ipv4 set global defaultcurhoplimit=64',
            'int ipv6 set global defaultcurhoplimit=64',
            'int ipv6 set global randomizeidentifiers=disabled',
            'int ipv6 set privacy state=disabled'
        )) {
            try { $null = & netsh.exe @($c.Split(' ')) 2>&1; _Tk $c } catch { _Tk $c 'fail' }
        }
        try { Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object Status -eq 'Up' | ForEach-Object { Enable-NetAdapterRss -Name $_.Name -EA SilentlyContinue } } catch {}
        _Tk 'UFA_Netsh_Full'
    }
}



