        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters' -Name 'MaximumCacheSize' -PropertyType DWord -Value (16384) -Force -EA SilentlyContinue|Out-Null;_Gd 'MaximumCacheSize'}catch{_Gd 'MaximumCacheSize' 'fail'}
        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Name 'ProcessorAffinityMask' -PropertyType DWord -Value (0) -Force -EA SilentlyContinue|Out-Null;_Gd 'ProcessorAffinityMask'}catch{_Gd 'ProcessorAffinityMask' 'fail'}
        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Name 'LogicalProcessorsPerPhysicalProcessor' -PropertyType DWord -Value (1) -Force -EA SilentlyContinue|Out-Null;_Gd 'LogicalProcessorsPerPhysicalProcessor'}catch{_Gd 'LogicalProcessorsPerPhysicalProcessor' 'fail'}
        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters' -Name 'EnableTCPChimney' -PropertyType DWord -Value (0) -Force -EA SilentlyContinue|Out-Null;_Gd 'EnableTCPChimney'}catch{_Gd 'EnableTCPChimney' 'fail'}
        try{
            $tp='HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if(-not(Test-Path $tp)){New-Item -Path $tp -Force|Out-Null}
            New-ItemProperty -Path $tp -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue|Out-Null
            New-ItemProperty -Path $tp -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue|Out-Null
            New-ItemProperty -Path $tp -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue|Out-Null
            $tcpIf='HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
            if(Test-Path $tcpIf){
                Get-ChildItem $tcpIf -EA SilentlyContinue|ForEach-Object{
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue|Out-Null
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue|Out-Null
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue|Out-Null
                }
            }
            _Gd 'God_IF_TCP'
        }catch{_Gd 'God_IF_TCP' 'fail'}
        # Dektin-style netsh (aggressive)
        foreach($c in @(
            'int tcp set heuristics disabled',
            'int tcp set global timestamps=disabled',
            'int tcp set global ecncapability=disabled',
            'int tcp set global rss=enabled',
            'int tcp set global dca=enabled',
            'int tcp set global rsc=disabled',
            'int tcp set global autotuninglevel=normal',
            'int tcp set global initialRto=1000',
            'int tcp set global maxsynretransmissions=2',
            'int tcp set global fastopen=enabled',
            'int ipv4 set global defaultcurhoplimit=64',
            'int ip set global neighborcachelimit=8192'
        )){
            try{$null=& netsh.exe @($c.Split(' ')) 2>&1; _Gd $c}catch{_Gd $c 'fail'}
        }
    }
}



