                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'netsh' }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
        } catch {}
    }


    # === EXTRA FROM OTHER SOURCES (Flow wins) ===
    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; SackOpts=1; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; MaxUserPort=65534
                TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                KeepAliveTime=300000; KeepAliveInterval=1000
                MaxFreeTcbs=16000; MaxHashTableSize=65536
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'ExtraNet' }
        } catch {}
    }

}



function Apply-NetworkForce {
    $ErrorActionPreference = 'SilentlyContinue'
    function _N([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    try {
        $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
        if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
        # single best values only
        $best = @{
            TcpAckFrequency = 1
            TCPNoDelay = 1
            TcpDelAckTicks = 0
            TcpTimedWaitDelay = 15
            DefaultTTL = 64
            EnablePMTUDiscovery = 1
            SackOpts = 1
            Tcp1323Opts = 1
            EnableRSS = 1
            EnableDCA = 1
            MaxUserPort = 65534
            TcpMaxDataRetransmissions = 3
            KeepAliveTime = 300000
            KeepAliveInterval = 1000
            SynAttackProtect = 0
            EnableDeadGWDetect = 0
        }
        foreach ($kv in $best.GetEnumerator()) {
            New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            _N $kv.Key
        }
        foreach ($root in @(
            'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
            'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
        )) {
            if (-not (Test-Path $root)) { continue }
            Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
            }
            _N 'Interface_NoNagle'
        }
        $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
        if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
        foreach ($kv in @{
            DefaultReceiveWindow = 262144
            DefaultSendWindow = 262144
            FastSendDatagramThreshold = 1500
            EnableDynamicBacklog = 1
            MinimumDynamicBacklog = 20
            MaximumDynamicBacklog = 20000
        }.GetEnumerator()) {
            New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            _N $kv.Key
        }
        New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
        Set-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
        _N 'NonBestEffortLimit'
        New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
        Set-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
        _N 'NetworkThrottlingIndex'
        New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
        Set-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
        _N 'SystemResponsiveness'

        foreach ($a in @(
            @('int','tcp','set','heuristics','disabled'),
            @('int','tcp','set','global','autotuninglevel=normal'),
            @('int','tcp','set','global','rss=enabled'),
            @('int','tcp','set','global','rsc=disabled'),
            @('int','tcp','set','global','timestamps=disabled'),
            @('int','tcp','set','global','ecncapability=disabled'),
            @('int','tcp','set','global','fastopen=enabled'),
            @('int','tcp','set','global','dca=enabled'),
            @('int','tcp','set','global','chimney=disabled'),
            @('int','tcp','set','global','initialRto=1000'),
            @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
            @('int','ipv4','set','global','defaultcurhoplimit=64'),
            @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536')
        )) {
            try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _N ('netsh') } catch {}
        }

        # NIC once
        $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
        if (Test-Path $nicRoot) {
            Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                $p = $_.PSPath
                foreach ($pair in @(
                    @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                    @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','8'),
                    @('*ReceiveBuffers','2048'),@('*TransmitBuffers','2048'),
                    @('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0')
                )) {
                    New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                }
            }
            _N 'NIC'
        }

        try { Apply-DnsCloudflare } catch {}

        try {
            Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback|Virtual|Bluetooth|VPN' } | ForEach-Object {
                try { Restart-NetAdapter -Name $_.Name -Confirm:$false -EA SilentlyContinue } catch {}
            }
            _N 'AdapterRestart'
        } catch {}
        try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
    } catch {}
}


function Apply-AironPlusLean {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    # Rank1 pair with Aspas V2 — SELECT values only (not full Airon dump)

    if ($Mode -in @('Setting','All')) {
        try {
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            $games = Join-Path $mm 'Tasks\Games'
            if (-not (Test-Path $games)) { New-Item -Path $games -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $games -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'GamesProfile' }

            $mem = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
            if (-not (Test-Path $mem)) { New-Item -Path $mem -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mem -Name 'DisablePagingExecutive' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mem -Name 'DisablePagingExecutive' -Value 1 -Type DWord -Force -EA SilentlyContinue

            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null

            $mou = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 16 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -Value 16 -Type DWord -Force -EA SilentlyContinue

            $mouse = 'HKCU:\Control Panel\Mouse'
            if (-not (Test-Path $mouse)) { New-Item -Path $mouse -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mouse -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null

            $desk = 'HKCU:\Control Panel\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $desk -Name 'MenuShowDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null

            $gfx = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
            if (-not (Test-Path $gfx)) { New-Item -Path $gfx -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gfx -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null

            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'AironLean_Setting' }
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; SackOpts=1; Tcp1323Opts=1; EnableRSS=1; EnableDCA=1
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            $ifRoot = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
            if (Test-Path $ifRoot) {
                Get-ChildItem $ifRoot -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $afd -Name 'FastSendDatagramThreshold' -PropertyType DWord -Value 1500 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $afd -Name 'DefaultReceiveWindow' -PropertyType DWord -Value 65535 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $afd -Name 'DefaultSendWindow' -PropertyType DWord -Value 65535 -Force -EA SilentlyContinue | Out-Null

            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null

            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null

            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue

            foreach ($a in @(
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'AironLean_Net' }
        } catch {}
    }
}




function Apply-FinalMax {
