            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Power' }

            $gfx = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
            if (-not (Test-Path $gfx)) { New-Item -Path $gfx -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gfx -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gfx -Name 'TdrLevel' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gfx -Name 'TdrDelay' -PropertyType DWord -Value 60 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Graphics' }

            $mou = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 16 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -Value 16 -Type DWord -Force -EA SilentlyContinue
            $mouse = 'HKCU:\Control Panel\Mouse'
            if (-not (Test-Path $mouse)) { New-Item -Path $mouse -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mouse -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            $kbd = 'HKCU:\Control Panel\Keyboard'
            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $kbd -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
            $desk = 'HKCU:\Control Panel\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                MenuShowDelay='0'; AutoEndTasks='1'; HungAppTimeout='1000'
                WaitToKillAppTimeout='2000'; LowLevelHooksTimeout='1000'; WaitToKillServiceTimeout='2000'
            }.GetEnumerator()) {
                New-ItemProperty -Path $desk -Name $kv.Key -PropertyType String -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
            }
            New-ItemProperty -Path $desk -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Input' }

            $gcs = 'HKCU:\System\GameConfigStore'
            if (-not (Test-Path $gcs)) { New-Item -Path $gcs -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gcs -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gcs -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gcs -Name 'GameDVR_HonorUserFSEBehaviorMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $gdvr = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR'
            if (-not (Test-Path $gdvr)) { New-Item -Path $gdvr -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gdvr -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null

            $fs = 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem'
            if (-not (Test-Path $fs)) { New-Item -Path $fs -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $fs -Name 'NtfsDisableLastAccessUpdate' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $fs -Name 'NtfsDisable8dot3NameCreation' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null

            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null

            $ex = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
            if (-not (Test-Path $ex)) { New-Item -Path $ex -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ex -Name 'TaskbarAnimations' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $ex -Name 'ListviewAlphaSelect' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $ex -Name 'ListviewShadow' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null

            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'BCDTimer' }
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; EnableWsd=0
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpFinWait2Delay=30
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                MaxFreeTcbs=16000; MaxHashTableSize=65536
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Tcpip' }

            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($pair in @(@{N='TcpAckFrequency';V=1},@{N='TCPNoDelay';V=1},@{N='TcpDelAckTicks';V=0})) {
                        New-ItemProperty -Path $_.PSPath -Name $pair.N -PropertyType DWord -Value $pair.V -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $pair.N -Value $pair.V -Type DWord -Force -EA SilentlyContinue
                    }
                }
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'TcpInterfaces' }

            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'AFD' }

            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $dns -Name 'MaxNegativeCacheTtl' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NegativeCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NetFailureCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'DNS' }

            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue

            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue

            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Ndu' }

            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','4'),
                        @('*ReceiveBuffers','512'),@('*TransmitBuffers','512'),
                        @('*LsoV1IPv4','0'),@('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),
                        @('*TCPChecksumOffloadIPv4','0'),@('*UDPChecksumOffloadIPv4','0'),@('ITR','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                }
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'NIC' }

            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'netsh' }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'flushdns' }
        } catch {}
    }
}


function Apply-FlowStick {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    # Critical keys that make Flow feel aggressive — applied last

    if ($Mode -in @('Setting','All')) {
        try {
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            foreach ($t in @('Games','Low Latency')) {
                $tp = Join-Path $mm ("Tasks\" + $t)
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $tp -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            }
            $mem = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
            if (-not (Test-Path $mem)) { New-Item -Path $mem -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mem -Name 'DisablePagingExecutive' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mem -Name 'DisablePagingExecutive' -Value 1 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $mem -Name 'LargeSystemCache' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -Value 1 -Type DWord -Force -EA SilentlyContinue
            $mou = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 16 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -Value 16 -Type DWord -Force -EA SilentlyContinue
            $mouse = 'HKCU:\Control Panel\Mouse'
            if (-not (Test-Path $mouse)) { New-Item -Path $mouse -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mouse -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            $desk = 'HKCU:\Control Panel\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $desk -Name 'MenuShowDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'StickSetting' }
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            # Flow-style TCP (the keys that feel sharp)
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                Tcp1323Opts=1; EnableRSS=1; EnableDCA=1
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2
                KeepAliveTime=300000; KeepAliveInterval=1000
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),
                        @('*ReceiveBuffers','512'),@('*TransmitBuffers','512'),
                        @('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'StickNet' }
        } catch {}
    }
}




function Apply-PolicyExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _P([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            $rows = @(
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','DoNotShowFeedbackNotifications',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\System','EnableActivityFeed',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\System','PublishUserActivities',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\System','UploadUserActivities',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System','DisableAutomaticRestartSignOn',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search','AllowCortana',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\WindowsStore','AutoDownload',2),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent','DisableWindowsConsumerFeatures',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent','DisableSoftLanding',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent','DisableTailoredExperiencesWithDiagnosticData',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer','DisableNotificationCenter',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU','NoAutoUpdate',0)
            )
            foreach ($row in $rows) {
                if (-not (Test-Path $row[0])) { New-Item -Path $row[0] -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $row[0] -Name $row[1] -PropertyType DWord -Value $row[2] -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $row[0] -Name $row[1] -Value $row[2] -Type DWord -Force -EA SilentlyContinue
                _P $row[1]
            }
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            # gpedit: QoS Packet Scheduler - Limit reservable bandwidth = 0
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _P 'NonBestEffortLimit'

            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            _P 'NetworkThrottlingIndex'
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _P 'SystemResponsiveness'

            $netPol = @(
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\NetworkConnectivityStatusIndicator','NoActiveProbe',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\WcmSvc\GroupPolicy','fMinimizeConnections',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\TCPIP\v6Transition','Teredo_State',0)
            )
            foreach ($row in $netPol) {
                if (-not (Test-Path $row[0])) { New-Item -Path $row[0] -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $row[0] -Name $row[1] -PropertyType DWord -Value $row[2] -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $row[0] -Name $row[1] -Value $row[2] -Type DWord -Force -EA SilentlyContinue
                _P $row[1]
            }
        } catch {}
    }
}


function Apply-BitcexExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    # Supplementary pack (rank1 fill only — other rank1 values win on conflicts)

    if ($Mode -in @('Setting','All')) {
        try {
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
            $games = Join-Path $mm 'Tasks\Games'
            if (-not (Test-Path $game)) { New-Item -Path $game -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'BitcexSetting' }
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue

            $ifRoot = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
            if (Test-Path $ifRoot) {
                Get-ChildItem $ifRoot -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                }
            }
            # bitcex netsh (others may override later)
            foreach ($a in @(
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','chimney=enabled'),
                @('int','tcp','set','global','netdma=enabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','timestamps=disabled')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'BitcexNet' }
        } catch {}
    }
}




function Apply-Rank12Boost {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _B([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } else { $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue; _B 'SystemResponsiveness'
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue; _B 'NetworkThrottlingIndex'
            foreach ($t in @('Games','Low Latency','Audio','Capture','Playback','Window Manager','DisplayPostProcessing','Distribution','Pro Audio')) {
                $tp = Join-Path $mm ("Tasks\" + $t)
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $tp -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null; _B ("GPUPriority_" + $t)
                New-ItemProperty -Path $tp -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null; _B ("Priority_" + $t)
                New-ItemProperty -Path $tp -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            }
            $mem = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
            if (-not (Test-Path $mem)) { New-Item -Path $mem -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{DisablePagingExecutive=1;LargeSystemCache=0;FeatureSettings=1;FeatureSettingsOverride=3;FeatureSettingsOverrideMask=3}.GetEnumerator()) {
                New-ItemProperty -Path $mem -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $mem -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue; _B $kv.Key
            }
            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _B 'PowerThrottlingOff'
            $mou = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 16 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -Value 16 -Type DWord -Force -EA SilentlyContinue; _B 'MouseDataQueueSize'
            $mouse = 'HKCU:\Control Panel\Mouse'
            if (-not (Test-Path $mouse)) { New-Item -Path $mouse -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mouse -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null; _B 'MouseSpeed'
            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null; _B 'MouseThreshold1'
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null; _B 'MouseThreshold2'
            $desk = 'HKCU:\Control Panel\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $desk -Name 'MenuShowDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null; _B 'MenuShowDelay'
            New-ItemProperty -Path $desk -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _B 'ForegroundLockTimeout'
            $gfx = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
            if (-not (Test-Path $gfx)) { New-Item -Path $gfx -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gfx -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null; _B 'HwSchMode'
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _B 'GlobalTimerResolutionRequests'
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _B 'disabledynamictick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _B 'useplatformtick'
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1; _B 'tscsyncpolicy'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; SackOpts=1; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; MaxUserPort=65534
                TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2
                KeepAliveTime=300000; KeepAliveInterval=1000
                MaxFreeTcbs=16000; MaxHashTableSize=65536
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _B $kv.Key
            }
            $ifc = 0
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                    $ifc++
                }
            }
            if ($ifc -gt 0) { _B 'TcpInterfaces' }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _B $kv.Key
            }
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue; _B 'NonBestEffortLimit'
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue; _B 'NetworkThrottlingIndex'
            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue; _B 'Ndu_Start'
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*RSS','1'),@('*ReceiveBuffers','512'),@('*TransmitBuffers','512'),
                        @('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                }
                _B 'NIC'
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _B ($a[-1]) } catch {}
            }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1; _B 'flushdns' } catch {}
        } catch {}
    }
}


function Apply-SyncProjectExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    # Values from SyncProject.ps1 (rank 2) — aggressive net/input/system

    if ($Mode -in @('Setting','All')) {
        try {
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
            $games = Join-Path $mm 'Tasks\Games'
            if (-not (Test-Path $games)) { New-Item -Path $games -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $games -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'MMCSS' }

            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'PowerThrottlingOff' }

            $gfx = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
            if (-not (Test-Path $gfx)) { New-Item -Path $gfx -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gfx -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gfx -Name 'TdrDelay' -PropertyType DWord -Value 60 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'HAGS' }

            # SyncProject mouse queue default 100 (safe); keyboard 10 — UserLocked may override later
            $mou = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 100 -Force -EA SilentlyContinue | Out-Null
            $kbd = 'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters'
            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDataQueueSize' -PropertyType DWord -Value 10 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'InputQueues' }

            $pc = 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl'
            if (-not (Test-Path $pc)) { New-Item -Path $pc -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pc -Name 'Win32PrioritySeparation' -PropertyType DWord -Value ([uint32]0xFA322A) -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Win32Priority' }

            $gcs = 'HKCU:\System\GameConfigStore'
            if (-not (Test-Path $gcs)) { New-Item -Path $gcs -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gcs -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $gdvr = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR'
            if (-not (Test-Path $gdvr)) { New-Item -Path $gdvr -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gdvr -Name 'AppCaptureEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'GameDVR_Off' }

            $desk = 'HKCU:\Control Panel\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $desk -Name 'MenuShowDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            $mouse = 'HKCU:\Control Panel\Mouse'
            if (-not (Test-Path $mouse)) { New-Item -Path $mouse -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mouse -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null

            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'BCDTimer' }
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $tp -Name 'TcpTimedWaitDelay' -PropertyType DWord -Value 30 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $tp -Name 'TcpTimedWaitDelay' -Value 30 -Type DWord -Force -EA SilentlyContinue
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'TcpTimedWait' }

            $ifRoot = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
            if (Test-Path $ifRoot) {
                Get-ChildItem $ifRoot -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                }
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'NoNagle' }

            foreach ($nduPath in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu',
                'HKLM:\SYSTEM\ControlSet001\Services\Ndu'
            )) {
                if (-not (Test-Path $nduPath)) { New-Item -Path $nduPath -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $nduPath -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $nduPath -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Ndu' }

            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'QoSReserve' }

            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null

            foreach ($a in @(
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'TcpGlobal' }

            # Adapter power / flow control / RSS (best effort)
            try {
                Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
                    try { Disable-NetAdapterPowerManagement -Name $_.Name -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Energy-Efficient Ethernet' -DisplayValue 'Disabled' -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Flow Control' -DisplayValue 'Disabled' -EA SilentlyContinue } catch {}
                    try { Enable-NetAdapterRss -Name $_.Name -EA SilentlyContinue } catch {}
                }
                if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'AdapterTune' }
            } catch {}

            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'flushdns' }
        } catch {}
    }
}




function Apply-DenseExtra {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _D([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            $settingRegs = @(
                # priority / memory / kernel
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePagingExecutive',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','LargeSystemCache',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','SecondLevelDataCache',1024),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','IoPageLockLimit',983040),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','ClearPageFileAtShutdown',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettings',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverride',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverrideMask',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','DistributeTimers',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager','HeapDeCommitFreeBlockThreshold',0),
                # power
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','EnergyEstimationEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','CsEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','HibernateEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','PlatformAoAcOverride',0),
                # graphics
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrLevel',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDelay',60),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDdiDelay',60),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','DpiMapIommuController',0),
                # input queues
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',16),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',10),
                # services
                @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','Start',4),
                @('HKLM:\SYSTEM\ControlSet001\Services\Ndu','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\SysMain','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\WSearch','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\DiagTrack','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\dmwappushservice','Start',4),
                # multimedia
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','AlwaysOn',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NoLazyMode',1),
                # policy
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search','AllowCortana',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent','DisableWindowsConsumerFeatures',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent','DisableSoftLanding',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching','SearchOrderConfig',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisableLastAccessUpdate',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisable8dot3NameCreation',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','LongPathsEnabled',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl','AutoReboot',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System','DisableStartupSound',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\WMI\Autologger\Diagtrack-Listener','Start',0),
                # IFEO / scheduling related
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','IoPriority',3)
            )
            foreach ($row in $settingRegs) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _D $n
            }
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            foreach ($t in @('Games','Low Latency','Audio','Capture','Playback','Window Manager','DisplayPostProcessing','Distribution','Pro Audio','Instrument','Camera','Communications')) {
                $tp = Join-Path $mm ("Tasks\" + $t)
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
                foreach ($kv in @{'GPU Priority'=8;'Priority'=6;'Clock Rate'=10000;'Affinity'=0}.GetEnumerator()) {
                    New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                    _D ($t + '_' + ($kv.Key -replace ' ',''))
                }
                foreach ($kv in @{'Scheduling Category'='High';'SFIO Priority'='High';'Latency Sensitive'='True';'Background Only'='False'}.GetEnumerator()) {
                    New-ItemProperty -Path $tp -Name $kv.Key -PropertyType String -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                }
            }
            $hkcu = @(
                @('HKCU:\Control Panel\Mouse','MouseSpeed','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold1','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold2','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardDelay','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardSpeed','31'),
                @('HKCU:\Control Panel\Desktop','MenuShowDelay','0'),
                @('HKCU:\Control Panel\Desktop','AutoEndTasks','1'),
                @('HKCU:\Control Panel\Desktop','HungAppTimeout','1000'),
                @('HKCU:\Control Panel\Desktop','WaitToKillAppTimeout','2000'),
                @('HKCU:\Control Panel\Desktop','LowLevelHooksTimeout','1000'),
                @('HKCU:\Control Panel\Desktop','WaitToKillServiceTimeout','2000')
            )
            foreach ($row in $hkcu) {
                if (-not (Test-Path $row[0])) { New-Item -Path $row[0] -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $row[0] -Name $row[1] -PropertyType String -Value $row[2] -Force -EA SilentlyContinue | Out-Null
                _D $row[1]
            }
            New-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _D 'ForegroundLockTimeout'
            foreach ($path in @('HKCU:\System\GameConfigStore','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR','HKCU:\Software\Microsoft\GameBar')) {
                if (-not (Test-Path $path)) { New-Item -Path $path -Force -EA SilentlyContinue | Out-Null }
            }
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _D 'GameDVR_Enabled'
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null; _D 'GameDVR_FSEBehaviorMode'
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_HonorUserFSEBehaviorMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _D 'GameDVR_HonorUserFSEBehaviorMode'
            New-ItemProperty -Path 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR' -Name 'AppCaptureEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _D 'AppCaptureEnabled'
            New-ItemProperty -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AutoGameModeEnabled' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _D 'AutoGameModeEnabled'
            New-ItemProperty -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AllowAutoGameMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _D 'AllowAutoGameMode'
            $ex = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
            if (-not (Test-Path $ex)) { New-Item -Path $ex -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{TaskbarAnimations=0;ListviewAlphaSelect=0;ListviewShadow=0;IconsOnly=0;TaskbarMn=0}.GetEnumerator()) {
                New-ItemProperty -Path $ex -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null; _D $kv.Key
            }
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _D 'bcd_disabledynamictick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _D 'bcd_useplatformtick'
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1; _D 'bcd_tscsyncpolicy'
            try { $null = & powercfg.exe /hibernate off 2>&1; _D 'hibernate_off' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1; _D 'PROCTHROTTLEMIN' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1; _D 'PROCTHROTTLEMAX' } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1; _D 'powercfg_active' } catch {}
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            $tcpMap = @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                Tcp1323Opts=1; EnableRSS=1; EnableDCA=1; EnableWsd=0
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpFinWait2Delay=30
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                MaxFreeTcbs=16000; MaxHashTableSize=65536; TcpUseRFC1122UrgentPointer=0
                DisableTaskOffload=0; EnableICMPRedirect=0; PerformRouterDiscovery=0
                TcpMaxSendFree=65535; NumForwardPackets=0; ForwardBroadcasts=0
                IPEnableRouter=0; DeadGWDetectDefault=0
            }
            foreach ($kv in $tcpMap.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _D $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\PersistentRoutes'
            )) {
                if (-not (Test-Path $root)) { continue }
                if ($root -match 'PersistentRoutes') { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($n in @('TcpAckFrequency','TCPNoDelay','TcpDelAckTicks')) {
                        $val = if ($n -eq 'TcpDelAckTicks') { 0 } else { 1 }
                        New-ItemProperty -Path $_.PSPath -Name $n -PropertyType DWord -Value $val -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $n -Value $val -Type DWord -Force -EA SilentlyContinue
                    }
                    _D 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
                DoNotHoldNicBuffers=1; IgnorePushBitOnReceives=0; NonBlockingSendSpecialBuffering=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _D $kv.Key
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                MaxNegativeCacheTtl=0; NegativeCacheTime=0; NetFailureCacheTime=0
                MaxCacheTtl=86400; MaxSOACacheTtl=300; CacheHashTableBucketSize=1
                CacheHashTableSize=384; MaxCacheEntryTtlLimit=86400
            }.GetEnumerator()) {
                New-ItemProperty -Path $dns -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $dns -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _D $kv.Key
            }
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _D 'NonBestEffortLimit'
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null; _D 'NetworkThrottlingIndex'
            foreach ($ndu in @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','HKLM:\SYSTEM\ControlSet001\Services\Ndu')) {
                if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null; _D 'Ndu_Start'
            }
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','4'),
                        @('*ReceiveBuffers','512'),@('*TransmitBuffers','512'),
                        @('*LsoV1IPv4','0'),@('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),
                        @('*TCPChecksumOffloadIPv4','0'),@('*UDPChecksumOffloadIPv4','0'),
                        @('*IPChecksumOffloadIPv4','0'),@('*SpeedDuplex','0'),@('ITR','0'),
                        @('*PriorityVLANTag','0'),@('*PtpHardwareTimestamp','0'),
                        @('*JumboPacket','1514'),@('*ReceiveSideScaling','1')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                    _D 'NIC'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','global','nonbesteffortlimit=0'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _D ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1; _D 'flushdns' } catch {}
            try {
                Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
                    try { Disable-NetAdapterPowerManagement -Name $_.Name -EA SilentlyContinue; _D 'AdapterPowerOff' } catch {}
                    try { Enable-NetAdapterRss -Name $_.Name -EA SilentlyContinue; _D 'AdapterRSS' } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Flow Control' -DisplayValue 'Disabled' -EA SilentlyContinue; _D 'FlowControlOff' } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Energy-Efficient Ethernet' -DisplayValue 'Disabled' -EA SilentlyContinue; _D 'EEE_Off' } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Interrupt Moderation' -DisplayValue 'Disabled' -EA SilentlyContinue; _D 'ITR_Off' } catch {}
                }
            } catch {}
        } catch {}
    }
}



function Apply-FlowGpedit {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _G([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # Flow Gpdit.txt (registry equivalents of gpedit.msc) — max
    # FLSB / Sync run later and win on conflicts

    if ($Mode -in @('Setting','All','Network')) {
        try {
            # Computer Config > Admin Templates > Network > QoS Packet Scheduler > Limit reservable bandwidth = 0
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _G 'GPO_QoS_Bandwidth0'

            # Computer Config > Admin Templates > System > Power Management > Power Throttling Settings > Turn off Power Throttling
            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -Value 1 -Type DWord -Force -EA SilentlyContinue
            $ptPol = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell'
            # policy path for power throttling
            $ptPol2 = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Power\PowerThrottling'
            if (-not (Test-Path $ptPol2)) { New-Item -Path $ptPol2 -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ptPol2 -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ptPol2 -Name 'PowerThrottlingOff' -Value 1 -Type DWord -Force -EA SilentlyContinue
            _G 'GPO_PowerThrottlingOff'

            # Computer Config > Admin Templates > Windows Components > Delivery Optimization > Download Mode = Bypass (100)
            $do = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization'
            if (-not (Test-Path $do)) { New-Item -Path $do -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $do -Name 'DODownloadMode' -PropertyType DWord -Value 100 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $do -Name 'DODownloadMode' -Value 100 -Type DWord -Force -EA SilentlyContinue
            _G 'GPO_DO_Bypass100'

            try { $null = & gpupdate.exe /force 2>&1 } catch {}
            _G 'gpupdate'
        } catch {}
    }
}



function Apply-FlsbSyncGpeditWin {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _G([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # FLSB + Sync win: re-assert gpedit max after Flow
    if ($Mode -in @('Setting','All','Network')) {
        try {
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _G 'FLSB_Sync_QoS0'

            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -Value 1 -Type DWord -Force -EA SilentlyContinue
            $ptPol2 = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Power\PowerThrottling'
            if (-not (Test-Path $ptPol2)) { New-Item -Path $ptPol2 -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ptPol2 -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _G 'FLSB_Sync_PowerThrottleOff'

            $do = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization'
            if (-not (Test-Path $do)) { New-Item -Path $do -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $do -Name 'DODownloadMode' -PropertyType DWord -Value 100 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $do -Name 'DODownloadMode' -Value 100 -Type DWord -Force -EA SilentlyContinue
            _G 'FLSB_Sync_DO_Bypass'
        } catch {}
    }
}



function Apply-UltraMaxPack {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _U([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            # Extreme responsiveness / latency
            $regs = @(
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','AlwaysOn',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NoLazyMode',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ8Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ16Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePagingExecutive',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','LargeSystemCache',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','SecondLevelDataCache',1024),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','IoPageLockLimit',983040),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettings',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverride',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverrideMask',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','DistributeTimers',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','SerializeTimerExpiration',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','EnergyEstimationEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','CsEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','HibernateEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrLevel',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDelay',60),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDdiDelay',60),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',16),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',10),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','Start',4),
                @('HKLM:\SYSTEM\ControlSet001\Services\Ndu','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\SysMain','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\WSearch','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\DiagTrack','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\dmwappushservice','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\WerSvc','Start',4),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games','GPU Priority',8),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games','Priority',6),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games','Clock Rate',10000),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Low Latency','GPU Priority',8),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Low Latency','Priority',6),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Low Latency','Clock Rate',10000),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_b2189_GTAProcess.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_b2189_GTAProcess.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisableLastAccessUpdate',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisable8dot3NameCreation',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','LongPathsEnabled',1)
            )
            foreach ($row in $regs) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _U $n
            }
            foreach ($t in @('Games','Low Latency','Audio','Capture','Playback','Window Manager','DisplayPostProcessing','Distribution','Pro Audio','Instrument','Camera','Communications')) {
                $tp = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\$t"
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $tp -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
                _U ("MMCSS_" + $t)
            }
            $hkcu = @(
                @('HKCU:\Control Panel\Mouse','MouseSpeed','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold1','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold2','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardDelay','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardSpeed','31'),
                @('HKCU:\Control Panel\Desktop','MenuShowDelay','0'),
                @('HKCU:\Control Panel\Desktop','AutoEndTasks','1'),
                @('HKCU:\Control Panel\Desktop','HungAppTimeout','1000'),
                @('HKCU:\Control Panel\Desktop','WaitToKillAppTimeout','2000'),
                @('HKCU:\Control Panel\Desktop','LowLevelHooksTimeout','1000'),
                @('HKCU:\Control Panel\Desktop','WaitToKillServiceTimeout','2000')
            )
            foreach ($row in $hkcu) {
                if (-not (Test-Path $row[0])) { New-Item -Path $row[0] -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $row[0] -Name $row[1] -PropertyType String -Value $row[2] -Force -EA SilentlyContinue | Out-Null
                _U $row[1]
            }
            New-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _U 'ForegroundLockTimeout'
            foreach ($p in @('HKCU:\System\GameConfigStore','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR','HKCU:\Software\Microsoft\GameBar')) {
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
            }
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _U 'GameDVR_Enabled'
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null; _U 'GameDVR_FSEBehaviorMode'
            New-ItemProperty -Path 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR' -Name 'AppCaptureEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _U 'AppCaptureEnabled'
            New-ItemProperty -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AutoGameModeEnabled' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _U 'AutoGameModeEnabled'
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _U 'bcd_disabledynamictick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _U 'bcd_useplatformtick'
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1; _U 'bcd_tscsyncpolicy'
            try { $null = & powercfg.exe /hibernate off 2>&1; _U 'hibernate_off' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1; _U 'PROCTHROTTLEMIN' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1; _U 'PROCTHROTTLEMAX' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100 2>&1; _U 'CPMINCORES' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMAXCORES 100 2>&1; _U 'CPMAXCORES' } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1; _U 'powercfg_active' } catch {}
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            $tcp = @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                Tcp1323Opts=1; EnableRSS=1; EnableDCA=1; EnableWsd=0
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpFinWait2Delay=30
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                MaxFreeTcbs=16000; MaxHashTableSize=65536; TcpUseRFC1122UrgentPointer=0
                DisableTaskOffload=0; EnableICMPRedirect=0; PerformRouterDiscovery=0
                TcpMaxSendFree=65535; IPEnableRouter=0
            }
            foreach ($kv in $tcp.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _U $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($n in @('TcpAckFrequency','TCPNoDelay','TcpDelAckTicks')) {
                        $val = if ($n -eq 'TcpDelAckTicks') { 0 } else { 1 }
                        New-ItemProperty -Path $_.PSPath -Name $n -PropertyType DWord -Value $val -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $n -Value $val -Type DWord -Force -EA SilentlyContinue
                    }
                    _U 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
                DoNotHoldNicBuffers=1; NonBlockingSendSpecialBuffering=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _U $kv.Key
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                MaxNegativeCacheTtl=0; NegativeCacheTime=0; NetFailureCacheTime=0
                MaxCacheTtl=86400; MaxSOACacheTtl=300
            }.GetEnumerator()) {
                New-ItemProperty -Path $dns -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $dns -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _U $kv.Key
            }
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _U 'NonBestEffortLimit'
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null; _U 'NetworkThrottlingIndex'
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','8'),
                        @('*ReceiveBuffers','1024'),@('*TransmitBuffers','1024'),
                        @('*LsoV1IPv4','0'),@('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),
                        @('*TCPChecksumOffloadIPv4','0'),@('*UDPChecksumOffloadIPv4','0'),
                        @('*IPChecksumOffloadIPv4','0'),@('ITR','0'),@('*PriorityVLANTag','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                    _U 'NIC_Ultra'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','global','nonbesteffortlimit=0'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _U ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1; _U 'flushdns' } catch {}
        } catch {}
    }
}



