                @('HKLM:\SYSTEM\CurrentControlSet\Services\MapsBroker','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\RetailDemo','Start',4),
                # Policy
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization','DODownloadMode',100),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search','AllowCortana',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent','DisableWindowsConsumerFeatures',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent','DisableSoftLanding',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\System','EnableActivityFeed',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\System','PublishUserActivities',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching','SearchOrderConfig',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisableLastAccessUpdate',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisable8dot3NameCreation',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','LongPathsEnabled',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl','AutoReboot',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System','DisableStartupSound',1),
                # FiveM / GTA process priority
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_GTAProcess.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_GTAProcess.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_ChromeBrowser.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_ChromeBrowser.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_b2189_GTAProcess.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_b2189_GTAProcess.exe\PerfOptions','IoPriority',3)
            )
            foreach ($row in $R) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
