            # MMCSS all tasks max
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            foreach ($t in @('Games','Low Latency','Audio','Capture','Playback','Window Manager','DisplayPostProcessing','Distribution','Pro Audio','Instrument','Camera','Communications')) {
