                New-ItemProperty -Path $tp -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
                _G ("God_" + $t)
            }
            # HKCU input / desktop
            foreach ($row in @(
                @('HKCU:\Control Panel\Mouse','MouseSpeed','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold1','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold2','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardDelay','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardSpeed','31'),
                @('HKCU:\Control Panel\Desktop','MenuShowDelay','0'),
                @('HKCU:\Control Panel\Desktop','AutoEndTasks','1'),
                @('HKCU:\Control Panel\Desktop','HungAppTimeout','1000'),
                @('HKCU:\Control Panel\Desktop','WaitToKillAppTimeout','2000'),
                @('HKCU:\Control Panel\Desktop','LowLevelHooksTimeout','1000'),
                @('HKCU:\Control Panel\Desktop','WaitToKillServiceTimeout','2000')
            )) {
                if (-not (Test-Path $row[0])) { New-Item -Path $row[0] -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $row[0] -Name $row[1] -PropertyType String -Value $row[2] -Force -EA SilentlyContinue | Out-Null
                _G $row[1]
            }
            New-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _G 'ForegroundLockTimeout'
            foreach ($p in @('HKCU:\System\GameConfigStore','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR','HKCU:\Software\Microsoft\GameBar')) {
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
            }
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _G 'GameDVR_Enabled'
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null; _G 'GameDVR_FSEBehaviorMode'
            New-ItemProperty -Path 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR' -Name 'AppCaptureEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _G 'AppCaptureEnabled'
            New-ItemProperty -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AutoGameModeEnabled' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _G 'AutoGameModeEnabled'
            New-ItemProperty -Path 'HKCU:\Software\Microsoft\GameBar' -Name 'AllowAutoGameMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _G 'AllowAutoGameMode'
            # BCD + power
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _G 'bcd_disabledynamictick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _G 'bcd_useplatformtick'
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1; _G 'bcd_tscsyncpolicy'
            try { $null = & powercfg.exe /hibernate off 2>&1; _G 'hibernate_off' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1; _G 'PROCTHROTTLEMIN' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1; _G 'PROCTHROTTLEMAX' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100 2>&1; _G 'CPMINCORES' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMAXCORES 100 2>&1; _G 'CPMAXCORES' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PERFBOOSTMODE 2 2>&1; _G 'PERFBOOSTMODE' } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR IDLEDISABLE 1 2>&1; _G 'IDLEDISABLE' } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1; _G 'powercfg_active' } catch {}
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                Tcp1323Opts=1; EnableRSS=1; EnableDCA=1; EnableWsd=0
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpFinWait2Delay=30
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                MaxFreeTcbs=16000; MaxHashTableSize=65536
                DisableTaskOffload=0; EnableICMPRedirect=0; PerformRouterDiscovery=0
                TcpMaxSendFree=65535; IPEnableRouter=0; DeadGWDetectDefault=0
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _G $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($n in @('TcpAckFrequency','TCPNoDelay','TcpDelAckTicks')) {
                        $val = if ($n -eq 'TcpDelAckTicks') { 0 } else { 1 }
                        New-ItemProperty -Path $_.PSPath -Name $n -PropertyType DWord -Value $val -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $n -Value $val -Type DWord -Force -EA SilentlyContinue
                    }
                    _G 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
                DoNotHoldNicBuffers=1; NonBlockingSendSpecialBuffering=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _G $kv.Key
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                MaxNegativeCacheTtl=0; NegativeCacheTime=0; NetFailureCacheTime=0
                MaxCacheTtl=86400; MaxSOACacheTtl=300; CacheHashTableBucketSize=1
                CacheHashTableSize=384
            }.GetEnumerator()) {
                New-ItemProperty -Path $dns -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $dns -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _G $kv.Key
            }
            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _G 'NonBestEffortLimit'
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null; _G 'NetworkThrottlingIndex'
            foreach ($ndu in @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','HKLM:\SYSTEM\ControlSet001\Services\Ndu')) {
                if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null; _G 'Ndu_Start'
            }
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','8'),
                        @('*ReceiveBuffers','1024'),@('*TransmitBuffers','1024'),
                        @('*LsoV1IPv4','0'),@('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),
                        @('*TCPChecksumOffloadIPv4','0'),@('*UDPChecksumOffloadIPv4','0'),
                        @('*IPChecksumOffloadIPv4','0'),@('ITR','0'),@('*PriorityVLANTag','0'),
                        @('*ReceiveSideScaling','1')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                    _G 'NIC_God'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','global','nonbesteffortlimit=0'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _G ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1; _G 'flushdns' } catch {}
            try {
                Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
                    try { Disable-NetAdapterPowerManagement -Name $_.Name -EA SilentlyContinue; _G 'AdapterPowerOff' } catch {}
                    try { Enable-NetAdapterRss -Name $_.Name -EA SilentlyContinue; _G 'AdapterRSS' } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Flow Control' -DisplayValue 'Disabled' -EA SilentlyContinue; _G 'FlowControlOff' } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Energy-Efficient Ethernet' -DisplayValue 'Disabled' -EA SilentlyContinue; _G 'EEE_Off' } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName 'Interrupt Moderation' -DisplayValue 'Disabled' -EA SilentlyContinue; _G 'ITR_Off' } catch {}
                }
            } catch {}
        } catch {}
    }
}



function Apply-Rank1Seal {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _S([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # Seal aggressive keys after rank1 packs (same direction as Aspas/FLSB/Sync/Flow)

    if ($Mode -in @('Setting','All')) {
        try {
            foreach ($row in @(
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePagingExecutive',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',16),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',10),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','Start',4),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization','DODownloadMode',100),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0)
            )) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _S $n
            }
            $games = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            if (-not (Test-Path $games)) { New-Item -Path $games -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $games -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            _S 'GamesProfile'
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _S 'bcd_disabledynamictick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _S 'bcd_useplatformtick'
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
            _S 'power_max'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnableRSS=1; EnableDCA=1; SackOpts=1; Tcp1323Opts=1
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _S $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                    _S 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _S $kv.Key
            }
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            _S 'NetworkThrottlingIndex'
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','tcp','set','global','nonbesteffortlimit=0')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _S ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
        } catch {}
    }
}



function Apply-JacobExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _J([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # Jacob pack (3++) — rank 1/2 win on conflicts

    if ($Mode -in @('Setting','All')) {
        try {
            # win32P7800.reg / Jacob priority (may be overridden by rank1 FA322A / UserLocked)
            $pc = 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl'
            if (-not (Test-Path $pc)) { New-Item -Path $pc -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pc -Name 'ConvertibleSlateMode' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $pc -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0x26 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $pc -Name 'AVX2PriorityBoost' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $pc -Name 'Win32TimeSlice' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _J 'Jacob_Win32Priority'

            # Mouse/Keyboard queue 0x1E (30) + kbd ThreadPriority 0x1F
            $mou = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 0x1E -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -Value 0x1E -Type DWord -Force -EA SilentlyContinue
            _J 'Jacob_MouseQueue30'

            $kbd = 'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters'
            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDataQueueSize' -PropertyType DWord -Value 0x1E -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $kbd -Name 'KeyboardDataQueueSize' -Value 0x1E -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $kbd -Name 'ThreadPriority' -PropertyType DWord -Value 0x1F -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $kbd -Name 'ConnectMultiplePorts' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $kbd -Name 'SendOutputToAllPorts' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _J 'Jacob_KeyboardQueue30'

            # USB
            $usb = 'HKLM:\SYSTEM\CurrentControlSet\Services\USB'
            if (-not (Test-Path $usb)) { New-Item -Path $usb -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $usb -Name 'DisableSelectiveSuspend' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _J 'Jacob_USB_NoSelectiveSuspend'
            $usbport = 'HKLM:\SYSTEM\CurrentControlSet\Services\Usbport'
            if (-not (Test-Path $usbport)) { New-Item -Path $usbport -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $usbport -Name 'USBPollingRateMaxFrequencyNodlle' -PropertyType DWord -Value 0x3E8 -Force -EA SilentlyContinue | Out-Null
            _J 'Jacob_USBPolling1000'

            # Game mode
            $gm = 'HKCU:\Software\Microsoft\GameBar'
            if (-not (Test-Path $gm)) { New-Item -Path $gm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gm -Name 'ShowGameBar' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gm -Name 'AllowAutoGameMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $gmm = 'HKLM:\SOFTWARE\Microsoft\GameMode'
            if (-not (Test-Path $gmm)) { New-Item -Path $gmm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gmm -Name 'Enabled' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _J 'Jacob_GameMode'

            # Driver update exclusions (EU.reg style)
            foreach ($p in @(
                'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate',
                'HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings'
            )) {
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name 'ExcludeWUDriversInQualityUpdate' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            }
            _J 'Jacob_ExcludeWUDrivers'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            # NoNagle per interface (from setting Jacob.cmd)
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    _J 'Jacob_IF_NoNagle'
                }
            }
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $tp -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _J 'Jacob_Tcp'
        } catch {}
    }
}



function Apply-DektinExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _D([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            foreach ($row in @(
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',42),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ8Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ16Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ17Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePagingExecutive',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','LargeSystemCache',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePageCombining',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverride',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverrideMask',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',16),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',16),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','ThreadPriority',31),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\USB','DisableSelectiveSuspend',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','AlwaysOn',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NoLazyMode',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\FiveM\Parameters','CEFHardwareAcceleration',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','CpuPriorityClass',3)
            )) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _D $n
            }
            foreach ($p in @('HKCU:\System\GameConfigStore','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR')) {
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
            }
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _D 'GameDVR_Enabled'
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _D 'bcd_tick'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; DefaultTTL=64
                EnablePMTUDiscovery=1; TcpTimedWaitDelay=30; DisableTaskOffload=1
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpMaxDataRetransmissions=3
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _D $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    _D 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                DefaultReceiveWindow=65536; DefaultSendWindow=65536
                EnableDynamicBacklog=1; MinimumDynamicBacklog=32; MaximumDynamicBacklog=4096; DynamicBacklogGrowthDelta=16
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                _D $kv.Key
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $dns -Name 'MaxCacheTtl' -PropertyType DWord -Value 86400 -Force -EA SilentlyContinue | Out-Null; _D 'MaxCacheTtl'
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _D 'NonBestEffortLimit'
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','ipv4','set','global','defaultcurhoplimit=64')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _D ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
        } catch {}
    }
}

function Apply-BastienExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _B([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            $gd = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
            if (-not (Test-Path $gd)) { New-Item -Path $gd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gd -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null; _B 'HwSchMode'
            foreach ($p in @('HKCU:\System\GameConfigStore','HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications','HKCU:\SOFTWARE\CitizenFX\FiveM')) {
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
            }
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _B 'GameDVR_Enabled'
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_HonorUserFSEBehaviorMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR' -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _B 'AllowGameDVR'
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' -Name 'AllowTelemetry' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _B 'AllowTelemetry'
            New-ItemProperty -Path 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications' -Name 'GlobalUserDisabled' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _B 'GlobalUserDisabled'
            New-ItemProperty -Path 'HKCU:\SOFTWARE\CitizenFX\FiveM' -Name 'DisableTelemetry' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null; _B 'DisableTelemetry'
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null; _B 'NetworkThrottlingIndex'
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _B 'SystemResponsiveness'
            try { $null = & powercfg.exe /duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 2>&1 } catch {}
            try { $null = & powercfg.exe /setactive e9a42b02-d5df-448d-aa00-03f14749eb61 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
            _B 'Bastien_Power'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $tp -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _B 'Bastien_Tcp'
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    _B 'IF_Tcp'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','timestamps=disabled')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _B ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
            try { $null = & "$env:SystemRoot\System32\netsh.exe" interface ip delete arpcache 2>&1; _B 'arp_cache' } catch {}
        } catch {}
    }
}



function Apply-MoreAggression {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _M([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            $rows = @(
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','AlwaysOn',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NoLazyMode',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ8Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ16Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePagingExecutive',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','LargeSystemCache',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','SecondLevelDataCache',1024),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','IoPageLockLimit',983040),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettings',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverride',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverrideMask',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePageCombining',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','DistributeTimers',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','EnergyEstimationEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','CsEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power','HibernateEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrLevel',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDelay',60),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',16),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',10),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','Start',4),
                @('HKLM:\SYSTEM\ControlSet001\Services\Ndu','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\SysMain','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\WSearch','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\DiagTrack','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\dmwappushservice','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\WerSvc','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\PcaSvc','Start',4),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization','DODownloadMode',100),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisableLastAccessUpdate',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem','NtfsDisable8dot3NameCreation',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\GTA5.exe\PerfOptions','IoPriority',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_GTAProcess.exe\PerfOptions','CpuPriorityClass',3),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_GTAProcess.exe\PerfOptions','IoPriority',3)
            )
            foreach ($row in $rows) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _M $n
            }
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            foreach ($t in @('Games','Low Latency','Audio','Capture','Playback','Window Manager','DisplayPostProcessing','Distribution','Pro Audio')) {
                $tp = Join-Path $mm ("Tasks\" + $t)
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $tp -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
                _M ("MM_" + $t)
            }
            foreach ($row in @(
                @('HKCU:\Control Panel\Mouse','MouseSpeed','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold1','0'),
                @('HKCU:\Control Panel\Mouse','MouseThreshold2','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardDelay','0'),
                @('HKCU:\Control Panel\Keyboard','KeyboardSpeed','31'),
                @('HKCU:\Control Panel\Desktop','MenuShowDelay','0'),
                @('HKCU:\Control Panel\Desktop','AutoEndTasks','1'),
                @('HKCU:\Control Panel\Desktop','HungAppTimeout','1000'),
                @('HKCU:\Control Panel\Desktop','WaitToKillAppTimeout','2000')
            )) {
                if (-not (Test-Path $row[0])) { New-Item -Path $row[0] -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $row[0] -Name $row[1] -PropertyType String -Value $row[2] -Force -EA SilentlyContinue | Out-Null
                _M $row[1]
            }
            New-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _M 'ForegroundLockTimeout'
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _M 'bcd_disabledynamictick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _M 'bcd_useplatformtick'
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1; _M 'bcd_tscsyncpolicy'
            try { $null = & powercfg.exe /hibernate off 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMAXCORES 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PERFBOOSTMODE 2 2>&1 } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
            _M 'power_max'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; SackOpts=1; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; MaxUserPort=65534
                TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2
                KeepAliveTime=300000; KeepAliveInterval=1000
                MaxFreeTcbs=16000; MaxHashTableSize=65536
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _M $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($n in @('TcpAckFrequency','TCPNoDelay','TcpDelAckTicks')) {
                        $val = if ($n -eq 'TcpDelAckTicks') { 0 } else { 1 }
                        New-ItemProperty -Path $_.PSPath -Name $n -PropertyType DWord -Value $val -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $n -Value $val -Type DWord -Force -EA SilentlyContinue
                    }
                    _M 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
                DoNotHoldNicBuffers=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _M $kv.Key
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{ MaxNegativeCacheTtl=0; NegativeCacheTime=0; NetFailureCacheTime=0; MaxCacheTtl=86400 }.GetEnumerator()) {
                New-ItemProperty -Path $dns -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                _M $kv.Key
            }
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _M 'NonBestEffortLimit'
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null; _M 'NetworkThrottlingIndex'
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','8'),
                        @('*ReceiveBuffers','1024'),@('*TransmitBuffers','1024'),
                        @('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                    _M 'NIC'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','nonbesteffortlimit=0'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _M ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1; _M 'flushdns' } catch {}
        } catch {}
    }
}



function Apply-BTXExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _T([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # BTX Setting (no FilterKeys)

    if ($Mode -in @('Setting','All')) {
        try {
            foreach ($row in @(
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy','LetAppsRunInBackground',2),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\WcmSvc\GroupPolicy','fMinimizeConnections',2),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',38),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization','DODownloadMode',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',20),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',100)
            )) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _T $n
            }
            $game = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            if (-not (Test-Path $game)) { New-Item -Path $game -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $game -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            _T 'GamesProfile'
            if (-not (Test-Path 'HKCU:\System\GameConfigStore')) { New-Item -Path 'HKCU:\System\GameConfigStore' -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _T 'GameDVR_Enabled'
            New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
            _T 'Keyboard'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{ Tcp1323Opts=1; SackOpts=1; TcpTimedWaitDelay=30; MaxUserPort=65534; TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0 }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _T $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                    _T 'IF_Tcp'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','nonsackrttresiliency=disabled'),
                @('int','tcp','set','supplemental','Template=Internet','icw=10','minrto=300')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _T ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
            try {
                Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
                    foreach ($kw in @('*FlowControl','*InterruptModeration','*EEE','*SelectiveSuspend','EnableGreenEthernet')) {
                        try { Set-NetAdapterAdvancedProperty -Name $_.Name -RegistryKeyword $kw -RegistryValue 0 -NoRestart -EA SilentlyContinue } catch {}
                    }
                    _T 'BTX_NIC'
                }
            } catch {}
        } catch {}
    }
}

function Apply-BangbathExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _B([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # bangbathV2 aggressive subset

    if ($Mode -in @('Setting','All')) {
        try {
            foreach ($row in @(
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDelay',10),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',38),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ8Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','DistributeTimers',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',20),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',100)
            )) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _B $n
            }
            if (-not (Test-Path 'HKCU:\System\GameConfigStore')) { New-Item -Path 'HKCU:\System\GameConfigStore' -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _B 'GameDVR_Enabled'
            New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            _B 'MouseAccelOff'
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _B 'bcd_tick'
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
            _B 'Bang_Power'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{ TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0 }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _B $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                    _B 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $afd -Name 'DefaultReceiveWindow' -PropertyType DWord -Value 262144 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $afd -Name 'DefaultSendWindow' -PropertyType DWord -Value 262144 -Force -EA SilentlyContinue | Out-Null
            _B 'AFD_Window'
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $dns -Name 'NegativeCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null; _B 'NegativeCacheTime'
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','autotuninglevel=normal')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _B ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
        } catch {}
    }
}



function Apply-Rank1Dense {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _R([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    if ($Mode -in @('Setting','All')) {
        try {
            $rows = @(
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','AlwaysOn',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NoLazyMode',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ8Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ16Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePagingExecutive',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','LargeSystemCache',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePageCombining',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverride',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverrideMask',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','DistributeTimers',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrLevel',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDelay',60),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',20),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',20),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','Start',4),
                @('HKLM:\SYSTEM\ControlSet001\Services\Ndu','Start',4),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization','DODownloadMode',100)
            )
            foreach ($row in $rows) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _R $n
            }
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            foreach ($t in @('Games','Low Latency','Audio','Pro Audio','DisplayPostProcessing','Window Manager')) {
                $tp = Join-Path $mm ("Tasks\" + $t)
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $tp -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
                _R ("MM_" + $t)
            }
            foreach ($exe in @('FiveM.exe','GTA5.exe','FiveM_GTAProcess.exe','FiveM_b3095_GTAProcess.exe','FiveM_b3258_GTAProcess.exe')) {
                $ipe = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe\PerfOptions"
                if (-not (Test-Path $ipe)) { New-Item -Path $ipe -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $ipe -Name 'CpuPriorityClass' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $ipe -Name 'IoPriority' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                _R ("IFEO_" + $exe)
            }
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _R 'bcd_tick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _R 'bcd_platform'
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
            _R 'power_max'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; SackOpts=1; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; MaxUserPort=65534
                TcpMaxDataRetransmissions=3; KeepAliveTime=300000; KeepAliveInterval=1000
                SynAttackProtect=0; EnableDeadGWDetect=0
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _R $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($pair in @(@('TcpAckFrequency',1),@('TCPNoDelay',1),@('TcpDelAckTicks',0))) {
                        New-ItemProperty -Path $_.PSPath -Name $pair[0] -PropertyType DWord -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $pair[0] -Value $pair[1] -Type DWord -Force -EA SilentlyContinue
                    }
                    _R 'IF_Tcp'
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                DefaultReceiveWindow=262144; DefaultSendWindow=262144
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                EnableDynamicBacklog=1; MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _R $kv.Key
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{ MaxNegativeCacheTtl=0; NegativeCacheTime=0; NetFailureCacheTime=0; MaxCacheTtl=86400 }.GetEnumerator()) {
                New-ItemProperty -Path $dns -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                _R $kv.Key
            }
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _R 'NonBestEffortLimit'
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','8'),
                        @('*ReceiveBuffers','2048'),@('*TransmitBuffers','2048'),
                        @('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                    _R 'NIC'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _R ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
        } catch {}
    }
}



function Apply-AspasKeySeal {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _S([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    if ($Mode -notin @('Setting','All')) { return }
    try {
        # Aspas V2 values (not locked — this seal makes them win over TOP/3++)
        foreach ($pc in @(
            'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl',
            'HKLM:\SYSTEM\ControlSet001\Control\PriorityControl',
            'HKLM:\SYSTEM\ControlSet002\Control\PriorityControl'
        )) {
            if (-not (Test-Path $pc)) { New-Item -Path $pc -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pc -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0x26 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $pc -Name 'Win32PrioritySeparation' -Value 0x26 -Type DWord -Force -EA SilentlyContinue
        }
        _S 'Win32PrioritySeparation'

        foreach ($kbd in @(
            'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters',
            'HKLM:\SYSTEM\ControlSet001\Services\kbdclass\Parameters'
        )) {
            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDataQueueSize' -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $kbd -Name 'KeyboardDataQueueSize' -Value 20 -Type DWord -Force -EA SilentlyContinue
        }
        _S 'KeyboardDataQueueSize'

        foreach ($mou in @(
            'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters',
            'HKLM:\SYSTEM\ControlSet001\Services\mouclass\Parameters'
        )) {
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -Value 20 -Type DWord -Force -EA SilentlyContinue
        }
        _S 'MouseDataQueueSize'
    } catch {}
}



function Apply-StickHard {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _H([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    # dual-write helper: New + Set on path
    function Set-DWord([string]$Path,[string]$Name,[int]$Value) {
        try {
            if (-not (Test-Path -LiteralPath $Path)) { New-Item -Path $Path -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -LiteralPath $Path -Name $Name -PropertyType DWord -Value $Value -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -Type DWord -Force -EA SilentlyContinue
            _H $Name
            return $true
        } catch { return $false }
    }

    if ($Mode -in @('Setting','All')) {
        try {
            # memory / kernel / timer
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' 'DisablePagingExecutive' 1
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' 'LargeSystemCache' 0
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' 'DisablePageCombining' 1
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' 'FeatureSettingsOverride' 3
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' 'FeatureSettingsOverrideMask' 3
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel' 'GlobalTimerResolutionRequests' 1
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel' 'DistributeTimers' 1
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel' 'DpcTimeout' 0
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel' 'DpcWatchdogPeriod' 0
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' 'PowerThrottlingOff' 1
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode' 2
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'TdrLevel' 0
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'TdrDelay' 60
            Set-DWord 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'SystemResponsiveness' 0
            Set-DWord 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'NetworkThrottlingIndex' ([int][uint32]0xFFFFFFFF)
            Set-DWord 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'AlwaysOn' 1
            Set-DWord 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'NoLazyMode' 1
            Set-DWord 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' 'NonBestEffortLimit' 0
            Set-DWord 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR' 'AllowGameDVR' 0
            Set-DWord 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' 'AllowTelemetry' 0
            Set-DWord 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' 'DODownloadMode' 100
            Set-DWord 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Services\SysMain' 'Start' 4
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Services\WSearch' 'Start' 4
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Services\DiagTrack' 'Start' 4
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Services\dmwappushservice' 'Start' 4
            Set-DWord 'HKLM:\SYSTEM\CurrentControlSet\Services\USB' 'DisableSelectiveSuspend' 1
            # MMCSS Games
            $game = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            if (-not (Test-Path $game)) { New-Item -Path $game -Force -EA SilentlyContinue | Out-Null }
            Set-DWord $game 'GPU Priority' 8
            Set-DWord $game 'Priority' 6
            New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            _H 'Games_MMCSS'
            # IFEO
            foreach ($exe in @('FiveM.exe','GTA5.exe','FiveM_GTAProcess.exe')) {
                $ipe = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe\PerfOptions"
                if (-not (Test-Path $ipe)) { New-Item -Path $ipe -Force -EA SilentlyContinue | Out-Null }
                Set-DWord $ipe 'CpuPriorityClass' 3
                Set-DWord $ipe 'IoPriority' 3
            }
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1; _H 'bcd_tick'
            $null = & bcdedit.exe /set useplatformtick yes 2>&1; _H 'bcd_platform'
            try { $null = & powercfg.exe /hibernate off 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMINCORES 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR CPMAXCORES 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
            _H 'power_max'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; SackOpts=1; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; MaxUserPort=65534
                TcpMaxDataRetransmissions=3; KeepAliveTime=300000; KeepAliveInterval=1000
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                TcpMaxDupAcks=2; DisableTaskOffload=0
            }.GetEnumerator()) {
                Set-DWord $tp $kv.Key ([int]$kv.Value)
                Set-DWord 'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters' $kv.Key ([int]$kv.Value)
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    Set-DWord $_.PSPath 'TcpAckFrequency' 1
                    Set-DWord $_.PSPath 'TCPNoDelay' 1
                    Set-DWord $_.PSPath 'TcpDelAckTicks' 0
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            foreach ($kv in @{
                DefaultReceiveWindow=262144; DefaultSendWindow=262144
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                EnableDynamicBacklog=1; MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000
                DynamicBacklogGrowthDelta=10; DoNotHoldNicBuffers=1
            }.GetEnumerator()) {
                Set-DWord $afd $kv.Key ([int]$kv.Value)
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            foreach ($kv in @{ MaxNegativeCacheTtl=0; NegativeCacheTime=0; NetFailureCacheTime=0; MaxCacheTtl=86400 }.GetEnumerator()) {
                Set-DWord $dns $kv.Key ([int]$kv.Value)
            }
            Set-DWord 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' 'NonBestEffortLimit' 0
            Set-DWord 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'NetworkThrottlingIndex' ([int][uint32]0xFFFFFFFF)
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','8'),
                        @('*ReceiveBuffers','2048'),@('*TransmitBuffers','2048'),
                        @('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0'),
                        @('*TCPChecksumOffloadIPv4','0'),@('*UDPChecksumOffloadIPv4','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                    _H 'NIC'
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _H ('netsh_' + ($a[-1] -replace '[^a-zA-Z0-9_]','_')) } catch {}
            }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1; _H 'flushdns' } catch {}
            try {
                Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback|Virtual|Bluetooth' } | ForEach-Object {
                    try { Restart-NetAdapter -Name $_.Name -Confirm:$false -EA SilentlyContinue; _H ('restart_' + $_.Name) } catch {}
                }
            } catch {}
        } catch {}
    }
}



function Apply-DnsCloudflare {
    $ErrorActionPreference = 'SilentlyContinue'
    function _D([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    try {
        $adapters = @(Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback|Virtual|Bluetooth|VPN|Hyper-V|vEthernet' })
        foreach ($a in $adapters) {
            try {
                Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses @('1.1.1.1','1.0.0.1') -EA SilentlyContinue
                _D 'DNS'
            } catch {}
        }
        # also via netsh for legacy
        foreach ($a in $adapters) {
            try {
                $null = & "$env:SystemRoot\System32\netsh.exe" interface ip set dns name="$($a.Name)" static 1.1.1.1 primary 2>&1
                $null = & "$env:SystemRoot\System32\netsh.exe" interface ip add dns name="$($a.Name)" 1.0.0.1 index=2 2>&1
            } catch {}
        }
        try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1; _D 'flushdns' } catch {}
    } catch {}
}



function Apply-ConflictResolve {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _C([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    # Same key from many packs -> write the hardest value once.
    # Aspas V2 still owns Win32 / Keyboard / Mouse via Apply-AspasKeySeal after this.

    if ($Mode -in @('Setting','All')) {
        try {
            $settingBest = @(
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','AlwaysOn',1),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NoLazyMode',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePagingExecutive',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','LargeSystemCache',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','DisablePageCombining',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverride',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management','FeatureSettingsOverrideMask',3),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','GlobalTimerResolutionRequests',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel','DistributeTimers',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrLevel',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','TdrDelay',60),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection','AllowTelemetry',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization','DODownloadMode',100),
                @('HKCU:\System\GameConfigStore','GameDVR_Enabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\SysMain','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\WSearch','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\DiagTrack','Start',4),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\Ndu','Start',4)
            )
            foreach ($row in $settingBest) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _C $n
            }
            $game = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            if (-not (Test-Path $game)) { New-Item -Path $game -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $game -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $game -Name 'GPU Priority' -Value 8 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $game -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $game -Name 'Priority' -Value 6 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            _C 'Games_MMCSS'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $netBest = @{
                TcpAckFrequency = 1
                TCPNoDelay = 1
                TcpDelAckTicks = 0
                TcpTimedWaitDelay = 15
                DefaultTTL = 64
                EnablePMTUDiscovery = 1
                SackOpts = 1
                Tcp1323Opts = 1
                EnableRSS = 1
                EnableDCA = 1
                MaxUserPort = 65534
                TcpMaxDataRetransmissions = 3
                KeepAliveTime = 300000
                KeepAliveInterval = 1000
                SynAttackProtect = 0
                EnableDeadGWDetect = 0
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters'
            )) {
                if (-not (Test-Path $root)) { New-Item -Path $root -Force -EA SilentlyContinue | Out-Null }
                foreach ($kv in $netBest.GetEnumerator()) {
                    New-ItemProperty -Path $root -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $root -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                    _C $kv.Key
                }
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                }
                _C 'Interface_NoNagle'
            }
            $afdBest = @{
                DefaultReceiveWindow = 262144
                DefaultSendWindow = 262144
                FastSendDatagramThreshold = 1500
                FastCopyReceiveThreshold = 1500
                EnableDynamicBacklog = 1
                MinimumDynamicBacklog = 20
                MaximumDynamicBacklog = 20000
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in $afdBest.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _C $kv.Key
            }
            $dnsBest = @{ MaxNegativeCacheTtl = 0; NegativeCacheTime = 0; NetFailureCacheTime = 0 }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in $dnsBest.GetEnumerator()) {
                New-ItemProperty -Path $dns -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $dns -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _C $kv.Key
            }
            if (-not (Test-Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched')) {
                New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Force -EA SilentlyContinue | Out-Null
            }
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _C 'NonBestEffortLimit'
        } catch {}
    }
}



function Set-RegDword {
    param([string]$Path,[string]$Name,[UInt32]$Value)
    $ErrorActionPreference = 'SilentlyContinue'
    try {
        if (-not (Test-Path -LiteralPath $Path)) {
            New-Item -Path $Path -Force -ErrorAction SilentlyContinue | Out-Null
        }
        New-ItemProperty -LiteralPath $Path -Name $Name -PropertyType DWord -Value $Value -Force -ErrorAction SilentlyContinue | Out-Null
        Set-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -Type DWord -Force -ErrorAction SilentlyContinue
        $regPath = $Path -replace '^HKLM:\\','HKLM\' -replace '^HKCU:\\','HKCU\' -replace '^HKLM:','HKLM\' -replace '^HKCU:','HKCU\'
        $null = & "$env:SystemRoot\System32\reg.exe" add $regPath /v $Name /t REG_DWORD /d $Value /f 2>&1
        if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name $Name }
        elseif ($null -ne $script:Ok) { $script:Ok++ }
        return $true
    } catch {
        if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name $Name 'fail' }
        elseif ($null -ne $script:Fail) { $script:Fail++ }
        return $false
    }
}

function Apply-ForceStick {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'

    if ($Mode -in @('Setting','All')) {
        Set-RegDword 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'SystemResponsiveness' 0
        Set-RegDword 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'NetworkThrottlingIndex' ([UInt32]0xFFFFFFFF)
        Set-RegDword 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'AlwaysOn' 1
        Set-RegDword 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'NoLazyMode' 1
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl' 'Win32PrioritySeparation' 0x26
        Set-RegDword 'HKLM:\SYSTEM\ControlSet001\Control\PriorityControl' 'Win32PrioritySeparation' 0x26
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters' 'KeyboardDataQueueSize' 20
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters' 'MouseDataQueueSize' 20
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' 'DisablePagingExecutive' 1
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' 'LargeSystemCache' 0
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel' 'GlobalTimerResolutionRequests' 1
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel' 'DistributeTimers' 1
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' 'PowerThrottlingOff' 1
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode' 2
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'TdrLevel' 0
        Set-RegDword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' 'NonBestEffortLimit' 0
        Set-RegDword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR' 'AllowGameDVR' 0
        Set-RegDword 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0
        Set-RegDword 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu' 'Start' 4
        Set-RegDword 'HKLM:\SYSTEM\ControlSet001\Services\Ndu' 'Start' 4
        $game = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
        if (-not (Test-Path $game)) { New-Item -Path $game -Force -EA SilentlyContinue | Out-Null }
        Set-RegDword $game 'GPU Priority' 8
        Set-RegDword $game 'Priority' 6
        New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
        New-ItemProperty -Path $game -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
        New-ItemProperty -Path $game -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
        if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Games_MMCSS' }
        try { $null = & bcdedit.exe /set disabledynamictick yes 2>&1 } catch {}
        try { $null = & bcdedit.exe /set useplatformtick yes 2>&1 } catch {}
        try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
        try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
        try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
        if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Power_BCD' }
    }

    if ($Mode -in @('Network','All')) {
        $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
        foreach ($kv in @{
            TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
            DefaultTTL=64; EnablePMTUDiscovery=1; SackOpts=1; Tcp1323Opts=1
            EnableRSS=1; EnableDCA=1; MaxUserPort=65534
            TcpMaxDataRetransmissions=3; KeepAliveTime=300000; KeepAliveInterval=1000
            SynAttackProtect=0; EnableDeadGWDetect=0
        }.GetEnumerator()) {
            Set-RegDword $tp $kv.Key ([UInt32]$kv.Value)
            Set-RegDword 'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters' $kv.Key ([UInt32]$kv.Value)
        }
        foreach ($root in @(
            'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
            'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
        )) {
            if (-not (Test-Path $root)) { continue }
            Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                Set-RegDword $_.PSPath 'TcpAckFrequency' 1
                Set-RegDword $_.PSPath 'TCPNoDelay' 1
                Set-RegDword $_.PSPath 'TcpDelAckTicks' 0
            }
        }
        $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
        Set-RegDword $afd 'DefaultReceiveWindow' 262144
        Set-RegDword $afd 'DefaultSendWindow' 262144
        Set-RegDword $afd 'FastSendDatagramThreshold' 1500
        Set-RegDword $afd 'EnableDynamicBacklog' 1
        Set-RegDword $afd 'MinimumDynamicBacklog' 20
        Set-RegDword $afd 'MaximumDynamicBacklog' 20000
        Set-RegDword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' 'NonBestEffortLimit' 0
        Set-RegDword 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'NetworkThrottlingIndex' ([UInt32]0xFFFFFFFF)
        foreach ($a in @(
            @('int','tcp','set','heuristics','disabled'),
            @('int','tcp','set','global','autotuninglevel=normal'),
            @('int','tcp','set','global','rss=enabled'),
            @('int','tcp','set','global','rsc=disabled'),
            @('int','tcp','set','global','timestamps=disabled'),
            @('int','tcp','set','global','ecncapability=disabled'),
            @('int','tcp','set','global','fastopen=enabled'),
            @('int','tcp','set','global','dca=enabled'),
            @('int','tcp','set','global','chimney=disabled'),
            @('int','tcp','set','global','initialRto=1000'),
            @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
            @('int','ipv4','set','global','defaultcurhoplimit=64'),
            @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536')
        )) {
            try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
        }
        if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'netsh' }
        try { Apply-DnsCloudflare } catch {}
        try {
            Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback|Virtual|Bluetooth|VPN' } | ForEach-Object {
                try { Restart-NetAdapter -Name $_.Name -Confirm:$false -EA SilentlyContinue } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'AdapterRestart' }
        } catch {}
        try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
    }
}



function Apply-ProjectPrimeExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _P([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # TOP pack from Project Prime aggressive defaults (FiveM-oriented)
    if ($Mode -in @('Setting','All')) {
        try {
            foreach ($row in @(
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKCU:\System\GameConfigStore','GameDVR_Enabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',20),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',20)
            )) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _P $n
            }
            $game = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            if (-not (Test-Path $game)) { New-Item -Path $game -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $game -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            _P 'Games_MMCSS'
        } catch {}
    }
    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{ TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15; SackOpts=1; Tcp1323Opts=1; EnableRSS=1; MaxUserPort=65534 }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _P $kv.Key
            }
            foreach ($root in @('HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces')) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                }
                _P 'Interface_NoNagle'
            }
        } catch {}
    }
}



function Apply-U18Extras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _U([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }
    # TOP: U18 V2 (SETTING U18 V2) - aggressive FiveM latency pack

    if ($Mode -in @('Setting','All')) {
        try {
            foreach ($row in @(
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\ControlSet001\Control\PriorityControl','Win32PrioritySeparation',0x26),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','IRQ8Priority',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters','MouseDataQueueSize',16),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters','KeyboardDataQueueSize',10),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness',0),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex',[uint32]0xFFFFFFFF),
                @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NoLazyMode',1),
                @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode',2),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched','NonBestEffortLimit',0),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR','AllowGameDVR',0),
                @('HKCU:\System\GameConfigStore','GameDVR_Enabled',0),
                @('HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR','AppCaptureEnabled',0),
                @('HKLM:\SYSTEM\CurrentControlSet\Services\USB','DisableSelectiveSuspend',1),
                @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization','DODownloadMode',0)
            )) {
                $p,$n,$v = $row[0],$row[1],$row[2]
                if (-not (Test-Path $p)) { New-Item -Path $p -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $p -Name $n -PropertyType DWord -Value $v -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $n -Value $v -Type DWord -Force -EA SilentlyContinue
                _U $n
            }
            $game = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            if (-not (Test-Path $game)) { New-Item -Path $game -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $game -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            _U 'Games_MMCSS'
            New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            _U 'Input'
            foreach ($exe in @('FiveM.exe','GTA5.exe','FiveM_GTAProcess.exe','csrss.exe')) {
                $ipe = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe\PerfOptions"
                if (-not (Test-Path $ipe)) { New-Item -Path $ipe -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $ipe -Name 'CpuPriorityClass' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $ipe -Name 'IoPriority' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                _U ("IFEO_" + $exe)
            }
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1 } catch {}
            try { $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1 } catch {}
            _U 'Power'
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{ TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0 }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _U $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                }
                _U 'Interface_NoNagle'
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($a in @(
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','congestionprovider=ctcp'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','initialrto=1000'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','nonsackrttresiliency=disabled'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','supplemental','template=internet','icw=10')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1; _U 'netsh' } catch {}
            }
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _U 'NonBestEffortLimit'
        } catch {}
    }
}



function Apply-JacobRegRank1 {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    function _J([string]$n){ if(Get-Command Log-Name -EA SilentlyContinue){ Log-Name $n } elseif($null -ne $script:Ok){ $script:Ok++ } }

    # Rank1: Jacob reg + bat pack (from reg jacob.7z)
    # Note: Win32 values here lose to Aspas V2 (0x26) when ranks conflict

    if ($Mode -in @('Setting','All')) {
        try {
            # PriorityControl from Reg.REG / Jacob.reg (aggressive fa332a applied before Aspas wins)
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl',
                'HKLM:\SYSTEM\ControlSet001\Control\PriorityControl'
            )) {
                if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
                New-ItemProperty -Path $root -Name 'ConvertibleSlateMode' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0xfa332a -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -Value 0xfa332a -Type DWord -Force -EA SilentlyContinue
                _J 'Win32PrioritySeparation'
            }

            # USB polling
            $usb = 'HKLM:\SYSTEM\CurrentControlSet\Services\Usbport'
            if (-not (Test-Path $usb)) { New-Item -Path $usb -Force | Out-Null }
            New-ItemProperty -Path $usb -Name 'USBPollingRateMaxFrequencyNodlle' -PropertyType DWord -Value 0x3e8 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $usb -Name 'USBPollingRateMaxFrequencyNodlle' -Value 0x3e8 -Type DWord -Force -EA SilentlyContinue
            _J 'USBPollingRate'

            # EU.reg - block driver/WU noise
            foreach ($p in @(
                'HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device\Update',
                'HKLM:\SOFTWARE\Microsoft\PolicyManager\default\Update',
                'HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings',
                'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
            )) {
                if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
                New-ItemProperty -Path $p -Name 'ExcludeWUDriversInQualityUpdate' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name 'ExcludeWUDriversInQualityUpdate' -Value 1 -Type DWord -Force -EA SilentlyContinue
            }
            $pm = 'HKLM:\SOFTWARE\Microsoft\PolicyManager\default\Update\ExcludeWUDriversInQualityUpdate'
            if (-not (Test-Path $pm)) { New-Item -Path $pm -Force | Out-Null }
            New-ItemProperty -Path $pm -Name 'value' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $meta = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Device Metadata'
            if (-not (Test-Path $meta)) { New-Item -Path $meta -Force | Out-Null }
            New-ItemProperty -Path $meta -Name 'PreventDeviceMetadataFromNetwork' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $ds = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching'
            if (-not (Test-Path $ds)) { New-Item -Path $ds -Force | Out-Null }
            New-ItemProperty -Path $ds -Name 'SearchOrderConfig' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $ds -Name 'DontSearchWindowsUpdate' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _J 'DriverSearch'

            # Mouse from FF.bat
            $mouse = 'HKCU:\Control Panel\Mouse'
            if (-not (Test-Path $mouse)) { New-Item -Path $mouse -Force | Out-Null }
            New-ItemProperty -Path $mouse -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseSensitivity' -PropertyType String -Value '10' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseHoverTime' -PropertyType String -Value '400' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseTrails' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            _J 'Mouse'

            # GameDVR off (GamingOptimization)
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -Value 0 -Type DWord -Force -EA SilentlyContinue
            $gdvr = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR'
            if (-not (Test-Path $gdvr)) { New-Item -Path $gdvr -Force | Out-Null }
            New-ItemProperty -Path $gdvr -Name 'AppCaptureEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR' -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _J 'GameDVR'

            # Ultimate power (GamingOptimization.bat)
            try {
                $null = & powercfg.exe -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 2>&1
                $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN 100 2>&1
                $null = & powercfg.exe -setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX 100 2>&1
                $null = & powercfg.exe -setactive SCHEME_CURRENT 2>&1
                _J 'PowerUltimate'
            } catch {}
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            # GG.bat / network oriented bits already covered by NetworkForce;
            # keep interface NoNagle reinforcement from Jacob-style stack
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -EA SilentlyContinue
                    New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    Set-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -Value 0 -Type DWord -Force -EA SilentlyContinue
                }
                _J 'Interface_NoNagle'
            }
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
            foreach ($kv in @{ TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0 }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _J $kv.Key
            }
        } catch {}
    }
}



function Apply-FLSBResourcesBoost {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # From FLSB resources.7z: setting_flsb / network_fivem_win11 / gpedit / timer / graphic
    function _F([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -EA SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }

    if ($Mode -in @('Setting','All')) {
        try {
            # setting_flsb.ps1 core
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl',
                'HKLM:\SYSTEM\ControlSet001\Control\PriorityControl'
            )) {
                if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
                New-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0x26 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -Value 0x26 -Type DWord -Force -EA SilentlyContinue
                _F 'Win32PrioritySeparation'
            }

            # Game Mode ON / Game Bar OFF / DVR OFF
            $gb = 'HKCU:\SOFTWARE\Microsoft\GameBar'
            if (-not (Test-Path $gb)) { New-Item -Path $gb -Force | Out-Null }
            foreach ($kv in @{
                AutoGameModeEnabled = 1; AllowAutoGameMode = 1; ShowGameBar = 0
                UseNexusForGameBarEnabled = 0; ShowStartupPanel = 0
            }.GetEnumerator()) {
                New-ItemProperty -Path $gb -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $gb -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _F $kv.Key
            }
            $gcs = 'HKCU:\System\GameConfigStore'
            if (-not (Test-Path $gcs)) { New-Item -Path $gcs -Force | Out-Null }
            foreach ($kv in @{
                GameDVR_Enabled = 0; GameDVR_FSEBehaviorMode = 2
                GameDVR_HonorUserFSEBehaviorMode = 1; GameDVR_DXGIHonorFSEWindowsCompatible = 1
                GameDVR_EFSEBehaviorMode = 2
            }.GetEnumerator()) {
                New-ItemProperty -Path $gcs -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $gcs -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _F $kv.Key
            }
            New-ItemProperty -Path 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR' -Name 'AppCaptureEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR' -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _F 'GameDVR_Policy'

            # Input (setting_flsb)
            New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardDelay' -PropertyType String -Value '1' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
            foreach ($kv in @{
                MouseSpeed = '0'; MouseThreshold1 = '0'; MouseThreshold2 = '0'
                MouseTrails = '0'; MouseHoverTime = '10'
            }.GetEnumerator()) {
                New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name $kv.Key -PropertyType String -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                _F $kv.Key
            }

            # MMCSS Games
            $games = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            if (-not (Test-Path $game)) { New-Item -Path $game -Force | Out-Null }
            New-ItemProperty -Path $game -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $game -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            _F 'MMCSS_Games'

            # UI responsiveness
            New-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'MenuShowDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'ForegroundLockTimeout' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            $adv = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
            if (-not (Test-Path $adv)) { New-Item -Path $adv -Force | Out-Null }
            foreach ($kv in @{
                Start_TrackDocs = 0; Start_TrackProgs = 0; SeparateProcess = 1; TaskbarGlomLevel = 1
                TaskbarAnimations = 0; ListviewAlphaSelect = 0; ListviewShadow = 0
            }.GetEnumerator()) {
                New-ItemProperty -Path $adv -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                _F $kv.Key
            }
            New-ItemProperty -Path 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Search' -Name 'SearchboxTaskbarMode' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name 'EnableTransparency' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _F 'UI_Snappy'

            # gpedit.ps1 policies
            $ap = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy'
            if (-not (Test-Path $ap)) { New-Item -Path $ap -Force | Out-Null }
            New-ItemProperty -Path $ap -Name 'LetAppsRunInBackground' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' -Name 'PowerThrottlingOff' -Value 1 -Type DWord -Force -EA SilentlyContinue
            _F 'PowerThrottlingOff'

            # IFEO FiveM High priority
            foreach ($app in @('FiveM.exe','FiveM_GTAProcess.exe','FiveM_b3258_GTAProcess.exe','GTA5.exe')) {
                $p = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$app\PerfOptions"
                if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
                New-ItemProperty -Path $p -Name 'CpuPriorityClass' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $p -Name 'IoPriority' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                _F ("IFEO_" + $app)
            }

            # Timer resolution request (timer_resolution.ps1 intent)
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -Value 1 -Type DWord -Force -EA SilentlyContinue
            try {
                $null = & bcdedit.exe /set disabledynamictick yes 2>&1
                $null = & bcdedit.exe /set useplatformtick yes 2>&1
                _F 'BCD_Timer'
            } catch {}

            # USB selective suspend off + High Performance active (setting_flsb)
            try {
                $null = & powercfg.exe /setacvalueindex SCHEME_MIN SUB_USB USBSELECTIVE 0 2>&1
                $null = & powercfg.exe /setdcvalueindex SCHEME_MIN SUB_USB USBSELECTIVE 0 2>&1
                $null = & powercfg.exe /setacvalueindex SCHEME_CURRENT SUB_USB USBSELECTIVE 0 2>&1
                $null = & powercfg.exe /setdcvalueindex SCHEME_CURRENT SUB_USB USBSELECTIVE 0 2>&1
                $null = & powercfg.exe /setactive SCHEME_CURRENT 2>&1
                _F 'USB_SelectiveOff'
            } catch {}

            # GPU preference High Performance for FiveM paths (graphic_card.ps1)
            try {
                $gpu = 'HKCU:\SOFTWARE\Microsoft\DirectX\UserGpuPreferences'
                if (-not (Test-Path $gpu)) { New-Item -Path $gpu -Force | Out-Null }
                $paths = @(
                    "$env:LOCALAPPDATA\FiveM\FiveM.exe",
                    "$env:LOCALAPPDATA\FiveM\FiveM.app\FiveM.exe",
                    "$env:LOCALAPPDATA\FiveM\FiveM.app\data\cache\subprocess\FiveM_GTAProcess.exe"
                )
                foreach ($fp in $paths) {
                    New-ItemProperty -Path $gpu -Name $fp -PropertyType String -Value 'GpuPreference=2;' -Force -EA SilentlyContinue | Out-Null
                }
                _F 'GPU_Preference'
            } catch {}
        } catch {}
    }

    if ($Mode -in @('Network','All')) {
        try {
            # setting_network_fivem_win11.ps1
            foreach ($a in @(
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp')
            )) {
                try { $null = & netsh.exe @a 2>&1; _F ($a -join '_') } catch { _F ($a -join '_') 'fail' }
            }
            try { $null = & ipconfig.exe /flushdns 2>&1; _F 'FlushDNS' } catch {}

            Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
                try {
                    Set-NetAdapterPowerManagement -Name $_.Name -SelectiveSuspend Disabled -EA SilentlyContinue
                    Set-NetAdapterPowerManagement -Name $_.Name -AllowComputerToTurnOffDevice Disabled -EA SilentlyContinue
                    _F ('AdapterPower_' + $_.Name)
                } catch {}
            }

            # reinforce NoNagle
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
            foreach ($kv in @{ TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0 }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _F $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($kv in @{ TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0 }.GetEnumerator()) {
                        New-ItemProperty -Path $_.PSPath -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                    }
                }
                _F 'IF_NoNagle'
            }
        } catch {}
    }
}




