            _S 'SessionKeepAlive'
            New-ItemProperty -Path $p -Name 'InitialBackoff' -PropertyType DWord -Value 100 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $p -Name 'InitialBackoff' -Value 100 -Type DWord -Force -EA SilentlyContinue
            _S 'InitialBackoff'
            New-ItemProperty -Path $p -Name 'MaximumBackoff' -PropertyType DWord -Value 600 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $p -Name 'MaximumBackoff' -Value 600 -Type DWord -Force -EA SilentlyContinue
            _S 'MaximumBackoff'
            New-ItemProperty -Path $p -Name 'MinimumTimeout' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $p -Name 'MinimumTimeout' -Value 1 -Type DWord -Force -EA SilentlyContinue
            _S 'MinimumTimeout'
        } catch {}
        try {
            $p = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters'
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            New-ItemProperty -Path $p -Name 'ProcessorAffinityMask' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $p -Name 'ProcessorAffinityMask' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _S 'ProcessorAffinityMask'
            New-ItemProperty -Path $p -Name 'LogicalProcessorsPerPhysicalProcessor' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $p -Name 'LogicalProcessorsPerPhysicalProcessor' -Value 1 -Type DWord -Force -EA SilentlyContinue
            _S 'LogicalProcessorsPerPhysicalProcessor'
        } catch {}
        try {
            $p = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            New-ItemProperty -Path $p -Name 'SessionPoolSize' -PropertyType DWord -Value 524288 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $p -Name 'SessionPoolSize' -Value 524288 -Type DWord -Force -EA SilentlyContinue
            _S 'SessionPoolSize'
            New-ItemProperty -Path $p -Name 'LargePageMinimum' -PropertyType DWord -Value 2097152 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $p -Name 'LargePageMinimum' -Value 2097152 -Type DWord -Force -EA SilentlyContinue
            _S 'LargePageMinimum'
        } catch {}
        try {
            $p = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\ServiceProvider'
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            try { Remove-ItemProperty -Path $p -Name 'Class' -Force -EA SilentlyContinue; _S 'Class' } catch {}
            try { Remove-ItemProperty -Path $p -Name 'LocalAddressSortList' -Force -EA SilentlyContinue; _S 'LocalAddressSortList' } catch {}
        } catch {}

        try { $null = & netsh.exe @('int','tcp','set','heuristics','disabled') 2>&1; _S 'netsh_disabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','ecncapability=disabled') 2>&1; _S 'netsh_ecncapability=disabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('interface','isatap','set','state','disabled') 2>&1; _S 'netsh_disabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','timestamps=disabled') 2>&1; _S 'netsh_timestamps=disabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','nonsackrttresiliency=disabled') 2>&1; _S 'netsh_nonsackrttresiliency=disabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','initialRto=1000') 2>&1; _S 'netsh_initialRto=1000' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','supplemental','template=internet','congestionprovider=cubic') 2>&1; _S 'netsh_congestionprovider=cubic' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','supplemental','template=compat','congestionprovider=cubic') 2>&1; _S 'netsh_congestionprovider=cubic' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','supplemental','template=custom','congestionprovider=cubic') 2>&1; _S 'netsh_congestionprovider=cubic' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','ip','set','global','taskoffload=enabled') 2>&1; _S 'netsh_taskoffload=enabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','autotuninglevel=restricted') 2>&1; _S 'netsh_autotuninglevel=restricted' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','rsc=disabled') 2>&1; _S 'netsh_rsc=disabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','rss=enabled') 2>&1; _S 'netsh_rss=enabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','dca=enabled') 2>&1; _S 'netsh_dca=enabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','fastopen=enabled') 2>&1; _S 'netsh_fastopen=enabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','tcp','set','global','fastopenfallback=enabled') 2>&1; _S 'netsh_fastopenfallback=enabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','ip','set','global','icmpredirects=disabled') 2>&1; _S 'netsh_icmpredirects=disabled' } catch { _S 'netsh' 'fail' }
        try { $null = & netsh.exe @('int','ip','set','global','multicasting=disabled') 2>&1; _S 'netsh_multicasting=disabled' } catch { _S 'netsh' 'fail' }

        try {
            Get-NetAdapter -EA SilentlyContinue | Where-Object {
                $_.Status -eq 'Up' -and -not $_.Virtual -and
                $_.InterfaceDescription -notmatch 'Loopback|Tunnel|Virtual|Hyper-V|WAN Miniport'
            } | ForEach-Object {
                $ad = $_
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*DeviceSleepOnDisconnect' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*EEE' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*FlowControl' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'AutoPowerSaveModeEnabled' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*WakeOnMagicPacket' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*WakeOnPattern' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'WakeOnLink' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'WakeOnSlot' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'WakeUpModeCap' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*SelectiveSuspend' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'Selective Suspend' -RegistryValue 'Disabled' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'Selective Suspend Idle Timeout' -RegistryValue '60' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EEELinkAdvertisement' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EeePhyEnable' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'AdvancedEEE' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EnableGreenEthernet' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'GigaLite' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'PowerSavingMode' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'ULPMode' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'Ultra Low Power Mode' -RegistryValue 'Disabled' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'System Idle Power Saver' -RegistryValue 'Disabled' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'Link Speed Battery Saver' -RegistryValue 'Disabled' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'ReduceSpeedOnPowerDown' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'PowerDownPll' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*InterruptModeration' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'DMACoalescing' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'ITR' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*LsoV2IPv4' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*LsoV2IPv6' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*RSS' -RegistryValue '1' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*NumRssQueues' -RegistryValue '2' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*ReceiveBuffers' -RegistryValue '2048' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*TransmitBuffers' -RegistryValue '2048' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*PriorityVLANTag' -RegistryValue '1' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'WaitAutoNegComplete' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EnableLLI' -RegistryValue '1' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'PnPCapabilities' -RegistryValue '24' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*IPChecksumOffloadIPv4' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*TCPChecksumOffloadIPv4' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*TCPChecksumOffloadIPv6' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*UDPChecksumOffloadIPv4' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*UDPChecksumOffloadIPv6' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*LsoV1IPv4' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*PMARPOffload' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*PMNSOffload' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*InterruptModerationRate' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword '*PacketDirect' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EnableCoalesce' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'CoalesceBufferSize' -RegistryValue '2048' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EnableUDPTxScaling' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'MTU' -RegistryValue '1492' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EnablePME' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EnableDynamicPowerGating' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'EnableConnectedPowerGating' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'NicAutoPowerSaver' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                    try { Set-NetAdapterAdvancedProperty -Name $ad.Name -RegistryKeyword 'DisableDelayedPowerUp' -RegistryValue '0' -NoRestart -EA SilentlyContinue } catch {}
                try {
                    Set-NetAdapterPowerManagement -Name $ad.Name -SelectiveSuspend Disabled -EA SilentlyContinue
                    Set-NetAdapterPowerManagement -Name $ad.Name -AllowComputerToTurnOffDevice Disabled -EA SilentlyContinue
                } catch {}
                _S ('NIC_' + $ad.Name)
            }
        } catch {}

        try {
            $disable = @('ms_tcpip6','vmware_bridge','ms_lldp','ms_lltdio','ms_implat','ms_rspndr','ms_server','ms_msclient')
            Get-NetAdapterBinding -EA SilentlyContinue | Where-Object {
                $disable -contains $_.ComponentID -and $_.Enabled
            } | ForEach-Object {
                try {
                    Disable-NetAdapterBinding -Name $_.Name -ComponentID $_.ComponentID -EA SilentlyContinue
                    _S ('BindOff_' + $_.ComponentID)
                } catch {}
            }
        } catch {}

        try {
            Get-NetAdapter -EA SilentlyContinue | Where-Object {
                $_.Status -eq 'Up' -and -not $_.Virtual -and
                $_.InterfaceDescription -notmatch 'Loopback|Tunnel|Virtual|Hyper-V|WAN Miniport'
            } | ForEach-Object {
                try {
                    Set-DnsClientServerAddress -InterfaceAlias $_.Name -ServerAddresses @('1.1.1.1','1.0.0.1') -EA SilentlyContinue
                    _S ('DNS_' + $_.Name)
                } catch {}
            }
            try { Clear-DnsClientCache -EA SilentlyContinue; _S 'FlushDNS' } catch {}
            try { $null = & ipconfig.exe /flushdns 2>&1 } catch {}
        } catch {}
    }

    if ($Mode -in @('Setting','All')) {
        try { $null = & bcdedit.exe @('/set','useplatformtick','No') 2>&1; _S 'bcd' } catch {}
        try { $null = & bcdedit.exe @('/set','useplatformclock','No') 2>&1; _S 'bcd' } catch {}
        try { $null = & bcdedit.exe @('/deletevalue','tscsyncpolicy') 2>&1; _S 'bcd' } catch {}
        try { $null = & bcdedit.exe @('/set','disabledynamictick','yes') 2>&1; _S 'bcd' } catch {}
        try { $null = & bcdedit.exe @('/set','hypervisorlaunchtype','off') 2>&1; _S 'bcd' } catch {}
    }
}



function Apply-PrimaryInputSeal {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # Shared primary tier (FLSB + Aspas V2 + Internet): lock input/priority to best known values
    function _P([string]$n) {
        if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name $n }
        elseif ($null -ne $script:Ok) { $script:Ok++ }
    }
    if ($Mode -notin @('Setting','All')) { return }
    try {
        # Win32: FLSB official setting_flsb + common Aspas = 0x26 (38) — foreground boost, stable for FiveM
        foreach ($root in @(
            'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl',
            'HKLM:\SYSTEM\ControlSet001\Control\PriorityControl'
        )) {
            if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
            New-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0x26 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -Value 0x26 -Type DWord -Force -EA SilentlyContinue
            _P 'Win32PrioritySeparation'
        }
        # Keyboard — FLSB resources (Delay 1, Speed 31) + queue size aggressive
        New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardDelay' -PropertyType String -Value '1' -Force -EA SilentlyContinue | Out-Null
        New-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
        foreach ($cs in @(
            'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters',
            'HKLM:\SYSTEM\ControlSet001\Services\kbdclass\Parameters'
        )) {
            if (-not (Test-Path $cs)) { New-Item -Path $cs -Force | Out-Null }
            New-ItemProperty -Path $cs -Name 'KeyboardDataQueueSize' -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $cs -Name 'KeyboardDataQueueSize' -Value 20 -Type DWord -Force -EA SilentlyContinue
        }
        _P 'Keyboard'
        # Mouse — no accel (Aspas/FLSB aligned)
        foreach ($kv in @{
            MouseSpeed='0'; MouseThreshold1='0'; MouseThreshold2='0'
            MouseTrails='0'; MouseHoverTime='10'
        }.GetEnumerator()) {
            New-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name $kv.Key -PropertyType String -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
        }
        foreach ($cs in @(
            'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters',
            'HKLM:\SYSTEM\ControlSet001\Services\mouclass\Parameters'
        )) {
            if (-not (Test-Path $cs)) { New-Item -Path $cs -Force | Out-Null }
            New-ItemProperty -Path $cs -Name 'MouseDataQueueSize' -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $cs -Name 'MouseDataQueueSize' -Value 20 -Type DWord -Force -EA SilentlyContinue
        }
        _P 'Mouse'
    } catch {}
}


function Invoke-MergedAllSources {
    param([ValidateSet('All','Setting','Network')][string]$Mode = 'All')
    $ErrorActionPreference = 'SilentlyContinue'
    $script:Ok = 0
    $script:Fail = 0
    $script:LoggedNames = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    if (Get-Command Write-LogTime -EA SilentlyContinue) { Write-LogTime ("start Mode=$Mode") '#FFFFFF' }

    # Conflict: Rank1 primary trio (equal) > Rank1 rest > TOP > 3++
    # Primary equal: FLSB + Aspas V2 + Internet Aspas (all sealed together)

    # 3++
    try { Apply-Setting7zExtras -Mode $Mode } catch {}
    try { Apply-SayhanExtras -Mode $Mode } catch {}
    try { Apply-HitFeel -Mode $Mode } catch {}
    try { Apply-MaxAggression -Mode $Mode } catch {}
    try { Apply-CoreRegistryBulk -Mode $Mode } catch {}
    try { Apply-DenseExtra -Mode $Mode } catch {}
    try { Apply-UltraMaxPack -Mode $Mode } catch {}
    try { Apply-FullStackMax -Mode $Mode } catch {}
    try { Apply-GodTierStack -Mode $Mode } catch {}
    try { Apply-MoreAggression -Mode $Mode } catch {}
    try { Apply-PolicyExtras -Mode $Mode } catch {}

    # TOP
    try { Apply-AssassinExtras -Mode $Mode } catch {}
    try { Apply-BitcexExtras -Mode $Mode } catch {}
    try { Apply-ProjectWongNua -Mode $Mode } catch {}
    try { Apply-SlurppyWongNua -Mode $Mode } catch {}
    try { Apply-ProjectPrimeExtras -Mode $Mode } catch {}
    try { Apply-TopUfaAntiKai -Mode $Mode } catch {}
    try { Apply-DektinExtras -Mode $Mode } catch {}
    try { Apply-BastienExtras -Mode $Mode } catch {}
    try { Apply-AironPlusExtras -Mode $Mode } catch {}
    try { Apply-JacobExtras -Mode $Mode } catch {}
    try { Apply-VenomExtras -Mode $Mode } catch {}
    try { Apply-BangbathExtras -Mode $Mode } catch {}
    try { Apply-KaiPrimeExtras -Mode $Mode } catch {}
    try { Apply-BestPowerPlan } catch {}

    # Rank1 lower half (below primary trio)
    # Flow < Sync < RegJacob < BTX < U18 < Radubgod < Shi
    try { Apply-FlowExtras -Mode $Mode } catch {}
    try { Apply-FlowGpedit -Mode $Mode } catch {}
    try { Apply-SyncProjectExtras -Mode $Mode } catch {}
    try { Apply-JacobRegRank1 -Mode $Mode } catch {}
    try { Apply-BTXExtras -Mode $Mode } catch {}
    try { Apply-U18Extras -Mode $Mode } catch {}
    try { Apply-RadubGodExtras -Mode $Mode } catch {}
    try { Apply-ShiNetTweak -Mode $Mode } catch {}

    # Rank1 PRIMARY equal tier: Internet Aspas + Aspas V2 + FLSB (same weight)
    try { Apply-InternetAspasLean -Mode $Mode } catch {}
    try { Apply-AspasV2Extras -Mode $Mode } catch {}
    try { Apply-FLSBExtras -Mode $Mode } catch {}
    try { Apply-FlsbSyncGpeditWin -Mode $Mode } catch {}
    try { Apply-FLSBResourcesBoost -Mode $Mode } catch {}
    try { Apply-Rank12Boost -Mode $Mode } catch {}
    try { Apply-Rank1Dense -Mode $Mode } catch {}
    try { Apply-StickHard -Mode $Mode } catch {}
    try { Apply-Rank1Seal -Mode $Mode } catch {}
    try { Apply-BestPowerPlan } catch {}

    # Seal primary trio again + best Win32/Mouse/Keyboard
    try { Apply-ConflictResolve -Mode $Mode } catch {}
    try { Apply-InternetAspasLean -Mode $Mode } catch {}
    try { Apply-AspasV2Extras -Mode $Mode } catch {}
    try { Apply-FLSBExtras -Mode $Mode } catch {}
    try { Apply-FlsbSyncGpeditWin -Mode $Mode } catch {}
    try { Apply-FLSBResourcesBoost -Mode $Mode } catch {}
    try { Apply-PrimaryInputSeal -Mode $Mode } catch {}
    try { Apply-AspasKeySeal -Mode $Mode } catch {}
    try { Apply-ForceStick -Mode $Mode } catch {}
    try { Apply-UserLockedRegs } catch {}
    if ($Mode -in @('Network','All')) {
        try { Apply-NetworkForce } catch {}
        try { Apply-ConflictResolve -Mode 'Network' } catch {}
        try { Apply-ShiNetTweak -Mode 'Network' } catch {}
        try { Apply-InternetAspasLean -Mode 'Network' } catch {}
        try { Apply-AspasV2Extras -Mode 'Network' } catch {}
        try { Apply-FLSBExtras -Mode 'Network' } catch {}
        try { Apply-FLSBResourcesBoost -Mode 'Network' } catch {}
        try { Apply-ForceStick -Mode 'Network' } catch {}
        try { Apply-DnsCloudflare } catch {}
    }

    if ($null -eq $script:Ok) { $script:Ok = 0 }
    if ($null -eq $script:Fail) { $script:Fail = 0 }
    if (Get-Command Write-LogTime -EA SilentlyContinue) {
        Write-LogTime ("Mode={0} | applied={1} values" -f $Mode, [int]$script:Ok) '#14eb00'
        if ([int]$script:Fail -gt 0) {
            Write-LogTime ("skipped/fail={0}" -f [int]$script:Fail) '#AAAAAA'
        }
        Write-LogTime 'SUCCESS' '#14eb00'
    }
}


function Show-MainWindow {

[xml]$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Project UndergroundPrime — Cyber Galaxy Console" Height="860" Width="1180"
        WindowStartupLocation="CenterScreen"
        ResizeMode="NoResize"
        WindowStyle="None"
        AllowsTransparency="True"
        Opacity="0"
        Background="Transparent"
        TextOptions.TextFormattingMode="Display"
        TextOptions.TextRenderingMode="ClearType"
        RenderOptions.ClearTypeHint="Enabled"
        UseLayoutRounding="True"
        SnapsToDevicePixels="True">

    <Window.Triggers>
        <EventTrigger RoutedEvent="Window.Loaded">
            <BeginStoryboard>
                <Storyboard>
                    <DoubleAnimation Storyboard.TargetProperty="Opacity"
                                     From="0" To="1" Duration="0:0:0.35"/>
                    <DoubleAnimation Storyboard.TargetName="OuterGlow"
                                     Storyboard.TargetProperty="Opacity"
                                     From="0.2" To="0.55" Duration="0:0:2.2"
                                     AutoReverse="True" RepeatBehavior="Forever"/>
                    <DoubleAnimation Storyboard.TargetName="OnlineDotScale"
                                     Storyboard.TargetProperty="ScaleX"
                                     From="0.85" To="1.25" Duration="0:0:1.1"
                                     AutoReverse="True" RepeatBehavior="Forever"/>
                    <DoubleAnimation Storyboard.TargetName="OnlineDotScale"
                                     Storyboard.TargetProperty="ScaleY"
                                     From="0.85" To="1.25" Duration="0:0:1.1"
                                     AutoReverse="True" RepeatBehavior="Forever"/>
                </Storyboard>
            </BeginStoryboard>
        </EventTrigger>
    </Window.Triggers>

    <Window.Resources>
        <Style x:Key="GalaxyScrollThumb" TargetType="Thumb">
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Thumb">
                        <Border CornerRadius="5" Background="#C0C0C0" Opacity="0.75"/>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="ScrollBar">
            <Setter Property="Width" Value="8"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ScrollBar">
                        <Grid>
                            <Border CornerRadius="4" Background="#0A0A0A"/>
                            <Track x:Name="PART_Track" IsDirectionReversed="True" Margin="1">
                                <Track.Thumb>
                                    <Thumb Style="{StaticResource GalaxyScrollThumb}"/>
                                </Track.Thumb>
                                <Track.IncreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageDownCommand" Opacity="0" Focusable="False"/>
                                </Track.IncreaseRepeatButton>
                                <Track.DecreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageUpCommand" Opacity="0" Focusable="False"/>
                                </Track.DecreaseRepeatButton>
                            </Track>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="ActionBtn" TargetType="Button">
            <Setter Property="Foreground" Value="#E0E0E0"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Height" Value="46"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="Padding" Value="16,0,0,0"/>
            <Setter Property="Background" Value="#0A0A0A"/>
            <Setter Property="Margin" Value="0,0,0,8"/>
            <Setter Property="RenderTransformOrigin" Value="0.5,0.5"/>
            <Setter Property="RenderTransform">
                <Setter.Value>
                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                </Setter.Value>
            </Setter>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="10" Background="{TemplateBinding Background}"
                                BorderThickness="1" BorderBrush="#555555">
                            <Border.Effect>
                                <DropShadowEffect x:Name="btnGlow" Color="#E8E8E8" BlurRadius="0" ShadowDepth="0" Opacity="0"/>
                            </Border.Effect>
                            <Grid>
                                <Border x:Name="accentDot" Width="6" Height="6" CornerRadius="3"
                                        HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,16,0"
                                        Background="#222222"/>
                                <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"
                                                   Margin="{TemplateBinding Padding}"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="border"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#E0E0E0" Duration="0:0:0.15"/>
                                            <ColorAnimation Storyboard.TargetName="accentDot"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#E0E0E0" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                             Storyboard.TargetProperty="BlurRadius" To="16" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                             Storyboard.TargetProperty="Opacity" To="0.65" Duration="0:0:0.15"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <ColorAnimation Storyboard.TargetName="border"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#0A0A0A" Duration="0:0:0.2"/>
                                            <ColorAnimation Storyboard.TargetName="accentDot"
                                                            Storyboard.TargetProperty="(Border.Background).(SolidColorBrush.Color)"
                                                            To="#222222" Duration="0:0:0.2"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                             Storyboard.TargetProperty="BlurRadius" To="0" Duration="0:0:0.2"/>
                                            <DoubleAnimation Storyboard.TargetName="btnGlow"
                                                             Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.2"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                                <Setter Property="Foreground" Value="#050505"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="AppBtn" TargetType="Button">
            <Setter Property="Foreground" Value="#E0E0E0"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Height" Value="44"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="Padding" Value="14,0,0,0"/>
            <Setter Property="Background" Value="#0A0A0A"/>
            <Setter Property="Margin" Value="0,0,0,0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="9" Background="{TemplateBinding Background}"
                                BorderThickness="1" BorderBrush="#222222">
                            <Grid>
                                <Border x:Name="accentDot" Width="6" Height="6" CornerRadius="3"
                                        HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,14,0"
                                        Background="#222222"/>
                                <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"
                                                   Margin="{TemplateBinding Padding}"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#E0E0E0"/>
                                <Setter TargetName="accentDot" Property="Background" Value="#E0E0E0"/>
                                <Setter TargetName="border" Property="BorderBrush" Value="#E0E0E0"/>
                                <Setter Property="Foreground" Value="#050505"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="HwCard" TargetType="Border">
            <Setter Property="Background" Value="#0A0A0A"/>
            <Setter Property="CornerRadius" Value="9"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="BorderBrush" Value="#555555"/>
            <Setter Property="Padding" Value="10,8"/>
            <Setter Property="Margin" Value="0,0,0,8"/>
        </Style>

        <Style x:Key="HwIconBox" TargetType="Border">
            <Setter Property="Width" Value="30"/>
            <Setter Property="Height" Value="30"/>
            <Setter Property="CornerRadius" Value="7"/>
            <Setter Property="Background" Value="#222222"/>
        </Style>

        <Style x:Key="HwLabel" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#9F9F9F"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="9.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
        </Style>

        <Style x:Key="HwValue" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#E0E0E0"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="TextWrapping" Value="Wrap"/>
        </Style>

        <Style x:Key="RailIcon" TargetType="Border">
            <Setter Property="Width" Value="34"/>
            <Setter Property="Height" Value="34"/>
            <Setter Property="CornerRadius" Value="9"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Margin" Value="0,0,0,6"/>
        </Style>

        <Style x:Key="StartBtn" TargetType="Button">
            <Setter Property="Foreground" Value="#F2F2F2"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Height" Value="42"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Background" Value="#101010"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="10" Background="{TemplateBinding Background}"
                                BorderThickness="1.4" BorderBrush="#E8E8E8">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#C0C0C0"/>
                                <Setter Property="Foreground" Value="White"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="CapBtn" TargetType="Button">
            <Setter Property="Width" Value="30"/>
            <Setter Property="Height" Value="30"/>
            <Setter Property="Foreground" Value="#F2F2F2"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="FontFamily" Value="Segoe UI"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="cb" CornerRadius="8" Background="{TemplateBinding Background}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="cb" Property="Background" Value="#CC1A1A1A"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="GlassCard" TargetType="Border">
            <Setter Property="Background" Value="#E0121212"/>
            <Setter Property="CornerRadius" Value="16"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="BorderBrush" Value="#666666"/>
            <Setter Property="Padding" Value="20"/>
        </Style>

        <Style x:Key="SpecLabel" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#F2F2F2"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="10"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Margin" Value="0,9,0,2"/>
            <Setter Property="TextOptions.TextFormattingMode" Value="Display"/>
            <Setter Property="TextOptions.TextRenderingMode" Value="ClearType"/>
        </Style>
        <Style x:Key="SpecValue" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="FontFamily" Value="Consolas"/>
            <Setter Property="FontSize" Value="12.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="TextWrapping" Value="Wrap"/>
            <Setter Property="TextOptions.TextFormattingMode" Value="Display"/>
            <Setter Property="TextOptions.TextRenderingMode" Value="ClearType"/>
        </Style>
    </Window.Resources>

    <Grid>
        <Border CornerRadius="20" BorderThickness="0" Margin="-6">
            <Border.Background>
                <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                    <GradientStop Color="#A8A8A8" Offset="0"/>
                    <GradientStop Color="#E6E6E6" Offset="0.5"/>
                    <GradientStop Color="#FFFFFF" Offset="1"/>
                </LinearGradientBrush>
            </Border.Background>
            <Border.Effect>
                <DropShadowEffect x:Name="OuterGlow" Color="#B8B8B8" BlurRadius="26" ShadowDepth="0" Opacity="0.35"/>
            </Border.Effect>
        </Border>

    <Border CornerRadius="20" BorderThickness="1.4">
        <Border.BorderBrush>
            <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                <GradientStop Color="#A8A8A8" Offset="0"/>
                <GradientStop Color="#E6E6E6" Offset="0.5"/>
                <GradientStop Color="#FFFFFF" Offset="1"/>
            </LinearGradientBrush>
        </Border.BorderBrush>
        <Border.Background>
            <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                <GradientStop Color="#050505" Offset="0"/>
                <GradientStop Color="#0A0A0A" Offset="0.5"/>
                <GradientStop Color="#121212" Offset="1"/>
            </LinearGradientBrush>
        </Border.Background>

        <Grid ClipToBounds="True">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="*"/>
            </Grid.RowDefinitions>

            <!-- Background artwork -->
            <Image x:Name="BgImage" Grid.Row="0" Grid.RowSpan="3" Stretch="UniformToFill"
                   Opacity="0.30" IsHitTestVisible="False"/>
            <Border Grid.Row="0" Grid.RowSpan="3" IsHitTestVisible="False">
                <Border.Background>
                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                        <GradientStop Color="#050505" Offset="0"/>
                        <GradientStop Color="#8A222222" Offset="0.4"/>
                        <GradientStop Color="#050505" Offset="1"/>
                    </LinearGradientBrush>
                </Border.Background>
            </Border>

            <!-- nebula + stars backdrop -->
            <Canvas Grid.Row="0" Grid.RowSpan="3" IsHitTestVisible="False">
                <Ellipse Canvas.Left="-100" Canvas.Top="-70" Width="340" Height="340" Opacity="0.14">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#E0E0E0" Offset="0"/>
                            <GradientStop Color="#050505" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.Effect><BlurEffect Radius="30"/></Ellipse.Effect>
                </Ellipse>
                <Ellipse Canvas.Left="820" Canvas.Top="-40" Width="320" Height="320" Opacity="0.13">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#E8E8E8" Offset="0"/>
                            <GradientStop Color="#050505" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.Effect><BlurEffect Radius="30"/></Ellipse.Effect>
                </Ellipse>
                <Ellipse Canvas.Left="380" Canvas.Top="560" Width="360" Height="240" Opacity="0.12">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#F0F0F0" Offset="0"/>
                            <GradientStop Color="#050505" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.Effect><BlurEffect Radius="32"/></Ellipse.Effect>
                </Ellipse>
                <Ellipse Canvas.Left="60"  Canvas.Top="130" Width="2" Height="2" Fill="#ffffff" Opacity="0.5"/>
                <Ellipse Canvas.Left="950" Canvas.Top="90"  Width="2" Height="2" Fill="#E0E0E0" Opacity="0.6"/>
                <Ellipse Canvas.Left="1020" Canvas.Top="260" Width="3" Height="3" Fill="#F2F2F2" Opacity="0.55"/>
                <Ellipse Canvas.Left="40"  Canvas.Top="600" Width="2" Height="2" Fill="#FFFFFF" Opacity="0.5"/>
                <Ellipse Canvas.Left="1040" Canvas.Top="620" Width="2" Height="2" Fill="#F2F2F2" Opacity="0.5"/>
            </Canvas>

            <!-- custom title bar -->
            <Grid x:Name="TitleBar" Grid.Row="0" Height="42" Background="Transparent">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <TextBlock Grid.Column="0" Text="&#x25C8;  Project UndergroundPrime" Foreground="#F2F2F2"
                           FontFamily="Segoe UI Semibold" FontSize="11" VerticalAlignment="Center" Margin="16,0,0,0"/>
                <TextBlock Grid.Column="1" Text="" Foreground="#E8E8E8"
                           FontFamily="Consolas" FontSize="15" VerticalAlignment="Center" HorizontalAlignment="Center"/>
                <StackPanel Grid.Column="2" Orientation="Horizontal" Margin="0,0,8,0">
                    <Button x:Name="BtnMin" Style="{StaticResource CapBtn}" Content="&#x2014;"/>
                    <Button x:Name="BtnClose" Style="{StaticResource CapBtn}" Content="&#x2715;"/>
                </StackPanel>
            </Grid>

            <!-- header -->
            <Grid Grid.Row="1" Margin="30,10,30,16">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                <StackPanel Grid.Column="0">
                    <TextBlock Text="&#x25C8; Project UndergroundPrime" FontFamily="Segoe UI Black" FontSize="24">
                        <TextBlock.Foreground>
                            <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
                                <GradientStop Color="#FFFFFF" Offset="0"/>
                                <GradientStop Color="#D0D0D0" Offset="0.5"/>
                                <GradientStop Color="#F2F2F2" Offset="1"/>
                            </LinearGradientBrush>
                        </TextBlock.Foreground>
                    </TextBlock>
                    <TextBlock Text="Project UndergroundPrime - THE BEST FIVEM" Foreground="#9F9F9F"
                               FontFamily="Consolas" FontSize="12.5" Margin="2,4,0,0"/>
                </StackPanel>
                <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">

                    <Border CornerRadius="16" BorderThickness="1" BorderBrush="#444444"
                            Background="#0A0A0A" Padding="14,7" VerticalAlignment="Center">
                        <StackPanel Orientation="Horizontal">
                            <Ellipse Width="9" Height="9" Fill="#00EBA0" Margin="0,0,8,0" VerticalAlignment="Center"
                                     RenderTransformOrigin="0.5,0.5">
                                <Ellipse.RenderTransform>
                                    <ScaleTransform x:Name="OnlineDotScale" ScaleX="1" ScaleY="1"/>
                                </Ellipse.RenderTransform>
                                <Ellipse.Effect><DropShadowEffect Color="#00EBA0" BlurRadius="10" ShadowDepth="0" Opacity="0.9"/></Ellipse.Effect>
                            </Ellipse>
                            <TextBlock Text="ONLINE" Foreground="#00EBA0" FontFamily="Consolas" FontSize="12" FontWeight="Bold" VerticalAlignment="Center"/>
                        </StackPanel>
                    </Border>
                </StackPanel>
            </Grid>

            <!-- body: ICON RAIL | PROFILE+HARDWARE sidebar | MAIN (commands grid + tweaks/log) -->
            <Grid Grid.Row="2" Margin="30,0,30,26">
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="62"/>
                    <ColumnDefinition Width="14"/>
                    <ColumnDefinition Width="230"/>
                    <ColumnDefinition Width="16"/>
                    <ColumnDefinition/>
                </Grid.ColumnDefinitions>

                <!-- ICON RAIL (decorative app-shell icon strip) -->
                <Border Grid.Column="0" Style="{StaticResource GlassCard}" Padding="8,16">
                    <StackPanel HorizontalAlignment="Center">
                        <Border Style="{StaticResource RailIcon}" Background="#E0E0E0">
                            <TextBlock Text="&#x25C8;" Foreground="#050505" FontSize="16" FontWeight="Bold"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}">
                            <TextBlock Text="&#x2699;" Foreground="#9F9F9F" FontSize="15"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}">
                            <TextBlock Text="&#x1F310;" Foreground="#9F9F9F" FontFamily="Segoe UI Emoji" FontSize="14"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}">
                            <TextBlock Text="&#x2328;" Foreground="#9F9F9F" FontFamily="Segoe UI Emoji" FontSize="15"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <Border Style="{StaticResource RailIcon}" Margin="0,90,0,0">
                            <TextBlock Text="&#x1F464;" Foreground="#9F9F9F" FontFamily="Segoe UI Emoji" FontSize="15"
                                       HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                    </StackPanel>
                </Border>

                <!-- SIDEBAR: profile card + hardware cards -->
                <Border Grid.Column="2" Style="{StaticResource GlassCard}" Padding="14">
                    <Grid>
                        <Grid.RowDefinitions>
                            <RowDefinition Height="Auto"/>
                            <RowDefinition Height="*"/>
                            <RowDefinition Height="Auto"/>
                        </Grid.RowDefinitions>

                        <!-- profile -->
                        <StackPanel Grid.Row="0" HorizontalAlignment="Center" Margin="0,4,0,14">
                            <Border Width="54" Height="54" CornerRadius="27" Background="#0A0A0A"
                                    BorderThickness="1.6" BorderBrush="#E0E0E0" Margin="0,0,0,8">
                                <Grid>
                                    <TextBlock x:Name="AvatarFallbackIcon" Text="&#x1F464;" FontFamily="Segoe UI Emoji" FontSize="22"
                                               HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                    <Ellipse x:Name="AvatarImage" Width="50.8" Height="50.8" Visibility="Collapsed"
                                             HorizontalAlignment="Center" VerticalAlignment="Center">
                                        <Ellipse.Fill>
                                            <ImageBrush x:Name="AvatarImageBrush" Stretch="UniformToFill"/>
                                        </Ellipse.Fill>
                                    </Ellipse>
                                </Grid>
                            </Border>
                            <TextBlock x:Name="TxtUserName" Text="Administrator" Foreground="#E0E0E0"
                                       FontFamily="Consolas" FontSize="12" FontWeight="Bold" HorizontalAlignment="Center"/>
                            <TextBlock x:Name="TxtComputerName" Text="-" Foreground="#9F9F9F"
                                       FontFamily="Consolas" FontSize="10" HorizontalAlignment="Center" Margin="0,2,0,0"/>
                        </StackPanel>

                        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto">
                            <StackPanel>
                                <TextBlock Text="◈ HARDWARE" Foreground="#F2F2F2" FontFamily="Consolas"
                                           FontSize="9.5" FontWeight="Bold" Margin="2,0,0,8"/>

                                <Border Style="{StaticResource HwCard}">
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition/>
                                        </Grid.ColumnDefinitions>
                                        <Border Style="{StaticResource HwIconBox}">
                                            <Viewbox Width="16" Height="16" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                <Canvas Width="24" Height="24">
                                                    <Rectangle Canvas.Left="3" Canvas.Top="4" Width="18" Height="12" RadiusX="2" RadiusY="2" Stroke="#E0E0E0" StrokeThickness="1.8" Fill="Transparent"/>
                                                    <Line X1="9" Y1="20" X2="15" Y2="20" Stroke="#E0E0E0" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="12" Y1="16" X2="12" Y2="20" Stroke="#E0E0E0" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                </Canvas>
                                            </Viewbox>
                                        </Border>
                                        <StackPanel Grid.Column="1" Margin="10,0,0,0" VerticalAlignment="Center">
                                            <TextBlock Text="OS" Style="{StaticResource HwLabel}"/>
                                            <TextBlock x:Name="TxtOs" Text="-" Style="{StaticResource HwValue}"/>
                                        </StackPanel>
                                    </Grid>
                                </Border>

                                <Border Style="{StaticResource HwCard}">
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition/>
                                        </Grid.ColumnDefinitions>
                                        <Border Style="{StaticResource HwIconBox}">
                                            <Viewbox Width="16" Height="16" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                <Canvas Width="24" Height="24">
                                                    <Rectangle Canvas.Left="6" Canvas.Top="6" Width="12" Height="12" RadiusX="1.5" RadiusY="1.5" Stroke="#E0E0E0" StrokeThickness="1.8" Fill="Transparent"/>
                                                    <Rectangle Canvas.Left="9.5" Canvas.Top="9.5" Width="5" Height="5" Stroke="#E0E0E0" StrokeThickness="1.3" Fill="Transparent"/>
                                                    <Line X1="9" Y1="2" X2="9" Y2="6" Stroke="#E0E0E0" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="15" Y1="2" X2="15" Y2="6" Stroke="#E0E0E0" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="9" Y1="18" X2="9" Y2="22" Stroke="#E0E0E0" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="15" Y1="18" X2="15" Y2="22" Stroke="#E0E0E0" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="2" Y1="9" X2="6" Y2="9" Stroke="#E0E0E0" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="2" Y1="15" X2="6" Y2="15" Stroke="#E0E0E0" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                    <Line X1="18" Y1="9" X2="22" Y2="9" Stroke="#E0E0E0" StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
