if ($script:AvatarBitmap) {
    $AvatarImageBrush.ImageSource  = $script:AvatarBitmap
    $AvatarImage.Visibility        = "Visible"
    $AvatarFallbackIcon.Visibility = "Collapsed"
}

$TxtOs           = $window.FindName("TxtOs")
$TxtComputerName = $window.FindName("TxtComputerName")
$TxtUserName     = $window.FindName("TxtUserName")
$TxtCpu          = $window.FindName("TxtCpu")
$TxtRam          = $window.FindName("TxtRam")
$TxtGpu          = $window.FindName("TxtGpu")
