$Btn1 = $window.FindName("Btn1"); $Btn2 = $window.FindName("Btn2")
$Btn3 = $window.FindName("Btn3"); $Btn4 = $window.FindName("Btn4")
$Btn5 = $window.FindName("Btn5"); $Btn6 = $window.FindName("Btn6")
$Btn7 = $window.FindName("Btn7"); $Btn8 = $window.FindName("Btn8")
