$LogPanel  = $window.FindName("LogPanel"); $script:LogPanel = $LogPanel
$LogScroll = $window.FindName("LogScroll"); $script:LogScroll = $LogScroll; $script:LogScroll = $LogScroll

$BtnTweakStandard = $window.FindName("BtnTweakStandard")
$BtnTweakAdvanced = $window.FindName("BtnTweakAdvanced")
