$BtnClose.Add_Click({ $script:mainWindow.Close() })

function global:Add-LogLine {
    param([string]$Text, [string]$Color = "#E8E8E8")
    $action = {
        param($t, $c)
        try {
            $tb = New-Object System.Windows.Controls.TextBlock
            $tb.Text = $t
            $tb.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($c)
            $tb.FontFamily = "Consolas"
            $tb.FontSize = 11.5
            $tb.TextWrapping = "Wrap"
            $tb.Margin = "0,1,0,1"
            if ($script:LogPanel) {
                $script:LogPanel.Children.Add($tb) | Out-Null
                if ($script:LogScroll) { $script:LogScroll.ScrollToEnd() }
            }
            # Force UI paint so log updates while long tasks run
            try {
                $disp = [System.Windows.Threading.Dispatcher]::CurrentDispatcher
                $disp.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Background)
            } catch {}
        } catch {}
    }
    try {
        $disp = [System.Windows.Threading.Dispatcher]::CurrentDispatcher
        if ($disp -and -not $disp.CheckAccess()) {
            $disp.Invoke($action, $Text, $Color)
        } else {
            & $action $Text $Color
            # pump messages so window stays responsive on UI thread
            try {
                $disp.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Background)
            } catch {}
        }
    } catch {
        try { & $action $Text $Color } catch {}
    }
}

function Set-SpecFields {
    # Read the actual machine values instead of showing fixed example hardware.
    $TxtOs.Text = Get-SafeValue {
        $osInfo = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $caption = if ($osInfo.Caption) { $osInfo.Caption.Trim() } else { "Windows" }
        $version = if ($osInfo.Version) { " (v$($osInfo.Version))" } else { "" }
        "$caption$version"
    }

    $TxtComputerName.Text = Get-SafeValue { $env:COMPUTERNAME }
    $TxtUserName.Text     = Get-SafeValue { $env:USERNAME }

    $TxtCpu.Text = Get-SafeValue {
        $cpuInfo = Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop |
            Sort-Object -Property DeviceID |
            Select-Object -First 1
        if ([string]::IsNullOrWhiteSpace([string]$cpuInfo.Name)) {
            throw "CPU name unavailable"
        }
        $cpuInfo.Name.Trim()
    }

    $TxtRam.Text = Get-SafeValue {
        $memoryInfo = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
        if (-not $memoryInfo.TotalPhysicalMemory) {
            throw "Physical memory unavailable"
        }
        $ramGb = [math]::Round([double]$memoryInfo.TotalPhysicalMemory / 1GB, 1)
        "{0:N1} GB" -f $ramGb
    }

    $TxtGpu.Text = Get-SafeValue {
        $gpuNames = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop |
            Where-Object {
                $_.Name -and $_.Name -notmatch "Microsoft Basic Display Adapter"
            } |
            Select-Object -ExpandProperty Name)
        if ($gpuNames.Count -eq 0) {
            throw "GPU name unavailable"
        }
        ($gpuNames | Select-Object -Unique) -join " / "
    }

    $TxtNet.Text = Get-SafeValue {
        $adapterNames = @(Get-NetAdapter -ErrorAction Stop |
            Where-Object {
                $_.Status -eq "Up" -and $_.InterfaceDescription
            } |
            Select-Object -ExpandProperty InterfaceDescription)
        if ($adapterNames.Count -eq 0) {
            throw "No active adapter"
        }
        ($adapterNames | Select-Object -Unique) -join " / "
    } "No Adapter Found"
}
Set-SpecFields

function Invoke-UGUiPump {
    # keep WPF responsive during long registry loops
    try {
        [void][System.Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke(
            [System.Windows.Threading.DispatcherPriority]::Background,
            [Action]{}
        )
    } catch {}
    if (($script:Ok % 80) -eq 0) {
        try {
            [System.Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke(
                [Action]{},
                [System.Windows.Threading.DispatcherPriority]::Background
            )
        } catch {}
    }
}


function Log-Name {
    param([string]$Name, [string]$Status = 'ok')
    if ($null -eq $script:Ok) { $script:Ok = 0 }
    if ($null -eq $script:Fail) { $script:Fail = 0 }
    if ($Status -ne 'ok') { $script:Fail++; return }
    $script:Ok++
    $clean = "$Name"
    $clean = $clean -replace '(?i)^(AspasV2|Aspas|Flow|Assassin|FLSB|InternetAspas|Internet|KaiV2|KaiPrime|Kai|UFA|ANTI|Anti|RadubGod|Radub|AironPlus|AironLean|Airon|WongNua|Wong|Venom|Sayhan|HitFeel|MaxAggression|NetworkForce|NF|DENSE|Ultra|R1|God|Top|Slurppy|Prime|Dektin|More|HEAVY|Lean|Final|Extra|Bitcex|SyncProject|Sync|BTX|Bangbath|Bastien|Jacob|JacobReg|ShiNet|Shi|MoreAggression|U18|StickHard|Rank1|Rank12|Seal|Lock|UserLocked|Conflict|Resolve|ForceStick|ProjectWong|Stephod|KingPlus|PoolPlus|67shop|ResourcesBoost|FLSBResources|FlsbSync|Gpedit|KeySeal)_', ''
    $clean = $clean -replace '(?i)^(FullNet|FullSetting|UltraNet|UltraSetting|DENSE_Net|DENSE_Setting|MAX_Net|Setting|Net|Heavy|Pack|Lean_Net|Lean_Setting)_', ''
    $clean = $clean -replace '(?i)^(Lock\s+|UserLocked\s+|Best\s+)', ''
    $clean = $clean.Trim()
    if ([string]::IsNullOrWhiteSpace($clean)) { $clean = $Name }
    if ($null -eq $script:LoggedNames) { $script:LoggedNames = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase) }
    if (-not $script:LoggedNames.Add($clean)) { return }
    try {
        if (Get-Command Write-LogTime -EA SilentlyContinue) { Write-LogTime $clean '#E8E8E8' }
        elseif (Get-Command Add-LogLine -EA SilentlyContinue) {
            $ts = Get-Date -Format 'HH:mm:ss'
            Add-LogLine -Text "[$ts] $clean" -Color '#E8E8E8'
        }
    } catch {}
    if (($script:Ok % 25) -eq 0) {
        try { [System.Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Background) } catch {}
    }
}

function Write-LogTime {
    param([string]$Msg, [string]$Color = "#E8E8E8")
    $timestamp = Get-Date -Format "HH:mm:ss"
    try { Add-LogLine -Text "[$timestamp] $Msg" -Color $Color } catch {}
    # Non-blocking UI pump so long bulk runs do not freeze the window
    try {
        [void][System.Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke(
            [System.Windows.Threading.DispatcherPriority]::Background,
            [Action]{}
        )
    } catch {}
}

Write-LogTime "Project UndergroundPrime READY TO USE." "#33fd00"

$BtnRefreshSpecs.Add_Click({
    Write-LogTime "Manual spec refresh requested." "#9F9F9F"
    Set-SpecFields
    Write-LogTime "Specs reloaded." "#00EBA0"
})

$Btn1.Add_Click({
    if ($script:UGRunning) { Write-LogTime "Already running..." "#F2F2F2"; return }
    $script:UGRunning = $true
    try { $Btn1.IsEnabled = $false; $Btn2.IsEnabled = $false } catch {}
    Write-LogTime "1. RUN SETTING UndergroundPrime..." "#FFFFFF"
    try {
        try { Set-TimerResolution05 } catch {}
        Write-LogTime "» applying Setting bulk (UI stays alive)..." "#E8E8E8"
        Invoke-MergedAllSources -Mode Setting
        Write-LogTime ("SETTING done | applied={0} values" -f [int]$script:Ok) "#33fd00"
    } catch {
        Write-LogTime ("» Setting error: " + $_.Exception.Message) "#F2F2F2"
    } finally {
        $script:UGRunning = $false
        try { $Btn1.IsEnabled = $true; $Btn2.IsEnabled = $true } catch {}
    }
})

$Btn2.Add_Click({
    if ($script:UGRunning) { Write-LogTime "Already running..." "#F2F2F2"; return }
    $script:UGRunning = $true
    try { $Btn1.IsEnabled = $false; $Btn2.IsEnabled = $false } catch {}
    Write-LogTime "2. RUN NETWORK UndergroundPrime..." "#FFFFFF"
    try {
        Write-LogTime "» applying Network bulk (UI stays alive)..." "#E8E8E8"
        Invoke-MergedAllSources -Mode Network
        Write-LogTime ("NETWORK done | applied={0} values" -f [int]$script:Ok) "#33fd00"
        # Fire-and-forget netsh (no wait, no Invoke-Expression hang)
        # direct netsh (ArgumentList string form often fails)
        $netCmdSets = @(
            @('int','tcp','set','global','autotuninglevel=normal'),
            @('int','tcp','set','global','chimney=disabled'),
            @('int','tcp','set','global','ecncapability=disabled'),
            @('int','tcp','set','global','timestamps=disabled'),
            @('int','tcp','set','global','rss=enabled'),
            @('int','tcp','set','global','rsc=disabled'),
            @('int','tcp','set','global','fastopen=enabled'),
            @('int','tcp','set','global','dca=enabled'),
            @('int','tcp','set','global','netdma=disabled'),
            @('int','tcp','set','global','initialRto=1000'),
            @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp')
        )
        foreach ($a in $netCmdSets) {
            try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
        }
        try { Apply-NetworkForce } catch {}
        # NIC registry quick pass (no # $1  # disabled: causes hang
        try {
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(@('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),@('*RSS','1'),@('*ReceiveBuffers','512'),@('*TransmitBuffers','512'))) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                }
            }
        } catch {}
        Write-LogTime "RUN NETWORK UndergroundPrime SUCCESS." "#33fd00"
    } catch {
        Write-LogTime ("» Network error: " + $_.Exception.Message) "#F2F2F2"
    } finally {
        $script:UGRunning = $false
        try { $Btn1.IsEnabled = $true; $Btn2.IsEnabled = $true } catch {}
    }
})

$Btn3.Add_Click({
    Write-LogTime "Refreshing dashboard data..." "#E8E8E8"
Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "NetworkThrottlingIndex" -Value 10 -Type DWord
Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "SystemResponsiveness" -Value 20 -Type DWord
Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "NetworkThrottlingIndex1" -ErrorAction SilentlyContinue
Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "SystemResponsiveness1" -ErrorAction SilentlyContinue

$tasks = @("Audio", "Capture", "DisplayPostProcessing", "Distribution", "Games", "Low Latency", "Playback", "Pro Audio", "Window Manager")
foreach ($task in $tasks) {
    $taskPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\$task"
    Remove-ItemProperty -Path $taskPath -Name "Affinity" -ErrorAction SilentlyContinue
    Remove-ItemProperty -Path $taskPath -Name "Clock Rate" -ErrorAction SilentlyContinue
    Remove-ItemProperty -Path $taskPath -Name "BackgroundPriority" -ErrorAction SilentlyContinue
}
Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" -Name "GPU Priority" -Value 8 -Type DWord
Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" -Name "Priority" -Value 2 -Type DWord
