            "UndergroundPrime_NetworkTweaker_{0}.ps1" -f [guid]::NewGuid().ToString("N")
        )
        Set-Content -LiteralPath $tempScript -Value $script:NetworkTweakerSource -Encoding UTF8 -Force -ErrorAction Stop

        $psExe = Join-Path $env:WINDIR "System32\WindowsPowerShell\v1.0\powershell.exe"
        if (-not (Test-Path -LiteralPath $psExe -PathType Leaf)) { $psExe = "powershell.exe" }
        $psArgs = @(
            "-NoProfile", "-ExecutionPolicy", "Bypass", "-STA",
            "-File", $tempScript
        )
        $tweakerProcess = Start-Process -FilePath $psExe -ArgumentList $psArgs -WorkingDirectory ([System.IO.Path]::GetTempPath()) -Verb RunAs -PassThru -ErrorAction Stop
        $tweakerProcess.EnableRaisingEvents = $true
