        $tcpOptimizerPath = $candidatePaths | Select-Object -First 1
        if (-not $tcpOptimizerPath) {
            $command = Get-Command "TCPOptimizer.exe" -ErrorAction SilentlyContinue
            if ($command) { $tcpOptimizerPath = $command.Source }
        }

        if (-not $tcpOptimizerPath) {
            $tcpOptimizerPath = Join-Path ([System.IO.Path]::GetTempPath()) (
                "UndergroundPrime_TCPOptimizer_{0}.exe" -f [guid]::NewGuid().ToString("N")
            )
            [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
            $tcpClient = New-Object System.Net.WebClient
            try {
                [byte[]]$tcpOptimizerBytes = $tcpClient.DownloadData($script:TCPOptimizerPayloadUrl)
            } finally {
                $tcpClient.Dispose()
            }
            if ($tcpOptimizerBytes.Length -lt 1024) { throw "TCP Optimizer payload is unexpectedly small." }
            $sha256 = [System.Security.Cryptography.SHA256]::Create()
            try {
                $actualTcpOptimizerHash = ([BitConverter]::ToString($sha256.ComputeHash($tcpOptimizerBytes))).Replace("-", "").ToLowerInvariant()
            } finally {
                $sha256.Dispose()
            }
            if ($actualTcpOptimizerHash -ne $script:TCPOptimizerSha256) { throw "TCP Optimizer integrity check failed." }
            [System.IO.File]::WriteAllBytes($tcpOptimizerPath, $tcpOptimizerBytes)
            $downloadedTempPath = $tcpOptimizerPath
        }

        $tcpProcess = Start-Process -FilePath $tcpOptimizerPath -WorkingDirectory (Split-Path -Parent $tcpOptimizerPath) -PassThru -ErrorAction Stop
        if ($downloadedTempPath) {
            $tcpProcess.EnableRaisingEvents = $true
            Register-ObjectEvent -InputObject $tcpProcess -EventName Exited -MessageData $downloadedTempPath -Action {
                $pathToRemove = $event.MessageData
                if ($pathToRemove -and (Test-Path -LiteralPath $pathToRemove -PathType Leaf)) {
                    Remove-Item -LiteralPath $pathToRemove -Force -ErrorAction SilentlyContinue
                }
            } | Out-Null
        }
        Write-LogTime "» TCP Optimizer launched: $tcpOptimizerPath" "#00EBA0"
    } catch {
        if ($tcpOptimizerPath -and (Test-Path -LiteralPath $tcpOptimizerPath -PathType Leaf) -and $tcpOptimizerPath -like "*UndergroundPrime_TCPOptimizer_*.exe") {
            Remove-Item -LiteralPath $tcpOptimizerPath -Force -ErrorAction SilentlyContinue
        }
        Write-LogTime "เปิด TCP Optimizer ไม่สำเร็จ: $($_.Exception.Message)" "#F2F2F2"
        [System.Windows.MessageBox]::Show(
            $_.Exception.Message,
            "Project UndergroundPrime - TCP Optimizer"
        ) | Out-Null
    }
})


function Remove-SafeJunkDirectory {
    param(
        [AllowEmptyString()][string]$Path,
        [string]$Label = $Path
    )

    $result = [ordered]@{
        Label   = $Label
        Path    = $Path
        Items   = 0
        Failed  = 0
        Bytes   = [int64]0
        Skipped = $false
    }

    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path -PathType Container)) {
        $result.Skipped = $true
        return [pscustomobject]$result
    }

    try {
        $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).Path
        if ($resolved -match '^[A-Za-z]:\\?$') {
            $result.Skipped = $true
            return [pscustomobject]$result
        }

        $items = @(Get-ChildItem -LiteralPath $resolved -Force -ErrorAction SilentlyContinue)
        foreach ($item in $items) {
            try {
                if (-not $item.PSIsContainer -and $null -ne $item.Length) {
                    $result.Bytes += [int64]$item.Length
                }
                Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction Stop
                $result.Items++
            } catch {
                $result.Failed++
            }
        }

    } catch {
        $result.Failed++
    }

    return [pscustomobject]$result
}

function Invoke-DeepJunkCleanup {
    $summary = [ordered]@{
        Items  = 0
        Failed = 0
        Bytes  = [int64]0
    }

    # Only the six categories requested by the user are included here.
    $paths = @(
        @{ Label = "User TEMP"; Path = $env:TEMP },
        @{ Label = "User TMP"; Path = $env:TMP },
        @{ Label = "Windows TEMP"; Path = (Join-Path $env:WINDIR "Temp") },
        @{ Label = "Windows Prefetch"; Path = (Join-Path $env:WINDIR "Prefetch") },
        @{ Label = "Windows Error Reports - Archive"; Path = (Join-Path $env:ProgramData "Microsoft\Windows\WER\ReportArchive") },
        @{ Label = "Windows Error Reports - Queue"; Path = (Join-Path $env:ProgramData "Microsoft\Windows\WER\ReportQueue") }
    )

    foreach ($spec in $paths) {
        $result = Remove-SafeJunkDirectory -Path $spec.Path -Label $spec.Label
        $summary.Items += $result.Items
        $summary.Failed += $result.Failed
        $summary.Bytes += $result.Bytes
    }

    try {
        Clear-RecycleBin -Force -ErrorAction Stop
    } catch {
        $summary.Failed++
    }

    return [pscustomobject]$summary
}


# =====================================================================
# MERGED PAYLOAD: priority core > fill
# (apply order: .7z first ... Settings last = wins)
# Injected into Project UndergroundPrime
# =====================================================================
function Set-RegTweak {
    param([string]$Path, [string]$Name, $Value, [string]$Type = "DWord")
    try {
        if (-not (Test-Path $Path)) { New-Item -Path $Path -Force | Out-Null }
        New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType $Type -Force | Out-Null
        return $true
    } catch { return $false }
}

function Get-IniLineKey {
    param([string]$Line)
    $t = $Line.Trim().TrimStart([char]0xFEFF)
    if ($t -eq "" -or $t.StartsWith(";") -or $t.StartsWith("#")) { return $null }
    if ($t.StartsWith("[") -and $t.EndsWith("]")) { return $null }
    if ($t.Contains("=")) {
        return ($t.Split("=", 2)[0]).Trim().ToLower()
    } else {
        return (($t -split '\s+', 2)[0]).ToLower()
    }
}

# Reads a text file as lines while stripping a leading UTF-8 BOM character.
# Get-Content -Encoding UTF8 sometimes leaves a literal U+FEFF (BOM) glued to
# the very first line (e.g. the first line becomes "<BOM>[Game]" instead of
# "[Game]"). That invisible character makes the "[Game]" header fail the
# StartsWith("[") check in Merge-IniAppendOnly, so the whole section is
# treated as if it didn't exist and everything under it (like a custom
# IVPath= line) ends up orphaned above the real section instead of inside
# it - which the game then ignores, looking exactly like the line got
# deleted. Reading with .NET directly and manually stripping the BOM avoids
# that entirely.
function Read-IniLinesSafe {
    param([string]$Path)
    $raw = [System.IO.File]::ReadAllText($Path)
    if ($raw.Length -gt 0 -and $raw[0] -eq [char]0xFEFF) {
        $raw = $raw.Substring(1)
    }
    if ($raw -eq "") { return @() }
    return ($raw -split "`r`n|`n")
}

# Writes ini lines as plain UTF-8 with NO byte-order-mark, so a future read
# of this same file (by this script or by FiveM itself) never runs into the
# BOM problem described above.
function Write-IniLinesSafe {
    param([string]$Path, [string[]]$Lines)
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllLines($Path, $Lines, $utf8NoBom)
}

# Merges $TargetLines into $ExistingLines WITHOUT removing or modifying any
# existing line. Only keys that are not already present under their section
# are appended (at the end of that section, or as a brand new section).
# Strips ANY leading invisible/control characters (BOM, zero-width space,
# zero-width joiner/non-joiner, word-joiner, stray control chars, etc.),
# not just the classic U+FEFF BOM. This is what makes section-header
# detection ("does this line start with '[' ?") reliable even when some
# other program (a text editor, FiveM itself, a re-save) glues an
# invisible character onto the front of "[Game]". Without this, that
# single invisible char makes "[Game]" fail the StartsWith("[") check,
# the whole section is treated as missing, and anything under it -
# like a hand-added "IVPath=" line - ends up orphaned above the
# recreated section instead of inside it.
function Remove-InvisiblePrefix {
    param([string]$s)
    $i = 0
    while ($i -lt $s.Length) {
        $code = [int][char]$s[$i]
        if ($code -eq 0xFEFF -or $code -eq 0x200B -or $code -eq 0x200C -or
            $code -eq 0x200D -or $code -eq 0x2060 -or [char]::IsControl($s[$i])) {
            $i++
        } else {
            break
        }
    }
    if ($i -gt 0) { return $s.Substring($i) } else { return $s }
}

function Merge-IniAppendOnly {
    param(
        [string[]]$ExistingLines,
        [string[]]$TargetLines
    )

    $sections = [ordered]@{}
    $current  = ""
    $sections[$current] = New-Object System.Collections.Generic.List[string]

    foreach ($line in $ExistingLines) {
        $trim = Remove-InvisiblePrefix ($line.Trim())
        if ($trim.StartsWith("[") -and $trim.EndsWith("]")) {
            $current = $trim
            if (-not $sections.Contains($current)) { $sections[$current] = New-Object System.Collections.Generic.List[string] }
        } else {
            $sections[$current].Add($line)
        }
    }

    $targetSections = [ordered]@{}
    $tcurrent = ""
    foreach ($line in $TargetLines) {
        $trim = Remove-InvisiblePrefix ($line.Trim())
        if ($trim -eq "") { continue }
        if ($trim.StartsWith("[") -and $trim.EndsWith("]")) {
            $tcurrent = $trim
            if (-not $targetSections.Contains($tcurrent)) { $targetSections[$tcurrent] = New-Object System.Collections.Generic.List[string] }
        } else {
            if (-not $targetSections.Contains($tcurrent)) { $targetSections[$tcurrent] = New-Object System.Collections.Generic.List[string] }
            $targetSections[$tcurrent].Add($line)
        }
    }

    # --- Repair pass ---------------------------------------------------
    # If a previous run (or FiveM itself) ever dropped a section header,
    # keys that belong under e.g. [Game] can end up sitting in the
    # "no header yet" area at the very top of the file, floating outside
    # any section. That's functionally the same as those keys being
    # deleted, since the game only reads keys that are under the right
    # header. Detect any such orphaned line whose key matches something
    # we know belongs in one of our target sections, and move it back
    # under the correct header instead of leaving it orphaned (or, worse,
    # adding a duplicate copy under the correct header while the broken
    # orphan stays behind).
    foreach ($secName in $targetSections.Keys) {
        if ($secName -eq "") { continue }
        $keysBelongingHere = @{}
        foreach ($tLine in $targetSections[$secName]) {
            $k = Get-IniLineKey $tLine
            if ($k) { $keysBelongingHere[$k] = $true }
        }

        # IVPath isn't one of the keys this tool writes, but it's a
        # critical hand-set/FiveM-set key that always lives under [Game].
        # If it ever gets orphaned outside any section, rehome it too -
        # otherwise it would just sit there separated from the rest of
        # [Game] forever (which is exactly the "values getting split
        # apart from IVPath" symptom this repair pass exists to fix).
        if ($secName -eq "[Game]") { $keysBelongingHere["ivpath"] = $true }

        if ($keysBelongingHere.Count -eq 0) { continue }

        $stillOrphaned = New-Object System.Collections.Generic.List[string]
        $toRehome      = New-Object System.Collections.Generic.List[string]
        foreach ($oLine in $sections[""]) {
            $ok = Get-IniLineKey $oLine
            if ($ok -and $keysBelongingHere.ContainsKey($ok)) {
                $toRehome.Add($oLine)
            } else {
                $stillOrphaned.Add($oLine)
            }
        }
        if ($toRehome.Count -gt 0) {
            $sections[""] = $stillOrphaned
            if (-not $sections.Contains($secName)) { $sections[$secName] = New-Object System.Collections.Generic.List[string] }
            foreach ($m in $toRehome) { $sections[$secName].Add($m) }
        }
    }
    # --------------------------------------------------------------------

    $addedCount = 0
    foreach ($secName in $targetSections.Keys) {
        if (-not $sections.Contains($secName)) {
            $sections[$secName] = New-Object System.Collections.Generic.List[string]
        }

        # Which keys does this target section manage, and what line should
        # represent each one? (Target's default line, unless overridden below.)
        $targetKeyOrder  = New-Object System.Collections.Generic.List[string]
        $targetLineByKey = @{}
        foreach ($tLine in $targetSections[$secName]) {
            $k = Get-IniLineKey $tLine
            if ($k -and -not $targetLineByKey.ContainsKey($k)) {
                $targetKeyOrder.Add($k)
                $targetLineByKey[$k] = $tLine
            }
        }
        if ($targetKeyOrder.Count -eq 0) { continue }

        # Pull the managed keys out of the section (wherever they currently
        # sit) so they can be grouped together in one place. Everything
        # else in the section stays exactly where it is. A user's existing
        # value always wins over the target's default - we only ever fill
        # in a key that isn't there yet.
        $otherLines        = New-Object System.Collections.Generic.List[string]
        $existingLineByKey = @{}
        foreach ($eLine in $sections[$secName]) {
            $k = Get-IniLineKey $eLine
            if ($k -and $targetLineByKey.ContainsKey($k) -and -not $existingLineByKey.ContainsKey($k)) {
                $existingLineByKey[$k] = $eLine
            } else {
                $otherLines.Add($eLine)
            }
        }

        $managedBlock = New-Object System.Collections.Generic.List[string]
        foreach ($k in $targetKeyOrder) {
            if ($existingLineByKey.ContainsKey($k)) {
                $managedBlock.Add($existingLineByKey[$k])
            } else {
                $managedBlock.Add($targetLineByKey[$k])
                $addedCount++
            }
        }

        # Place the managed block right after the last non-blank "other"
        # line, so it stays grouped with the section's real content
        # instead of drifting next to whatever section follows.
        $insertAt = $otherLines.Count
        for ($i = $otherLines.Count - 1; $i -ge 0; $i--) {
            if ($otherLines[$i].Trim() -ne "") { $insertAt = $i + 1; break }
            if ($i -eq 0) { $insertAt = 0 }
        }

        $rebuilt = New-Object System.Collections.Generic.List[string]
        for ($i = 0; $i -lt $insertAt; $i++) { $rebuilt.Add($otherLines[$i]) }
        foreach ($m in $managedBlock) { $rebuilt.Add($m) }
        for ($i = $insertAt; $i -lt $otherLines.Count; $i++) { $rebuilt.Add($otherLines[$i]) }

        $sections[$secName] = $rebuilt
    }

    # Trim trailing blank lines within each section. Without this, every
    # run would leave the previous run's blank-line gap in place AND add
    # its own separator blank line before the next header, so the file
    # would grow an extra blank line each time the button is clicked.
    foreach ($secName in @($sections.Keys)) {
        $lst = $sections[$secName]
        while ($lst.Count -gt 0 -and $lst[$lst.Count - 1].Trim() -eq "") {
            $lst.RemoveAt($lst.Count - 1)
        }
    }

    $output = New-Object System.Collections.Generic.List[string]
    foreach ($secName in $sections.Keys) {
        if ($secName -ne "") {
            if ($output.Count -gt 0) { $output.Add("") }
            $output.Add($secName)
        }
        foreach ($l in $sections[$secName]) { $output.Add($l) }
    }

    $originalJoined = ($ExistingLines -join "`n")
    $outputJoined   = ($output -join "`n")
    $changed        = ($originalJoined -ne $outputJoined)

    return [PSCustomObject]@{ Lines = $output; Added = $addedCount; Changed = $changed }
}



# FilterKeys removed


function Set-TimerResolution05 {
    Write-LogTime "Setting Timer Resolution 0.5 ms (persistent)..." "#FFFFFF"
    try {
        $k = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel"
        if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
        Set-ItemProperty -LiteralPath $k -Name "GlobalTimerResolutionRequests" -Value 1 -Type DWord -Force
        Write-LogTime "» GlobalTimerResolutionRequests = 1" "#E0E0E0"
    } catch {
        Write-LogTime "» GlobalTimerResolutionRequests: $($_.Exception.Message)" "#F2F2F2"
    }
    try {
        if (-not ("UGTimerRes" -as [type])) {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class UGTimerRes {
    [DllImport("ntdll.dll")] public static extern int NtSetTimerResolution(uint DesiredResolution, bool SetResolution, out uint CurrentResolution);
    [DllImport("winmm.dll")] public static extern uint timeBeginPeriod(uint uMilliseconds);
}
"@
        }
        $cur = [uint32]0
        $hr = [UGTimerRes]::NtSetTimerResolution(5000, $true, [ref]$cur)
        Write-LogTime ("» NtSetTimerResolution(0.5ms) hr={0} current={1}" -f $hr, $cur) "#E0E0E0"
        try { [void][UGTimerRes]::timeBeginPeriod(1) } catch {}
    } catch {
        Write-LogTime "» TimerResolution API: $($_.Exception.Message)" "#F2F2F2"
    }
    try {
        $helperDir = Join-Path $env:ProgramData "UndergroundPrime"
        if (-not (Test-Path $helperDir)) { New-Item -ItemType Directory -Path $helperDir -Force | Out-Null }
        $helperPs1 = Join-Path $helperDir "TimerResolution05.ps1"
        $helperBody = @'
$ErrorActionPreference = "SilentlyContinue"
try {
    $k = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel"
    if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
    Set-ItemProperty -LiteralPath $k -Name "GlobalTimerResolutionRequests" -Value 1 -Type DWord -Force
} catch {}
try {
    if (-not ("UGTimerResBoot" -as [type])) {
        Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class UGTimerResBoot {
    [DllImport("ntdll.dll")] public static extern int NtSetTimerResolution(uint DesiredResolution, bool SetResolution, out uint CurrentResolution);
    [DllImport("winmm.dll")] public static extern uint timeBeginPeriod(uint uMilliseconds);
}
"@
    }
    $cur = [uint32]0
    [void][UGTimerResBoot]::NtSetTimerResolution(5000, $true, [ref]$cur)
    try { [void][UGTimerResBoot]::timeBeginPeriod(1) } catch {}
} catch {}
while ($true) {
    try {
        $cur = [uint32]0
        [void][UGTimerResBoot]::NtSetTimerResolution(5000, $true, [ref]$cur)
    } catch {}
    Start-Sleep -Seconds 60
}
'@
        Set-Content -Path $helperPs1 -Value $helperBody -Encoding UTF8 -Force
        $taskName = "UndergroundPrime_TimerResolution05"
        try { Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        $psExe = Join-Path $env:WINDIR "System32\WindowsPowerShell\v1.0\powershell.exe"
        $arg = "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$helperPs1`""
        $null = & schtasks.exe /Create /F /TN $taskName /SC ONLOGON /RL HIGHEST /TR "`"$psExe`" $arg" 2>&1
        Write-LogTime "» Scheduled Task ONLOGON: $taskName" "#00EBA0"
        try {
            Start-Process -FilePath $psExe -ArgumentList $arg -WindowStyle Hidden
            Write-LogTime "» Timer helper started" "#E0E0E0"
        } catch {}
    } catch {
        Write-LogTime "» Persist timer failed: $($_.Exception.Message)" "#F2F2F2"
    }
}









function Apply-VenomExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # venom.exe tweaks rank 3+. Mouse/Keyboard = HIGH profile. User locks applied later.
    function _Vn([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }
    if ($Mode -in @('Setting','All')) {
        try {
            # Mouse HIGH: queue 0x64 (100), no accel
            $mq = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mq)) { New-Item -Path $mq -Force | Out-Null }
            New-ItemProperty -Path $mq -Name 'MouseDataQueueSize' -PropertyType DWord -Value 0x64 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mq -Name 'MouseUpdateInterval' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $kbd = 'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters'
            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDataQueueSize' -PropertyType DWord -Value 0x14 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSpeed' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold1' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold2' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSensitivity' -Value '10' -Force -EA SilentlyContinue
            # Keyboard HIGH response (delay 0 / speed 31) — queue size locked by user to 0xA
            Set-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardDelay' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardSpeed' -Value '31' -Force -EA SilentlyContinue
            _Vn 'Extra MouseKB'
        } catch { _Vn 'Extra MouseKB' 'fail' }
        try {
            $sp = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $sp)) { New-Item -Path $sp -Force | Out-Null }
            New-ItemProperty -Path $sp -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value 0xffffffff -Force -EA SilentlyContinue | Out-Null
            $g = Join-Path $sp 'Tasks\Games'
            if (-not (Test-Path $g)) { New-Item -Path $g -Force | Out-Null }
            New-ItemProperty -Path $g -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            _Vn 'Extra MMCSS'
        } catch {}
        try {
            $gd = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
            if (-not (Test-Path $gd)) { New-Item -Path $gd -Force | Out-Null }
            New-ItemProperty -Path $gd -Name 'HwSchMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $mm = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force | Out-Null }
            New-ItemProperty -Path $mm -Name 'LargeSystemCache' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mm -Name 'IoPageLockLimit' -PropertyType DWord -Value 0x20000000 -Force -EA SilentlyContinue | Out-Null
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolution' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            # IRQ priority (not Win32Priority — locked by user)
            $pc = 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl'
            if (-not (Test-Path $pc)) { New-Item -Path $pc -Force | Out-Null }
            New-ItemProperty -Path $pc -Name 'IRQ8Priority' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _Vn 'Extra GPU/Mem/Timer'
        } catch {}
        try {
            $hid = 'HKLM:\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters'
            if (-not (Test-Path $hid)) { New-Item -Path $hid -Force | Out-Null }
            New-ItemProperty -Path $hid -Name 'PollingRate' -PropertyType DWord -Value 0x500 -Force -EA SilentlyContinue | Out-Null
            _Vn 'Extra HidUsb'
        } catch {}
        try {
            $msmq = 'HKLM:\SOFTWARE\Microsoft\MSMQ\Parameters'
            if (-not (Test-Path $msmq)) { New-Item -Path $msmq -Force | Out-Null }
            New-ItemProperty -Path $msmq -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $msmq -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $msmq -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _Vn 'Extra MSMQ'
        } catch {}
        try {
            $null = & bcdedit.exe /set useplatformclock No 2>&1
            $null = & bcdedit.exe /set useplatformtick Yes 2>&1
            $null = & bcdedit.exe /set disabledynamictick Yes 2>&1
            _Vn 'Extra BCD'
        } catch { _Vn 'Extra BCD' 'fail' }
        try {
            $null = & powercfg.exe -setactive SCHEME_MIN 2>&1
            _Vn 'Extra Power'
        } catch {}
    }
    if ($Mode -in @('Network','All')) {
        try {
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force | Out-Null }
            New-ItemProperty -Path $afd -Name 'DefaultSendWindow' -PropertyType DWord -Value 0x262144 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $afd -Name 'DefaultReceiveWindow' -PropertyType DWord -Value 0x262144 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $afd -Name 'DisableAddressSharing' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
            New-ItemProperty -Path $tp -Name 'TcpNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpTimedWaitDelay' -PropertyType DWord -Value 0x1e -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'DefaultTTL' -PropertyType DWord -Value 0x40 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpMaxDataRetransmissions' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpMaxDupAcks' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'DisableTcpChimneyOffload' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpWindowSize' -PropertyType DWord -Value 0x100000 -Force -EA SilentlyContinue | Out-Null
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force | Out-Null }
            New-ItemProperty -Path $dns -Name 'MaxNegativeCacheTtl' -PropertyType DWord -Value 0x300 -Force -EA SilentlyContinue | Out-Null
            _Vn 'Extra TCP'
        } catch { _Vn 'Extra TCP' 'fail' }
        foreach ($c in @(
            'int tcp set global rss=enabled',
            'int tcp set global autotuninglevel=normal',
            'int tcp set global ecncapability=disabled',
            'int tcp set heuristics disabled',
            'int tcp set global timestamps=disabled',
            'int tcp set global rsc=disabled'
        )) {
            try {
                $parts = $c.Split(' ')
                $null = & netsh.exe @parts 2>&1
                _Vn $c
            } catch { _Vn $c 'fail' }
        }
        try { $null = & ipconfig.exe /flushdns 2>&1; _Vn 'flushdns' } catch {}
    }
}


function Apply-SayhanExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # Extra pack aggression. User locks applied later.
    function _Sy([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }
    if ($Mode -in @('Network','All')) {
        try {
            # QoS DSCP46 with higher throttle (Sayhan rates more aggressive than Kai)
            foreach ($pair in @(
                @('SayhanKDM','FiveM.exe','25000'),
                @('SayhanKDM1','FiveM_GTAProcess.exe','250000')
            )) {
                $qos = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\$($pair[0])"
                if (-not (Test-Path $qos)) { New-Item -Path $qos -Force | Out-Null }
                New-ItemProperty -Path $qos -Name 'Version' -PropertyType String -Value '1.0' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'Application Name' -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                foreach ($v in @('Protocol','Local Port','Local IP','Local IP Prefix Length','Remote Port','Remote IP','Remote IP Prefix Length')) {
                    New-ItemProperty -Path $qos -Name $v -PropertyType String -Value '*' -Force -EA SilentlyContinue | Out-Null
                }
                New-ItemProperty -Path $qos -Name 'DSCP Value' -PropertyType String -Value '46' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'Throttle Rate' -PropertyType String -Value $pair[2] -Force -EA SilentlyContinue | Out-Null
            }
            $tq = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\QoS'
            if (-not (Test-Path $tq)) { New-Item -Path $tq -Force | Out-Null }
            New-ItemProperty -Path $tq -Name 'Do not use NLA' -PropertyType String -Value '1' -Force -EA SilentlyContinue | Out-Null
            _Sy 'Sayhan QoS DSCP46'
        } catch { _Sy 'Sayhan QoS' 'fail' }
        try {
            $classKey = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $classKey) {
                $vals = @{
                    '*FlowControl'='0'; '*InterruptModeration'='0'; '*PriorityVLANTag'='1'
                    '*RSS'='1'; '*NumRssQueues'='1'; '*LsoV2IPv4'='0'; '*LsoV2IPv6'='0'
                    '*IPChecksumOffloadIPv4'='0'; '*TCPChecksumOffloadIPv4'='0'; '*UDPChecksumOffloadIPv4'='0'
                    '*WakeOnPattern'='0'; '*WakeOnMagicPacket'='0'; '*EEE'='0'
                    '*ReceiveBuffers'='16840'; '*TransmitBuffers'='8'; '*JumboPacket'='1514'
                }
                Get-ChildItem $classKey -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d+$' } | ForEach-Object {
                    foreach ($k in $vals.Keys) {
                        try { New-ItemProperty -Path $_.PSPath -Name $k -PropertyType String -Value $vals[$k] -Force -EA SilentlyContinue | Out-Null } catch {}
                    }
                }
            }
            _Sy 'Sayhan NIC'
        } catch { _Sy 'Sayhan NIC' 'fail' }
        foreach ($c in @(
            'int tcp set global dca=enabled',
            'int tcp set global netdma=enabled',
            'int tcp set global timestamps=disabled',
            'int tcp set global rss=enabled',
            'int tcp set global nonsackrttresiliency=disabled',
            'int tcp set global initialRto=2000',
            'int tcp set supplemental template=Internet icw=10',
            'int ip set global taskoffload=enabled',
            'interface isatap set state disabled'
        )) {
            try {
                $parts = $c.Split(' ')
                $null = & netsh.exe @parts 2>&1
                _Sy $c
            } catch { _Sy $c 'fail' }
        }
        try {
            Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object Status -eq 'Up' | ForEach-Object {
                try { $null = & netsh.exe interface ip set interface $_.Name currenthoplimit=64 2>&1; _Sy ("hop64 " + $_.Name) } catch {}
            }
        } catch {}
    }
    if ($Mode -in @('Setting','All')) {
        try {
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            # ConvertibleSlateMode only — Win32Priority locked by user
            $pc = 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl'
            if (-not (Test-Path $pc)) { New-Item -Path $pc -Force | Out-Null }
            New-ItemProperty -Path $pc -Name 'ConvertibleSlateMode' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $mq = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mq)) { New-Item -Path $mq -Force | Out-Null }
            New-ItemProperty -Path $mq -Name 'MouseDataQueueSize' -PropertyType DWord -Value 16 -Force -EA SilentlyContinue | Out-Null
            _Sy 'Extra Timer/Mouse'
        } catch {}
    }
}



function Apply-KaiPrimeExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # TOP pack — denser Kai stack. Rank1 still wins on conflicts.
    function _Kp([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }

    if ($Mode -in @('Network','All')) {
        try {
            foreach ($pair in @(
                @('UGFiveM','FiveM.exe'),
                @('UGFiveMGTA','FiveM_GTAProcess.exe'),
                @('UGGTA5','GTA5.exe')
            )) {
                $qos = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\$($pair[0])"
                if (-not (Test-Path $qos)) { New-Item -Path $qos -Force | Out-Null }
                New-ItemProperty -Path $qos -Name 'Version' -PropertyType String -Value '1.0' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'Application Name' -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                foreach ($v in @('Protocol','Local Port','Local IP','Local IP Prefix Length','Remote Port','Remote IP','Remote IP Prefix Length')) {
                    New-ItemProperty -Path $qos -Name $v -PropertyType String -Value '*' -Force -EA SilentlyContinue | Out-Null
                }
                New-ItemProperty -Path $qos -Name 'DSCP Value' -PropertyType String -Value '46' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'Throttle Rate' -PropertyType String -Value '-1' -Force -EA SilentlyContinue | Out-Null
                _Kp ("QoS_" + $pair[1])
            }
        } catch {}

        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency = 1; TCPNoDelay = 1; TcpDelAckTicks = 0
                TcpTimedWaitDelay = 15; DefaultTTL = 64; EnablePMTUDiscovery = 1
                EnableRSS = 1; EnableTCPA = 1; TcpMaxDataRetransmissions = 3
                SynAttackProtect = 0; EnableDeadGWDetect = 0; SackOpts = 1
                Tcp1323Opts = 1; MaxUserPort = 65534
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value ([int]$kv.Value) -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value ([int]$kv.Value) -Type DWord -Force -EA SilentlyContinue
                _Kp $kv.Key
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($kv in @{ TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0 }.GetEnumerator()) {
                        New-ItemProperty -Path $_.PSPath -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                    }
                }
                _Kp 'IF_NoNagle'
            }
        } catch {}

        try {
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold = 1500; FastCopyReceiveThreshold = 1500
                DefaultReceiveWindow = 262144; DefaultSendWindow = 262144
                EnableDynamicBacklog = 1; MinimumDynamicBacklog = 20; MaximumDynamicBacklog = 20000
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                _Kp $kv.Key
            }
        } catch {}

        try {
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            _Kp 'ThrottleOff'
        } catch {}

        foreach ($a in @(
            @('int','tcp','set','global','autotuninglevel=normal'),
            @('int','tcp','set','global','rss=enabled'),
            @('int','tcp','set','global','rsc=disabled'),
            @('int','tcp','set','global','timestamps=disabled'),
            @('int','tcp','set','global','ecncapability=disabled'),
            @('int','tcp','set','global','fastopen=enabled'),
            @('int','tcp','set','global','dca=enabled'),
            @('int','tcp','set','global','chimney=disabled'),
            @('int','tcp','set','global','initialRto=1000'),
            @('int','tcp','set','heuristics','disabled'),
            @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp')
        )) {
            try { $null = & netsh.exe @a 2>&1; _Kp ($a -join '_') } catch { _Kp ($a -join '_') 'fail' }
        }

        try {
            Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object Status -eq 'Up' | ForEach-Object {
                try { $null = & netsh.exe interface ip set interface $_.Name currenthoplimit=64 2>&1; _Kp ('hop64_' + $_.Name) } catch {}
                foreach ($prop in @{
                    '*FlowControl' = 0; '*InterruptModeration' = 0; '*PriorityVLANTag' = 0
                    '*ReceiveBuffers' = 2048; '*TransmitBuffers' = 2048
                    '*TCPChecksumOffloadIPv4' = 0; '*UDPChecksumOffloadIPv4' = 0
                    '*TCPChecksumOffloadIPv6' = 0; '*UDPChecksumOffloadIPv6' = 0
                    '*LsoV2IPv4' = 0; '*LsoV2IPv6' = 0; '*RSS' = 1
                    'PowerSavingMode' = 0; 'PowerDownPll' = 0; 'S5WakeOnLan' = 0; 'GigaLite' = 0
                }.GetEnumerator()) {
                    try {
                        Set-NetAdapterAdvancedProperty -Name $_.Name -DisplayName $prop.Key -DisplayValue $prop.Value -ErrorAction SilentlyContinue
                        Set-NetAdapterAdvancedProperty -Name $_.Name -RegistryKeyword $prop.Key -RegistryValue $prop.Value -ErrorAction SilentlyContinue
                    } catch {}
                }
                _Kp ('NIC_' + $_.Name)
            }
        } catch {}
    }

    if ($Mode -in @('Setting','All')) {
        try {
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -Value 1 -Type DWord -Force -EA SilentlyContinue
            _Kp 'TimerResolution'
        } catch {}

        try {
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl',
                'HKLM:\SYSTEM\ControlSet001\Control\PriorityControl'
            )) {
                if (-not (Test-Path $root)) { New-Item -Path $root -Force | Out-Null }
                New-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0x26 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $root -Name 'Win32PrioritySeparation' -Value 0x26 -Type DWord -Force -EA SilentlyContinue
                _Kp 'Win32Priority'
            }
        } catch {}

        try {
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force | Out-Null }
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            $games = "$mm\Tasks\Games"
            if (-not (Test-Path $games)) { New-Item -Path $games -Force | Out-Null }
            New-ItemProperty -Path $games -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $games -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            _Kp 'MMCSS_Games'
        } catch {}

        try {
            foreach ($svc in @('kbdclass','mouclass')) {
                $p = "HKLM:\SYSTEM\CurrentControlSet\Services\$svc\Parameters"
                if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
                $name = if ($svc -eq 'kbdclass') { 'KeyboardDataQueueSize' } else { 'MouseDataQueueSize' }
                New-ItemProperty -Path $p -Name $name -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $p -Name $name -Value 20 -Type DWord -Force -EA SilentlyContinue
                _Kp $name
            }
        } catch {}

        try {
            New-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _Kp 'PowerGraphics'
        } catch {}

        try {
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            _Kp 'BCD_Timer'
        } catch {}
    }
}


function Apply-BestPowerPlan {
    $ErrorActionPreference = 'SilentlyContinue'
    function _Pp([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) {
            if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' }
        } elseif ($st -eq 'ok' -and $null -ne $script:Ok) { $script:Ok++ }
    }
    try {
        $null = & powercfg.exe /hibernate off 2>&1
        _Pp 'hibernate_off'

        $high = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'
        $ult  = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
        $active = $null

        # Ensure Ultimate Performance exists
        $list = (& powercfg.exe /list 2>&1 | Out-String)
        if ($list -notmatch $ult) {
            try { $null = & powercfg.exe -duplicatescheme $high 2>&1 } catch {}
            try { $null = & powercfg.exe -duplicatescheme $ult 2>&1 } catch {}
            # Windows hidden ultimate unlock
            try { $null = & powercfg.exe -duplicatescheme $ult 2>&1 } catch {}
            $list = (& powercfg.exe /list 2>&1 | Out-String)
        }

        if ($list -match $ult) {
            $active = $ult
        } elseif ($list -match $high) {
            $active = $high
            try {
                $dup = (& powercfg.exe -duplicatescheme $high 2>&1 | Out-String)
                if ($dup -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') {
                    $active = $Matches[1]
                }
            } catch {}
        } else {
            $active = 'SCHEME_CURRENT'
        }

        $null = & powercfg.exe /setactive $active 2>&1
        _Pp 'PowerPlan_SetActive'

        # Full GUIDs for max compatibility
        $SUB_PROCESSOR = '54533251-82be-4824-96c1-47b60b740d00'
        $SUB_DISK      = '0012ee47-9041-4b5d-9b77-535fba8b1442'
        $SUB_SLEEP     = '238c9fa8-0aad-41ed-83f4-97be242c8f20'
        $SUB_USB       = '2a737441-1930-4402-8d77-b2bebba308a3'
        $SUB_PCI       = '501a4d13-42af-4429-9fd1-a821f2f397b'
        $SUB_PCIEX     = '501a4d13-42af-4429-9fd1-a821f2f397b9'
        $SUB_VIDEO     = '7516b95f-f776-4464-8c53-06167f40cc99'
        $SUB_WIFI      = '19cbb8fa-5279-450e-9fac-8a3d5fedd0c1'

        $PROCTHROTTLEMIN = '893dee8e-2bef-41e0-89c6-b55d0929964c'
        $PROCTHROTTLEMAX = 'bc5038f7-23e0-4960-96da-33abaf5935ec'
        $CPMINCORES      = '0cc5b647-c1df-4637-891a-dec35c318583'
        $CPMAXCORES      = 'ea062031-0e34-4ff1-9b6d-eb1059334029'
        $PERFBOOSTMODE   = 'be337238-0d82-4146-a960-4f3749d470c7'
        $SYSCOOLPOL      = '94d3a615-a899-4ac5-ae2b-e4d8f634367f'
        $DISKIDLE        = '6738e2c4-e8a5-4a42-b16a-e040e769756e'
        $STANDBYIDLE     = '29f6c1db-86da-48c5-9fdb-f2b67b1f44da'
        $HYBRIDSLEEP     = '94ac6d29-73ce-41a6-809f-6363ba21b47e'
        $HIBERNATEIDLE   = '9d7815a6-7ee4-497e-8888-515a05f02364'
        $USBSELECTIVE    = '48e6b7a6-50f5-4782-a5d4-53bb8f07e226'
        $ASPM            = 'ee12f906-d277-404b-b6da-e5fa1a576df5'
        $VIDEOIDLE       = '3c0bc021-c8a8-4e07-a973-6b14cbcb2b7e'

        $targets = @($active, 'SCHEME_CURRENT')
        foreach ($scheme in $targets) {
            foreach ($pair in @(
                @($SUB_PROCESSOR, $PROCTHROTTLEMIN, '100'),
                @($SUB_PROCESSOR, $PROCTHROTTLEMAX, '100'),
                @($SUB_PROCESSOR, $CPMINCORES, '100'),
                @($SUB_PROCESSOR, $CPMAXCORES, '100'),
                @($SUB_PROCESSOR, $PERFBOOSTMODE, '2'),
                @($SUB_PROCESSOR, $SYSCOOLPOL, '1'),
                @($SUB_DISK, $DISKIDLE, '0'),
                @($SUB_SLEEP, $STANDBYIDLE, '0'),
                @($SUB_SLEEP, $HYBRIDSLEEP, '0'),
                @($SUB_SLEEP, $HIBERNATEIDLE, '0'),
                @($SUB_USB, $USBSELECTIVE, '0'),
                @($SUB_PCIEX, $ASPM, '0'),
                @($SUB_VIDEO, $VIDEOIDLE, '0')
            )) {
                try { $null = & powercfg.exe /setacvalueindex $scheme $pair[0] $pair[1] $pair[2] 2>&1 } catch {}
                try { $null = & powercfg.exe /setdcvalueindex $scheme $pair[0] $pair[1] $pair[2] 2>&1 } catch {}
            }
            # alias form too
            foreach ($a in @(
                @('SUB_PROCESSOR','PROCTHROTTLEMIN','100'),
                @('SUB_PROCESSOR','PROCTHROTTLEMAX','100'),
                @('SUB_PROCESSOR','CPMINCORES','100'),
                @('SUB_PROCESSOR','CPMAXCORES','100'),
                @('SUB_DISK','DISKIDLE','0'),
                @('SUB_SLEEP','STANDBYIDLE','0'),
                @('SUB_USB','USBSELECTIVESUSPEND','0'),
                @('SUB_PCIEXPRESS','ASPM','0'),
                @('SUB_VIDEO','VIDEOIDLE','0')
            )) {
                try { $null = & powercfg.exe /setacvalueindex $scheme $a[0] $a[1] $a[2] 2>&1 } catch {}
                try { $null = & powercfg.exe /setdcvalueindex $scheme $a[0] $a[1] $a[2] 2>&1 } catch {}
            }
        }

        $null = & powercfg.exe /setactive $active 2>&1
        try { $null = & powercfg.exe /changename $active 'S' 'S' 2>&1 } catch {}
        try {
            $gid = (& powercfg.exe /getactivescheme 2>&1 | Out-String)
            if ($gid -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') {
                $null = & powercfg.exe /setactive $Matches[1] 2>&1
                $null = & powercfg.exe /changename $Matches[1] 'S' 'S' 2>&1
                _Pp 'PowerPlan_Active'
            }
        } catch {}
        _Pp 'BestPowerPlan'
    } catch {
        _Pp 'BestPowerPlan' 'fail'
    }
}


