        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters' -Name 'CacheHashTableBucketSize' -PropertyType DWord -Value (1) -Force -EA SilentlyContinue|Out-Null;_Ap 'CacheHashTableBucketSize'}catch{_Ap 'CacheHashTableBucketSize' 'fail'}
        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters' -Name 'MaximumCacheSize' -PropertyType DWord -Value (16384) -Force -EA SilentlyContinue|Out-Null;_Ap 'MaximumCacheSize'}catch{_Ap 'MaximumCacheSize' 'fail'}
        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Name 'ProcessorAffinityMask' -PropertyType DWord -Value (0) -Force -EA SilentlyContinue|Out-Null;_Ap 'ProcessorAffinityMask'}catch{_Ap 'ProcessorAffinityMask' 'fail'}
        try{if(-not(Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters')){New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Force -EA SilentlyContinue|Out-Null};New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndis\Parameters' -Name 'LogicalProcessorsPerPhysicalProcessor' -PropertyType DWord -Value (1) -Force -EA SilentlyContinue|Out-Null;_Ap 'LogicalProcessorsPerPhysicalProcessor'}catch{_Ap 'LogicalProcessorsPerPhysicalProcessor' 'fail'}
