            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            $kbd = 'HKCU:\Control Panel\Keyboard'
            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $kbd -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
            # BCD
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'InternetAspas_DENSE_Setting' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'InternetAspas_DENSE_Setting' 'fail' } }
    }
    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
            $tcpMap = @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; EnableWsd=0; EnableTCPA=0; EnableICMPRedirect=0
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpFinWait2Delay=30
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                TcpNumConnections=0x00fffffe; ForwardBufferMemory=16400
                NumForwardPackets=800; MaxFreeTcbs=16000; MaxHashTableSize=65536
            }
            foreach ($k in $tcpMap.Keys) {
                New-ItemProperty -Path $tp -Name $k -PropertyType DWord -Value $tcpMap[$k] -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $k -Value $tcpMap[$k] -Type DWord -Force -EA SilentlyContinue
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($pair in @(@{N='TcpAckFrequency';V=1},@{N='TCPNoDelay';V=1},@{N='TcpDelAckTicks';V=0},@{N='TcpInitialRTT';V=3})) {
                        New-ItemProperty -Path $_.PSPath -Name $pair.N -PropertyType DWord -Value $pair.V -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $pair.N -Value $pair.V -Type DWord -Force -EA SilentlyContinue
                    }
                }
            }
            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
                NonBlockingSendSpecialBuffering=1
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force | Out-Null }
            New-ItemProperty -Path $dns -Name 'MaxNegativeCacheTtl' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NegativeCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NetFailureCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'MaxCacheEntryTtlLimit' -PropertyType DWord -Value 86400 -Force -EA SilentlyContinue | Out-Null
            $ps = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $ps)) { New-Item -Path $ps -Force | Out-Null }
            New-ItemProperty -Path $ps -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force | Out-Null }
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','4'),
                        @('*ReceiveBuffers','512'),@('*TransmitBuffers','512'),
                        @('*TCPChecksumOffloadIPv4','0'),@('*UDPChecksumOffloadIPv4','0'),
                        @('*TCPChecksumOffloadIPv6','0'),@('*UDPChecksumOffloadIPv6','0'),
                        @('*LsoV1IPv4','0'),@('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),
                        @('*IPChecksumOffloadIPv4','0'),@('ITR','0'),@('*PriorityVLANTag','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                }
            }
            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','nonsackrttresiliency=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','global','pacingprofile=off'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'InternetAspas_DENSE_Net' } else { $script:Ok++ }
        } catch { if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'InternetAspas_DENSE_Net' 'fail' } }
    }

}


function Apply-AspasV2Extras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # MAIN1 Aspas V2 FULL MAX
    function _A2([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }
    if ($Mode -in @('Setting','All')) {
        try {
            $mq = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            $kq = 'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters'
            foreach ($cs in @('CurrentControlSet','ControlSet001')) {
                $mq2 = "HKLM:\SYSTEM\$cs\Services\mouclass\Parameters"
                $kq2 = "HKLM:\SYSTEM\$cs\Services\kbdclass\Parameters"
                if (-not (Test-Path $mq2)) { New-Item -Path $mq2 -Force | Out-Null }
                if (-not (Test-Path $kq2)) { New-Item -Path $kq2 -Force | Out-Null }
                New-ItemProperty -Path $mq2 -Name 'MouseDataQueueSize' -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $kq2 -Name 'KeyboardDataQueueSize' -PropertyType DWord -Value 20 -Force -EA SilentlyContinue | Out-Null
            }
            _A2 'Tier1 Queue20'
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSpeed' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold1' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold2' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseTrails' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseHoverTime' -Value '10' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardDelay' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardSpeed' -Value '31' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'MenuShowDelay' -Value '0' -Force -EA SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'ForegroundLockTimeout' -Value 0 -Type DWord -Force -EA SilentlyContinue
            _A2 'Tier1 InputMAX'
            foreach ($cs in @('CurrentControlSet','ControlSet001')) {
                $pc = "HKLM:\SYSTEM\$cs\Control\PriorityControl"
                if (-not (Test-Path $pc)) { New-Item -Path $pc -Force | Out-Null }
                New-ItemProperty -Path $pc -Name 'Win32PrioritySeparation' -PropertyType DWord -Value 0x26 -Force -EA SilentlyContinue | Out-Null
            }
            _A2 'Tier1 Win32_26'
            $sp = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $sp)) { New-Item -Path $sp -Force | Out-Null }
            New-ItemProperty -Path $sp -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value 0xFFFFFFFF -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'AlwaysOn' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'NoLazyMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'LazyModeTimeout' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            $g = Join-Path $sp 'Tasks\Games'
            if (-not (Test-Path $g)) { New-Item -Path $g -Force | Out-Null }
            New-ItemProperty -Path $g -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Affinity' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _A2 'Tier1 MMCSS_Games'
            foreach ($cs in @('CurrentControlSet','ControlSet001')) {
                $k = "HKLM:\SYSTEM\$cs\Control\Session Manager\kernel"
                if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
                New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $k -Name 'DisableDynamicTick' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                $gd = "HKLM:\SYSTEM\$cs\Control\GraphicsDrivers"
                if (-not (Test-Path $gd)) { New-Item -Path $gd -Force | Out-Null }
                New-ItemProperty -Path $gd -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            }
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformclock no 2>&1
            _A2 'Tier1 Timer_HAGS'
            foreach ($app in @('FiveM.exe','FiveM_GTAProcess.exe','FiveM_b3258_GTAProcess.exe','GTA5.exe')) {
                $ifeo = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$app\PerfOptions"
                if (-not (Test-Path $ifeo)) { New-Item -Path $ifeo -Force | Out-Null }
                New-ItemProperty -Path $ifeo -Name 'CpuPriorityClass' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $ifeo -Name 'IoPriority' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
            }
            _A2 'Tier1 FiveM_High'
            $gcs = 'HKCU:\System\GameConfigStore'
            if (-not (Test-Path $gcs)) { New-Item -Path $gcs -Force | Out-Null }
            New-ItemProperty -Path $gcs -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gcs -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            $gb = 'HKCU:\SOFTWARE\Microsoft\GameBar'
            if (-not (Test-Path $gb)) { New-Item -Path $gb -Force | Out-Null }
            New-ItemProperty -Path $gb -Name 'AutoGameModeEnabled' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gb -Name 'AllowAutoGameMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gb -Name 'ShowGameBar' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $gdv = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\GameDVR'
            if (-not (Test-Path $gdv)) { New-Item -Path $gdv -Force | Out-Null }
            New-ItemProperty -Path $gdv -Name 'AppCaptureEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $pol = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR'
            if (-not (Test-Path $pol)) { New-Item -Path $pol -Force | Out-Null }
            New-ItemProperty -Path $pol -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _A2 'Tier1 GameDVR_Off'
            # Alt+Tab small only - NO taskbar changes
            $ex = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer'
            if (-not (Test-Path $ex)) { New-Item -Path $ex -Force | Out-Null }
            $mm = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force | Out-Null }
            New-ItemProperty -Path $mm -Name 'LargeSystemCache' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mm -Name 'DisablePagingExecutive' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _A2 'Tier1 Memory'
        } catch { _A2 'Tier1 Setting' 'fail' }
    }
    if ($Mode -in @('Network','All')) {
        try {
            foreach ($cs in @('CurrentControlSet','ControlSet001')) {
                $tp = "HKLM:\SYSTEM\$cs\Services\Tcpip\Parameters"
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
                New-ItemProperty -Path $tp -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'TcpNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'TcpTimedWaitDelay' -PropertyType DWord -Value 15 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'DefaultTTL' -PropertyType DWord -Value 64 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'EnablePMTUDiscovery' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'SackOpts' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Tcp1323Opts' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'MaxUserPort' -PropertyType DWord -Value 65534 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'TcpMaxDataRetransmissions' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
                $tcpIf = "HKLM:\SYSTEM\$cs\Services\Tcpip\Parameters\Interfaces"
                if (Test-Path $tcpIf) {
                    Get-ChildItem $tcpIf -EA SilentlyContinue | ForEach-Object {
                        New-ItemProperty -Path $_.PSPath -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                        New-ItemProperty -Path $_.PSPath -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
                        New-ItemProperty -Path $_.PSPath -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
                    }
                }
                $afd = "HKLM:\SYSTEM\$cs\Services\AFD\Parameters"
                if (-not (Test-Path $afd)) { New-Item -Path $afd -Force | Out-Null }
                New-ItemProperty -Path $afd -Name 'FastSendDatagramThreshold' -PropertyType DWord -Value 0x5DC -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $afd -Name 'DefaultSendWindow' -PropertyType DWord -Value 0x40000 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $afd -Name 'DefaultReceiveWindow' -PropertyType DWord -Value 0x40000 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $afd -Name 'DynamicSendBufferDisable' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            }
            _A2 'Tier1 TCP_AFD_MAX'
            $ps = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $ps)) { New-Item -Path $ps -Force | Out-Null }
            New-ItemProperty -Path $ps -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            foreach ($pair in @(@('UGFiveM','FiveM.exe'),@('UGFiveMGTA','FiveM_GTAProcess.exe'),@('UGFiveMb3258','FiveM_b3258_GTAProcess.exe'))) {
                $qos = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\$($pair[0])"
                if (-not (Test-Path $qos)) { New-Item -Path $qos -Force | Out-Null }
                New-ItemProperty -Path $qos -Name 'Version' -PropertyType String -Value '1.0' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'Application Name' -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $qos -Name 'DSCP Value' -PropertyType String -Value '46' -Force -EA SilentlyContinue | Out-Null
                foreach ($v in @('Protocol','Local Port','Local IP','Local IP Prefix Length','Remote Port','Remote IP','Remote IP Prefix Length')) {
                    New-ItemProperty -Path $qos -Name $v -PropertyType String -Value '*' -Force -EA SilentlyContinue | Out-Null
                }
            }
            _A2 'Tier1 QoS_DSCP46'

        # Aspas V2 Network Engine Stack (NIC + netsh + timer)
        try {
            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -ErrorAction SilentlyContinue | Where-Object {
                    $_.PSChildName -match '^\d+$'
                } | ForEach-Object {
                    $nic = $_.PSPath
                    $props = @{
                        '*ReceiveBuffers' = '2048'
                        '*TransmitBuffers' = '2048'
                        '*DeviceSleepOnDisconnect' = '0'
                        '*EEE' = '0'
                        '*FlowControl' = '0'
                        '*IPChecksumOffloadIPv4' = '3'
                        '*InterruptModeration' = '0'
                        '*LsoV2IPv4' = '0'
                        '*LsoV2IPv6' = '0'
                        '*NumRssQueues' = '2'
                        '*PMARPOffload' = '1'
                        '*PMNSOffload' = '1'
                        '*PriorityVLANTag' = '1'
                        '*RSS' = '1'
                        '*WakeOnMagicPacket' = '0'
                        'AutoPowerSaveModeEnabled' = '0'
                        '*WakeOnPattern' = '0'
                        '*TCPChecksumOffloadIPv4' = '3'
                        '*TCPChecksumOffloadIPv6' = '3'
                        '*UDPChecksumOffloadIPv4' = '3'
                        '*UDPChecksumOffloadIPv6' = '3'
                        'DMACoalescing' = '0'
                        'EEELinkAdvertisement' = '0'
                        'EEE' = '0'
                        'SipsEnabled' = '0'
                        'S5WakeOnLan' = '0'
                        'EeePhyEnable' = '0'
                        'ITR' = '0'
                        'ReduceSpeedOnPowerDown' = '0'
                        'PowerDownPll' = '0'
                        'WaitAutoNegComplete' = '0'
                        'WakeOnLink' = '0'
                        'WakeOnSlot' = '0'
                        'WakeUpModeCap' = '0'
                        'AdvancedEEE' = '0'
                        'EnableGreenEthernet' = '0'
                        'GigaLite' = '0'
                        'PowerSavingMode' = '0'
                        'ULPMode' = '0'
                        '*SelectiveSuspend' = '0'
                        'EnableLLI' = '1'
                    }
                    foreach ($k in $props.Keys) {
                        try {
                            New-ItemProperty -LiteralPath $nic -Name $k -PropertyType String -Value $props[$k] -Force -ErrorAction SilentlyContinue | Out-Null
                        } catch {}
                    }
                    try {
                        New-ItemProperty -LiteralPath $nic -Name 'PnPCapabilities' -PropertyType DWord -Value 24 -Force -ErrorAction SilentlyContinue | Out-Null
                    } catch {}
                    foreach ($sk in @('Ultra Low Power Mode','System Idle Power Saver','Selective Suspend','Link Speed Battery Saver')) {
                        try {
                            New-ItemProperty -LiteralPath $nic -Name $sk -PropertyType String -Value 'Disabled' -Force -ErrorAction SilentlyContinue | Out-Null
                        } catch {}
                    }
                    try {
                        New-ItemProperty -LiteralPath $nic -Name 'Selective Suspend Idle Timeout' -PropertyType String -Value '60' -Force -ErrorAction SilentlyContinue | Out-Null
                    } catch {}
                }
            }
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'Tier1_NIC_Stack' } else { $script:Ok++ }
        } catch {
            if (Get-Command Log-Name -ErrorAction SilentlyContinue) { Log-Name 'Tier1_NIC_Stack' 'fail' }
        }
        foreach ($c in @(
            'int tcp set global dca=enabled',
            'int tcp set global netdma=enabled',
            'int tcp set heuristics disabled',
            'int tcp set global ecncapability=disabled',
            'int tcp set global timestamps=disabled',
            'int tcp set global rss=enabled',
            'int tcp set global nonsackrttresiliency=disabled',
            'int tcp set global initialRto=1000',
            'int tcp set global fastopen=enabled',
            'int tcp set global fastopenfallback=enabled',
            'int tcp set global autotuninglevel=restricted',
            'int tcp set global rsc=disabled',
            'int ip set global taskoffload=enabled',
            'int ip set global icmpredirects=disabled'
        )) {
            try {
                $null = & netsh.exe @($c.Split(' ')) 2>&1
