            New-ItemProperty -Path $dwm -Name 'AlwaysHibernateThumbnails' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            # Game DVR off
            $gcs = 'HKCU:\System\GameConfigStore'
