            New-ItemProperty -Path $mem -Name 'FeatureSettingsOverride' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mem -Name 'FeatureSettingsOverrideMask' -PropertyType DWord -Value 3 -Force -EA SilentlyContinue | Out-Null
            # Power
            $pwr = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power'
