            New-ItemProperty -Path $pwr -Name 'EnergyEstimationEnabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
