            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $kbd -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
            $desk = 'HKCU:\Control Panel\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $desk -Name 'MenuShowDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'AutoEndTasks' -PropertyType String -Value '1' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'HungAppTimeout' -PropertyType String -Value '1000' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'WaitToKillAppTimeout' -PropertyType String -Value '2000' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $desk -Name 'LowLevelHooksTimeout' -PropertyType String -Value '1000' -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'InputLatency' }

            $gcs = 'HKCU:\System\GameConfigStore'
            if (-not (Test-Path $gcs)) { New-Item -Path $gcs -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gcs -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gcs -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gcs -Name 'GameDVR_HonorUserFSEBehaviorMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gcs -Name 'GameDVR_DXGIHonorFSEWindowsCompatible' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $gdvr = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR'
            if (-not (Test-Path $gdvr)) { New-Item -Path $gdvr -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gdvr -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'GameDVR_Off' }

            $fs = 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem'
            if (-not (Test-Path $fs)) { New-Item -Path $fs -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $fs -Name 'NtfsDisableLastAccessUpdate' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $fs -Name 'NtfsDisable8dot3NameCreation' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null

            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'TimerBCD' }
        } catch {}
    }
    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; EnableWsd=0
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpFinWait2Delay=30
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                MaxFreeTcbs=16000; MaxHashTableSize=65536
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name $kv.Key }
            }
            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($pair in @(@{N='TcpAckFrequency';V=1},@{N='TCPNoDelay';V=1},@{N='TcpDelAckTicks';V=0})) {
                        New-ItemProperty -Path $_.PSPath -Name $pair.N -PropertyType DWord -Value $pair.V -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $pair.N -Value $pair.V -Type DWord -Force -EA SilentlyContinue
                    }
                }
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'TcpInterfaces' }

            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
                if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name $kv.Key }
            }

            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $dns -Name 'MaxNegativeCacheTtl' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NegativeCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NetFailureCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'DnsCache' }

            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'NonBestEffortLimit' }

            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Ndu_Start' }

            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','4'),
                        @('*ReceiveBuffers','512'),@('*TransmitBuffers','512'),
                        @('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                }
                if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'NIC' }
            }

            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'netsh_ctcp' }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'flushdns' }
        } catch {}
    }

    # MORE_DENSE_Assassin

    # === MORE DENSE MAX ===
    if ($Mode -in @('Setting','All')) {
        try {
            # Multimedia tasks full
            $mm = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $mm)) { New-Item -Path $mm -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mm -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'SystemResponsiveness' -Value 0 -Type DWord -Force -EA SilentlyContinue
            New-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value ([uint32]0xFFFFFFFF) -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mm -Name 'NetworkThrottlingIndex' -Value ([uint32]0xFFFFFFFF) -Type DWord -Force -EA SilentlyContinue
            foreach ($t in @('Games','Low Latency','Audio','Capture','Playback','Window Manager','DisplayPostProcessing','Distribution','Pro Audio')) {
                $tp = Join-Path $mm ("Tasks\" + $t)
                if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
                New-ItemProperty -Path $tp -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Clock Rate' -PropertyType DWord -Value 10000 -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Latency Sensitive' -PropertyType String -Value 'True' -Force -EA SilentlyContinue | Out-Null
                New-ItemProperty -Path $tp -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'MMTasks' }

            # Kernel / session
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'GlobalTimerResolutionRequests' }

            $mem = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'
            if (-not (Test-Path $mem)) { New-Item -Path $mem -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                DisablePagingExecutive=1; LargeSystemCache=0; IoPageLockLimit=983040
                FeatureSettings=1; FeatureSettingsOverride=3; FeatureSettingsOverrideMask=3
                ClearPageFileAtShutdown=0; SecondLevelDataCache=1024
            }.GetEnumerator()) {
                New-ItemProperty -Path $mem -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $mem -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'MemoryManagement' }

            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -Value 1 -Type DWord -Force -EA SilentlyContinue

            $gfx = 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers'
            if (-not (Test-Path $gfx)) { New-Item -Path $gfx -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gfx -Name 'HwSchMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gfx -Name 'TdrLevel' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gfx -Name 'TdrDelay' -PropertyType DWord -Value 60 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'Graphics' }

            $mou = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            if (-not (Test-Path $mou)) { New-Item -Path $mou -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -PropertyType DWord -Value 16 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $mou -Name 'MouseDataQueueSize' -Value 16 -Type DWord -Force -EA SilentlyContinue
            $mouse = 'HKCU:\Control Panel\Mouse'
            if (-not (Test-Path $mouse)) { New-Item -Path $mouse -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $mouse -Name 'MouseSpeed' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold1' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $mouse -Name 'MouseThreshold2' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            $kbd = 'HKCU:\Control Panel\Keyboard'
            if (-not (Test-Path $kbd)) { New-Item -Path $kbd -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $kbd -Name 'KeyboardDelay' -PropertyType String -Value '0' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $kbd -Name 'KeyboardSpeed' -PropertyType String -Value '31' -Force -EA SilentlyContinue | Out-Null
            $desk = 'HKCU:\Control Panel\Desktop'
            if (-not (Test-Path $desk)) { New-Item -Path $desk -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                MenuShowDelay='0'; AutoEndTasks='1'; HungAppTimeout='1000'
                WaitToKillAppTimeout='2000'; LowLevelHooksTimeout='1000'; WaitToKillServiceTimeout='2000'
            }.GetEnumerator()) {
                New-ItemProperty -Path $desk -Name $kv.Key -PropertyType String -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
            }
            New-ItemProperty -Path $desk -Name 'ForegroundLockTimeout' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'DesktopLatency' }

            $gcs = 'HKCU:\System\GameConfigStore'
            if (-not (Test-Path $gcs)) { New-Item -Path $gcs -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gcs -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $gcs -Name 'GameDVR_FSEBehaviorMode' -PropertyType DWord -Value 2 -Force -EA SilentlyContinue | Out-Null
            $gdvr = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR'
            if (-not (Test-Path $gdvr)) { New-Item -Path $gdvr -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $gdvr -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null

            $fs = 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem'
            if (-not (Test-Path $fs)) { New-Item -Path $fs -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $fs -Name 'NtfsDisableLastAccessUpdate' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $fs -Name 'NtfsDisable8dot3NameCreation' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null

            $ex = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
            if (-not (Test-Path $ex)) { New-Item -Path $ex -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ex -Name 'TaskbarAnimations' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $ex -Name 'ListviewAlphaSelect' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $ex -Name 'ListviewShadow' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null

            $null = & bcdedit.exe /set disabledynamictick yes 2>&1
            $null = & bcdedit.exe /set useplatformtick yes 2>&1
            $null = & bcdedit.exe /set tscsyncpolicy Enhanced 2>&1
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'BCDTimer' }
        } catch {}
    }
    if ($Mode -in @('Network','All')) {
        try {
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                TcpAckFrequency=1; TCPNoDelay=1; TcpDelAckTicks=0; TcpTimedWaitDelay=15
                DefaultTTL=64; EnablePMTUDiscovery=1; EnablePMTUBHDetect=0; SackOpts=1
                TcpMaxDataRetransmissions=3; TcpMaxDupAcks=2; Tcp1323Opts=1
                EnableRSS=1; EnableDCA=1; EnableWsd=0
                MaxUserPort=65534; TcpWindowSize=65535; GlobalMaxTcpWindowSize=65535
                KeepAliveTime=300000; KeepAliveInterval=1000; TcpFinWait2Delay=30
                SynAttackProtect=0; EnableDeadGWDetect=0; TcpMaxConnectRetransmissions=2
                MaxFreeTcbs=16000; MaxHashTableSize=65536
            }.GetEnumerator()) {
                New-ItemProperty -Path $tp -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $tp -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'TcpipParameters' }

            foreach ($root in @(
                'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces',
                'HKLM:\SYSTEM\ControlSet001\Services\Tcpip\Parameters\Interfaces'
            )) {
                if (-not (Test-Path $root)) { continue }
                Get-ChildItem $root -EA SilentlyContinue | ForEach-Object {
                    foreach ($pair in @(@{N='TcpAckFrequency';V=1},@{N='TCPNoDelay';V=1},@{N='TcpDelAckTicks';V=0})) {
                        New-ItemProperty -Path $_.PSPath -Name $pair.N -PropertyType DWord -Value $pair.V -Force -EA SilentlyContinue | Out-Null
                        Set-ItemProperty -Path $_.PSPath -Name $pair.N -Value $pair.V -Type DWord -Force -EA SilentlyContinue
                    }
                }
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'TcpInterfaces' }

            $afd = 'HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters'
            if (-not (Test-Path $afd)) { New-Item -Path $afd -Force -EA SilentlyContinue | Out-Null }
            foreach ($kv in @{
                FastSendDatagramThreshold=1500; FastCopyReceiveThreshold=1500
                DefaultReceiveWindow=65535; DefaultSendWindow=65535
                DisableAddressSharing=1; EnableDynamicBacklog=1
                MinimumDynamicBacklog=20; MaximumDynamicBacklog=20000; DynamicBacklogGrowthDelta=10
            }.GetEnumerator()) {
                New-ItemProperty -Path $afd -Name $kv.Key -PropertyType DWord -Value $kv.Value -Force -EA SilentlyContinue | Out-Null
                Set-ItemProperty -Path $afd -Name $kv.Key -Value $kv.Value -Type DWord -Force -EA SilentlyContinue
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'AFD' }

            $dns = 'HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters'
            if (-not (Test-Path $dns)) { New-Item -Path $dns -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $dns -Name 'MaxNegativeCacheTtl' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NegativeCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $dns -Name 'NetFailureCacheTime' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null

            $psched = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched'
            if (-not (Test-Path $psched)) { New-Item -Path $psched -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $psched -Name 'NonBestEffortLimit' -Value 0 -Type DWord -Force -EA SilentlyContinue

            $ndu = 'HKLM:\SYSTEM\CurrentControlSet\Services\Ndu'
            if (-not (Test-Path $ndu)) { New-Item -Path $ndu -Force -EA SilentlyContinue | Out-Null }
            New-ItemProperty -Path $ndu -Name 'Start' -PropertyType DWord -Value 4 -Force -EA SilentlyContinue | Out-Null
            Set-ItemProperty -Path $ndu -Name 'Start' -Value 4 -Type DWord -Force -EA SilentlyContinue

            $nicRoot = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
            if (Test-Path $nicRoot) {
                Get-ChildItem $nicRoot -EA SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                    $p = $_.PSPath
                    foreach ($pair in @(
                        @('*InterruptModeration','0'),@('*FlowControl','0'),@('*EEE','0'),
                        @('*EnergyEfficientEthernet','0'),@('*RSS','1'),@('*NumRssQueues','4'),
                        @('*ReceiveBuffers','512'),@('*TransmitBuffers','512'),
                        @('*LsoV1IPv4','0'),@('*LsoV2IPv4','0'),@('*LsoV2IPv6','0'),@('ITR','0')
                    )) {
                        New-ItemProperty -Path $p -Name $pair[0] -PropertyType String -Value $pair[1] -Force -EA SilentlyContinue | Out-Null
                    }
                }
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'NIC' }

            foreach ($a in @(
                @('int','tcp','set','heuristics','disabled'),
                @('int','tcp','set','global','autotuninglevel=normal'),
                @('int','tcp','set','global','rss=enabled'),
                @('int','tcp','set','global','rsc=disabled'),
                @('int','tcp','set','global','timestamps=disabled'),
                @('int','tcp','set','global','ecncapability=disabled'),
                @('int','tcp','set','global','fastopen=enabled'),
                @('int','tcp','set','global','dca=enabled'),
                @('int','tcp','set','global','chimney=disabled'),
                @('int','tcp','set','global','netdma=disabled'),
                @('int','tcp','set','global','initialRto=1000'),
                @('int','tcp','set','global','maxsynretransmissions=2'),
                @('int','tcp','set','supplemental','template=internet','congestionprovider=ctcp'),
                @('int','ipv4','set','global','defaultcurhoplimit=64'),
                @('int','ipv4','set','dynamicport','tcp','start=10000','num=55536'),
                @('int','ipv4','set','dynamicport','udp','start=10000','num=55536')
            )) {
                try { $null = & "$env:SystemRoot\System32\netsh.exe" @a 2>&1 } catch {}
            }
            if (Get-Command Log-Name -EA SilentlyContinue) { Log-Name 'netsh' }
            try { $null = & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 } catch {}
        } catch {}
    }

}


function Apply-MaxAggression {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # Extra MAX layer (fill-gap only; never overrides core 1-2 intentional keys)
    function _Mx([string]$n,[string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }
    if ($Mode -in @('Setting','All')) {
        try {
            # Multimedia / games priority path
            $sp = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'
            if (-not (Test-Path $sp)) { New-Item -Path $sp -Force | Out-Null }
            New-ItemProperty -Path $sp -Name 'NetworkThrottlingIndex' -PropertyType DWord -Value 0xffffffff -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'SystemResponsiveness' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'NoLazyMode' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $sp -Name 'AlwaysOn' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $g = Join-Path $sp 'Tasks\Games'
            if (-not (Test-Path $g)) { New-Item -Path $g -Force | Out-Null }
            New-ItemProperty -Path $g -Name 'GPU Priority' -PropertyType DWord -Value 8 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Priority' -PropertyType DWord -Value 6 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Scheduling Category' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'SFIO Priority' -PropertyType String -Value 'High' -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $g -Name 'Background Only' -PropertyType String -Value 'False' -Force -EA SilentlyContinue | Out-Null
            _Mx 'MMCSS Games MAX'
        } catch { _Mx 'MMCSS Games MAX' 'fail' }
        try {
            # Input queues low latency
            $mq = 'HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters'
            $kq = 'HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters'
            if (-not (Test-Path $mq)) { New-Item -Path $mq -Force | Out-Null }
            if (-not (Test-Path $kq)) { New-Item -Path $kq -Force | Out-Null }
            New-ItemProperty -Path $mq -Name 'MouseDataQueueSize' -PropertyType DWord -Value 0x14 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $kq -Name 'KeyboardDataQueueSize' -PropertyType DWord -Value 0x14 -Force -EA SilentlyContinue | Out-Null
            _Mx 'InputQueues20'
        } catch { _Mx 'InputQueues20' 'fail' }
        try {
            # TCP low delay (if core already set same, harmless)
            $tp = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters'
            if (-not (Test-Path $tp)) { New-Item -Path $tp -Force | Out-Null }
            New-ItemProperty -Path $tp -Name 'TcpAckFrequency' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TCPNoDelay' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            New-ItemProperty -Path $tp -Name 'TcpDelAckTicks' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _Mx 'TCP LowDelay'
        } catch { _Mx 'TCP LowDelay' 'fail' }
        try {
            # Desktop / power latency
            Set-ItemProperty -Path 'HKCU:\Control Panel\Desktop' -Name 'MenuShowDelay' -Value '0' -Force -EA SilentlyContinue
            New-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            $pt = 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling'
            if (-not (Test-Path $pt)) { New-Item -Path $pt -Force | Out-Null }
            New-ItemProperty -Path $pt -Name 'PowerThrottlingOff' -PropertyType DWord -Value 1 -Force -EA SilentlyContinue | Out-Null
            _Mx 'PowerLatencyOff'
        } catch { _Mx 'PowerLatencyOff' 'fail' }
        try {
            # GameDVR off
            New-ItemProperty -Path 'HKCU:\System\GameConfigStore' -Name 'GameDVR_Enabled' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            $gd = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR'
            if (-not (Test-Path $gd)) { New-Item -Path $gd -Force | Out-Null }
            New-ItemProperty -Path $gd -Name 'AllowGameDVR' -PropertyType DWord -Value 0 -Force -EA SilentlyContinue | Out-Null
            _Mx 'GameDVR Off'
        } catch {}
    }
    if ($Mode -in @('Network','All')) {
        foreach ($c in @(
            'int tcp set global autotuninglevel=normal',
            'int tcp set global ecncapability=disabled',
            'int tcp set global timestamps=disabled',
            'int tcp set global rss=enabled',
            'int tcp set global rsc=disabled',
            'int tcp set global fastopen=enabled',
            'int tcp set global hystart=disabled',
            'int tcp set global initialRto=2000',
            'int tcp set global maxsynretransmissions=2',
            'int tcp set supplemental template=Internet congestionprovider=ctcp',
            'int ip set global taskoffload=enabled',
            'int tcp set global dca=enabled'
        )) {
            try {
                $parts = $c.Split(' ')
                $null = & netsh.exe @parts 2>&1
                _Mx $c
            } catch { _Mx $c 'fail' }
        }
        try {
            Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object Status -eq 'Up' | ForEach-Object {
                try { Enable-NetAdapterRss -Name $_.Name -ErrorAction SilentlyContinue | Out-Null; _Mx ("RSS " + $_.Name) } catch {}
            }
        } catch {}
    }
}


function Apply-Setting7zExtras {
    param([ValidateSet('Setting','Network','All')][string]$Mode = 'All')
    # Rank 3+ fill. Runs inside MERGED ALL SOURCES.
    function _S7Log([string]$n, [string]$st='ok') {
        if (Get-Command Log-Name -ErrorAction SilentlyContinue) { if ($st -eq 'ok') { Log-Name $n } else { Log-Name $n 'fail' } }
        elseif ($st -eq 'ok') { $script:Ok++ }
    }
    if ($Mode -in @('Setting','All')) {
        try {
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel'
            if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
            New-ItemProperty -Path $k -Name 'GlobalTimerResolutionRequests' -PropertyType DWord -Value 1 -Force -ErrorAction SilentlyContinue | Out-Null
            _S7Log 'GlobalTimerResolutionRequests'
        } catch { _S7Log 'GlobalTimerResolutionRequests' 'fail' }
        try {
            $qos = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\FiveM.exe'
            if (-not (Test-Path $qos)) { New-Item -Path $qos -Force | Out-Null }
            foreach ($pair in @(
                @('Version','1.0'), @('Application Name','FiveM.exe'), @('Protocol','*'),
                @('Local Port','*'), @('Remote Port','*'), @('DSCP Value','46'),
                @('Throttle Rate','-1'), @('Tcp Autotuning Level','Normal'),
                @('Application DSCP Marking Request','Ignored')
            )) {
                New-ItemProperty -Path $qos -Name $pair[0] -PropertyType String -Value $pair[1] -Force -ErrorAction SilentlyContinue | Out-Null
            }
            _S7Log 'QoS FiveM.exe'
        } catch { _S7Log 'QoS FiveM.exe' 'fail' }
        try {
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSensitivity' -Value '10' -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSpeed' -Value '0' -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold1' -Value '0' -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseThreshold2' -Value '0' -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardDelay' -Value '0' -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path 'HKCU:\Control Panel\Keyboard' -Name 'KeyboardSpeed' -Value '31' -Force -ErrorAction SilentlyContinue
            _S7Log 'MouseKeyboard'
        } catch { _S7Log 'MouseKeyboard' 'fail' }
    }
    if ($Mode -in @('Network','All')) {
        foreach ($c in @(
            'int tcp set global dca=enabled',
            'int tcp set global rss=enabled',
            'int tcp set global timestamps=disabled',
            'int tcp set global nonsackrttresiliency=disabled',
            'int tcp set global initialRto=2000',
            'int tcp set supplemental template=Internet icw=10',
            'int ip set global taskoffload=enabled',
            'int tcp set global autotuninglevel=normal'
        )) {
            try {
                $parts = $c.Split(' ')
                $null = & netsh.exe @parts 2>&1
                _S7Log $c
            } catch { _S7Log $c 'fail' }
        }
        try {
            Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
                try {
                    $null = & netsh.exe interface ip set interface $_.Name currenthoplimit=64 2>&1
                    _S7Log ("hop64 " + $_.Name)
                } catch { _S7Log ("hop64 " + $_.Name) 'fail' }
            }
        } catch {}
    }
}




function Invoke-StandardTweaks {
    Write-LogTime "Running AUTO CITIZENFX.INI..." "#FFFFFF"

    $targets = @(
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app\CitizenFX.ini"),
        (Join-Path $env:LOCALAPPDATA "FiveM Application Data\CitizenFX.ini"),
        (Join-Path $env:APPDATA "CitizenFX\CitizenFX.ini")
    )
    $targetPath = $null
    foreach ($c in $targets) {
        if (Test-Path -LiteralPath $c) { $targetPath = $c; break }
    }
    if (-not $targetPath) { $targetPath = $targets[0] }

    # [Game] keep path/pool + extras
    # [Addon]  = normal latency pack
    # [Addons] = ReShade only (preserve existing)
    # [Input] [Renderer] [Streaming] [Citizen]

    $gameExtras = @(
        'DisableLauncher=true',
        'EnableFastLoad=true',
        'ProcessPriority=high',
        'DisableInGameOverlays=true',
        'EnablePreload=1',
        'DisableWelcomeScreen=true',
        'profile_advGfxMaxLod=-5',
        'profile_lowQualitySky=1',
        'profile_lowQualityWater=1',
        'profile_lowQualityVegetation=1',
        'profile_lowQualityRoads=1',
        'profile_lowQualityBuildings=1',
        'profile_lowQualityLights=1',
        'profile_lowQualityProps=1',
        'profile_lowQualityVehicles=1',
        'profile_disablePedLod=1',
        'profile_disableLightShadows=1',
        'profile_829D291MMJ=11',
        'profile_disableWaterReflections=1',
        'profile_disableVegetationShadows=1',
        'profile_disableDecals=1',
        'profile_disableDistantLights=1',
        'profile_reduceDrawDistance=1',
        'profile_reduceShadowQuality=1',
        'profile_reduceReflectionQuality=1',
        'profile_reduceParticleQuality=1',
        'profile_reducePostFX=1',
        'profile_disableAllShadows=1',
        'profile_disableAllReflections=1',
        'profile_disableAllPostFX=1',
        'profile_minimalGraphics=1',
        'UncappedFPS=true',
        'DisableStreamingSubsystem=false'
    )

    $addonBody = @(
        'cl_forceStreamingLegacy=false',
        'enable_cloth=0',
        'disable_ambient_occlusion=1',
        'disable_fog=1',
        'NV_disableShaderDiskCache=false',
        'UseHighPriorityThreads=1',
        'UseAudioThread=1',
        'ClearInvalidPoolCache=1',
        'IgnoreDifferentVideoCard=1',
        'DisableResourceTimeouts=1',
        'DisableNagleAlgorithm=1',
        'HighPriority=1',
        'UseDirectInput=1',
        'DisableNvThreadedOptimization=1',
        'net_maxMtu=1200',
        'vid_budgetScale=0',
        'ui_maxQueriesPerMinute=6',
        'disable_vsync=1',
        'maxStreamingRequests=200',
        'cl_forceStreamingPrefetch=0',
        'net_thread_priority=1',
        'cl_interp=0',
        'cl_interp_ratio=1'
    )

    $inputSection = @(
        'UseRawInput=1',
        'DisableMouseSmoothing=1',
        'DisableControllerDeadzone=1',
        'RawInputBufferSize=1024',
        'RawInputBufferFlush=1',
        'EnableLowLatencyInput=1',
        'DisableKeyboardDebounce=1',
        'UseDirectInput=1'
    )

    $rendererSection = @(
        'DisableVSync=1',
        'EnableFramePacing=0',
        'EnableTripleBuffering=0',
        'DisableLatencyLimiter=1',
        'WaitForVBlank=0',
        'ReduceInputLatency=1',
        'ImmediatePresent=1',
        'DisableOcclusionQueries=1',
        'DisableShadowOptimizations=true',
        'EnablePresentationOptimizations=true',
        'ForceRenderAheadLimit=0',
        'SwapChainUseWaitableSwapChain=true',
        'DisableHyperthreading=1',
        'DisableNvLowLatency=false',
        'MaxLatency=1'
    )

    $streamingSection = @(
        'MaxStreamingRequests=120',
        'MaxStreamingMemory=4096',
        'StreamerMode=0',
        'NetworkStreamingThreshold=0'
    )

    $citizenSection = @(
        'DisableNVN=true',
        'DisableNVNGPU=true',
        'DisableVSync=1',
        'DisableAudioInputSupport=true'
    )

    $managedGameKeys = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($ln in $gameExtras) {
        $k = ($ln -split '=', 2)[0].Trim()
        [void]$managedGameKeys.Add($k)
    }

    try {
        $parent = Split-Path -Parent $targetPath
        if ($parent -and -not (Test-Path -LiteralPath $parent)) {
            New-Item -ItemType Directory -Path $parent -Force | Out-Null
        }

        $keepGame = New-Object 'System.Collections.Generic.List[string]'
        $keepAddons = New-Object 'System.Collections.Generic.List[string]'
        $existingText = ''
        if (Test-Path -LiteralPath $targetPath) {
            try {
                Copy-Item -LiteralPath $targetPath -Destination ($targetPath + '.bak') -Force -ErrorAction SilentlyContinue
            } catch {}
            try { $existingText = [System.IO.File]::ReadAllText($targetPath) } catch { $existingText = '' }
        }
        if ($existingText) {
            $cur = ''
            foreach ($ln in [regex]::Split($existingText, "\r?\n")) {
                $tr = if ($null -ne $ln) { $ln.Trim() } else { '' }
                $hm = [regex]::Match($tr, '^\[([^\]]+)\]\s*$')
                if ($hm.Success) {
                    $cur = $hm.Groups[1].Value.Trim().ToLowerInvariant()
                    continue
                }
                if ($cur -eq 'game') {
                    if ([string]::IsNullOrWhiteSpace($tr) -or $tr.StartsWith(';') -or $tr.StartsWith('#')) {
                        $keepGame.Add($ln)
                        continue
                    }
                    $key = ($tr -split '=', 2)[0].Trim()
                    if ($managedGameKeys.Contains($key)) { continue }
                    if ($tr -match '(?i)^reshade') { continue }
                    $keepGame.Add($ln)
                }
                elseif ($cur -eq 'addons') {
                    # preserve all existing [Addons] lines that look like ReShade
                    if ([string]::IsNullOrWhiteSpace($tr)) { continue }
                    if ($tr -match '(?i)reshade') {
                        $keepAddons.Add($tr)
                    }
                }
            }
        }

        $out = New-Object 'System.Collections.Generic.List[string]'
        $out.Add('[Game]')
        foreach ($ln in $keepGame) { $out.Add($ln) }
        foreach ($ln in $gameExtras) { $out.Add($ln) }

        $out.Add('')
        $out.Add('[Addon]')
        foreach ($ln in $addonBody) { $out.Add($ln) }

        $out.Add('')
        $out.Add('[Addons]')
        if ($keepAddons.Count -gt 0) {
            # already has ReShade lines — leave as-is
            foreach ($ln in $keepAddons) { $out.Add($ln) }
        } else {
            # no ReShade line found — add default acknowledgment line
            $out.Add('ReShade5=ID:420eb310 acknowledged that ReShade 5.x has a bug that will lead to game crashes')
        }

        $out.Add('')
        $out.Add('[Input]')
        foreach ($ln in $inputSection) { $out.Add($ln) }

        $out.Add('')
        $out.Add('[Renderer]')
        foreach ($ln in $rendererSection) { $out.Add($ln) }

        $out.Add('')
        $out.Add('[Streaming]')
        foreach ($ln in $streamingSection) { $out.Add($ln) }

        $out.Add('')
        $out.Add('[Citizen]')
        foreach ($ln in $citizenSection) { $out.Add($ln) }

        $utf8 = New-Object System.Text.UTF8Encoding $false
        [System.IO.File]::WriteAllText($targetPath, ($out -join "`r`n") + "`r`n", $utf8)
        Write-LogTime ("CitizenFX.ini written: {0}" -f $targetPath) "#00EBA0"

        try {
            Start-Process notepad.exe -ArgumentList "`"$targetPath`"" -ErrorAction SilentlyContinue
        } catch {}
    } catch {
        Write-LogTime ("CitizenFX replace failed: {0}" -f $_.Exception.Message) "#F2F2F2"
    }

    Write-LogTime "AUTO CITIZENFX.INI done." "#14eb00"
}


function Invoke-AdvancedTweaks {
    Write-LogTime "Running MOUSE AND KEYBOARD only..." "#FFFFFF"
    $failed = New-Object System.Collections.Generic.List[string]

    $mousePath = "HKCU:\Control Panel\Mouse"
    $mouseSettings = @(
        @{ Name = "MouseSensitivity";    Value = "10"  },
        @{ Name = "MouseSpeed";          Value = "0"   },
        @{ Name = "MouseThreshold1";     Value = "0"   },
        @{ Name = "MouseThreshold2";     Value = "0"   },
        @{ Name = "DoubleClickSpeed";    Value = "500" },
        @{ Name = "DoubleClickHeight";   Value = "4"   },
        @{ Name = "DoubleClickWidth";    Value = "4"   },
        @{ Name = "MouseHoverTime";      Value = "0"   },
        @{ Name = "MouseHoverHeight";    Value = "4"   },
        @{ Name = "MouseHoverWidth";     Value = "4"   },
        @{ Name = "MouseTrails";         Value = "0"   },
        @{ Name = "SnapToDefaultButton"; Value = "0"   }
    )
    foreach ($i in 3..9) { $mouseSettings += @{ Name = "MouseThreshold$i"; Value = "0" } }

    foreach ($s in $mouseSettings) {
        if (-not (Set-RegTweak $mousePath $s.Name $s.Value "String")) { $failed.Add("$mousePath\$($s.Name)") }
    }
    Write-LogTime "» Mouse settings applied (raw input / no acceleration)" "#E0E0E0"

    $kbdPath = "HKCU:\Control Panel\Keyboard"
    if (-not (Set-RegTweak $kbdPath "KeyboardDelay" "0"  "String")) { $failed.Add("$kbdPath\KeyboardDelay") }
    if (-not (Set-RegTweak $kbdPath "KeyboardSpeed" "31" "String")) { $failed.Add("$kbdPath\KeyboardSpeed") }
    Write-LogTime "» Keyboard repeat delay/speed applied" "#E0E0E0"

    if (-not (Set-RegTweak $respPath "Flags"           "0"  "String")) { $failed.Add("$respPath\Flags") }
    Write-LogTime "» Keyboard response settings applied" "#E0E0E0"

    if (-not (Set-RegTweak "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "SystemResponsiveness" 0)) {
        $failed.Add("HKLM:...\SystemProfile\SystemResponsiveness")
    }
    if (-not (Set-RegTweak "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" "Win32PrioritySeparation" 0x26)) {
        $failed.Add("HKLM:...\PriorityControl\Win32PrioritySeparation")
    }
    if (-not (Set-RegTweak "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "NetworkThrottlingIndex" 0xffffffff)) {
        $failed.Add("HKLM:...\SystemProfile\NetworkThrottlingIndex")
    }
    Write-LogTime "» System responsiveness / priority separation / network throttling applied" "#E0E0E0"

    if ($failed.Count -gt 0) {
        $msg = "Failed to apply $($failed.Count) setting(s):`n" + ($failed -join "`n")
        Write-LogTime "» ERROR: $($failed.Count) setting(s) failed to apply (try running as Administrator)" "#F2F2F2"
        [System.Windows.MessageBox]::Show($msg, "Project UndergroundPrime - Error") | Out-Null
    } else {
        Write-LogTime "MOUSE AND KEYBOARD tweaks complete." "#14eb00"
    }
}

function Invoke-SystemIniTweak {
    Write-LogTime "Running SYSTEM.INI..." "#fbff00"

    $iniFolder = "C:\Windows"
    $iniPath   = Join-Path $iniFolder "system.ini"

    $iniContent = @'
[boot]
[boot]
DMABufferSize=64
[386Enh]
MinTimeSlice=1
woafont=dosapp.fon
EGA80WOA.FON=EGA80WOA.FON
EGA40WOA.FON=EGA40WOA.FON
CGA80WOA.FON=CGA80WOA.FON
CGA40WOA.FON=CGA40WOA.FON
32BitDiskAccess=on
32BitFileAccess=on
VirtualHDIRQ=off
LocalLoadHigh=1
PerVMFiles=255
EMMSize=0
MaxBPs=768
PageBuffers=32
ConservativeSwapfileUsage=1
[vcache]
MinFileCache=8192
MaxFileCache=262144
ChunkSize=2048
NameCache=4096
DirectoryCache=128
[drivers]
Timer=timer.drv
[mci]
WaveAudio=mciwave.drv
Sequencer=mciseq.drv
'@

    try {
        if (-not (Test-Path $iniFolder)) {
            New-Item -Path $iniFolder -ItemType Directory -Force | Out-Null
            Write-LogTime "» Created folder: $iniFolder" "#E0E0E0"
        }

        $targetLines = $iniContent -split "`r`n|`n"

        if (Test-Path $iniPath) {
            $existingLines = Read-IniLinesSafe -Path $iniPath
            $merged = Merge-IniAppendOnly -ExistingLines $existingLines -TargetLines $targetLines

            if ($merged.Changed) {
                # backup disabled
                Write-IniLinesSafe -Path $iniPath -Lines $merged.Lines
                if ($merged.Added -gt 0) {
                    Write-LogTime "» system.ini updated: added $($merged.Added) missing setting(s), nothing removed (backup saved as system.ini.bak)" "#E0E0E0"
                } else {
                    Write-LogTime "» system.ini cleaned up: grouped/repositioned existing settings, no values changed (backup saved as system.ini.bak)" "#E0E0E0"
                }
            } else {
                Write-LogTime "» system.ini already contains all these settings, no changes made" "#E0E0E0"
            }
        } else {
            Write-IniLinesSafe -Path $iniPath -Lines $targetLines
            Write-LogTime "» system.ini created at: $iniPath" "#E0E0E0"
        }

        Write-LogTime "SYSTEM.INI complete." "#14eb00"
    } catch {
        Write-LogTime "» ERROR: Failed to update system.ini - $($_.Exception.Message)" "#F2F2F2"
        [System.Windows.MessageBox]::Show(
            "Failed to write system.ini:`n$($_.Exception.Message)`n`nPath: $iniPath`n`nTip: this file is in C:\Windows, make sure the app is running as Administrator.",
            "Project UndergroundPrime - Error"
        ) | Out-Null
    }
}

function Invoke-ResetTweaks {
    Write-LogTime "Running RESET (undo AUTO CITIZENFX.INI + MOUSE AND KEYBOARD)..." "#eeff00"
    $failed = New-Object System.Collections.Generic.List[string]

    # --- 1) CitizenFX.ini -------------------------------------------------
    # Prefer restoring the exact .bak snapshot taken right before the last
    # write (created by Invoke-StandardTweaks). If there is no backup
    # (e.g. the file was freshly created by the tool, so there was nothing
    # to back up), fall back to surgically removing only the keys this
    # tool manages - anything the user set by hand (like IVPath) is left
    # completely untouched either way.
    $iniFolder = "C:\Users\Administrator\AppData\Local\FiveM\FiveM.app"
    $iniPath   = Join-Path $iniFolder "CitizenFX.ini"
    $bakPath   = "$iniPath.bak"

    try {
        if (Test-Path $bakPath) {
            Copy-Item -Path $bakPath -Destination $iniPath -Force
            Write-LogTime "» CitizenFX.ini restored from backup (CitizenFX.ini.bak)" "#E0E0E0"
        } elseif (Test-Path $iniPath) {
            $managedKeysBySection = @{
                "[Game]"      = @("disablecrashreporting","enablegameloadingonstartup","disableloadingscreen")
                "[Graphics]"  = @("videomemorybudget","extratexturememory","extratexturememoryallowed","usehighprecisionshaders")
                "[Streaming]" = @("enabledistancestreaming","memoryusagelimit")
                "[Addon]"     = @("net_maxmtu","vid_budgetscale","ui_maxqueriesperminute","disable_vsync","disable_fog","disable_ambient_occlusion")
                "[Input]"     = @("userawinput","disablemousesmoothing","disablecontrollerdeadzone","lockmousetowindow","rawinputbuffersize","rawinputbufferflush","enablelowlatencyinput","disablekeyboarddebounce")
                "[Renderer]"  = @("disablevsync","forcerenderaheadlimit","swapchainusewaitableswapchain","enableframepacing","enabletriplebuffering","disablelatencylimiter","waitforvblank","reduceinputlatency","immediatepresent","disableocclusionqueries")
            }

            $existingLines = Read-IniLinesSafe -Path $iniPath
            $output  = New-Object System.Collections.Generic.List[string]
            $current = ""
            $removed = 0
            foreach ($line in $existingLines) {
                $trim = Remove-InvisiblePrefix ($line.Trim())
                if ($trim.StartsWith("[") -and $trim.EndsWith("]")) {
                    $current = $trim
                    $output.Add($line)
                    continue
                }
                $k = Get-IniLineKey $line
                if ($k -and $managedKeysBySection.ContainsKey($current) -and $managedKeysBySection[$current] -contains $k) {
                    $removed++
                    continue
                }
                $output.Add($line)
            }
            Write-IniLinesSafe -Path $iniPath -Lines $output
            Write-LogTime "» CitizenFX.ini: removed $removed tweak setting(s), everything else (e.g. IVPath) kept" "#E0E0E0"
        } else {
            Write-LogTime "» CitizenFX.ini not found, nothing to reset" "#E0E0E0"
        }
    } catch {
        $failed.Add("CitizenFX.ini")
        Write-LogTime "» ERROR: Failed to reset CitizenFX.ini - $($_.Exception.Message)" "#F2F2F2"
    }

    # --- 2) Mouse & Keyboard registry tweaks -> back to Windows defaults --
    $mousePath = "HKCU:\Control Panel\Mouse"
    foreach ($i in 3..9) {
        try {
            if (Get-ItemProperty -Path $mousePath -Name "MouseThreshold$i" -ErrorAction SilentlyContinue) {
                Remove-ItemProperty -Path $mousePath -Name "MouseThreshold$i" -ErrorAction Stop
            }
        } catch { $failed.Add("$mousePath\MouseThreshold$i") }
    }

    $registryDefaults = @(
        @{ Path = $mousePath; Name = "MouseSensitivity";    Value = "10";  Type = "String" },
        @{ Path = $mousePath; Name = "MouseSpeed";          Value = "1";   Type = "String" },
        @{ Path = $mousePath; Name = "MouseThreshold1";     Value = "6";   Type = "String" },
        @{ Path = $mousePath; Name = "MouseThreshold2";     Value = "10";  Type = "String" },
        @{ Path = $mousePath; Name = "DoubleClickSpeed";    Value = "500"; Type = "String" },
        @{ Path = $mousePath; Name = "DoubleClickHeight";   Value = "4";   Type = "String" },
        @{ Path = $mousePath; Name = "DoubleClickWidth";    Value = "4";   Type = "String" },
        @{ Path = $mousePath; Name = "MouseHoverTime";      Value = "400"; Type = "String" },
        @{ Path = $mousePath; Name = "MouseHoverHeight";    Value = "4";   Type = "String" },
        @{ Path = $mousePath; Name = "MouseHoverWidth";     Value = "4";   Type = "String" },
        @{ Path = $mousePath; Name = "MouseTrails";         Value = "0";   Type = "String" },
        @{ Path = $mousePath; Name = "SnapToDefaultButton"; Value = "0";   Type = "String" },
        @{ Path = "HKCU:\Control Panel\Keyboard"; Name = "KeyboardDelay"; Value = "1";  Type = "String" },
        @{ Path = "HKCU:\Control Panel\Keyboard"; Name = "KeyboardSpeed"; Value = "31"; Type = "String" },
        @{ Path = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"; Name = "SystemResponsiveness";  Value = 20; Type = "DWord" },
        @{ Path = "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl";                       Name = "Win32PrioritySeparation"; Value = 2;  Type = "DWord" },
        @{ Path = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"; Name = "NetworkThrottlingIndex"; Value = 10; Type = "DWord" }
    )
    foreach ($r in $registryDefaults) {
        if (-not (Set-RegTweak $r.Path $r.Name $r.Value $r.Type)) { $failed.Add("$($r.Path)\$($r.Name)") }
    }
    Write-LogTime "» Mouse / keyboard / system responsiveness registry values restored to Windows defaults" "#E0E0E0"

    if ($failed.Count -gt 0) {
        $msg = "Failed to reset $($failed.Count) setting(s):`n" + ($failed -join "`n")
        Write-LogTime "» ERROR: $($failed.Count) setting(s) failed to reset (try running as Administrator)" "#F2F2F2"
        [System.Windows.MessageBox]::Show($msg, "Project UndergroundPrime - Error") | Out-Null
    } else {
        Write-LogTime "RESET complete." "#14eb00"
    }
}

$BtnTweakStandard.Add_Click({ Invoke-StandardTweaks })
$BtnTweakAdvanced.Add_Click({ Invoke-AdvancedTweaks })
$BtnSystemIni.Add_Click({ Invoke-SystemIniTweak })
$BtnResetTweaks.Add_Click({ Invoke-ResetTweaks })

$window.ShowDialog() | Out-Null

}

# =====================================================================
# ===== ENTRY POINT: splash then dashboard =============================
# =====================================================================

try { Clear-UGLeftovers } catch {}

# Hide console when UI starts
try { [ProjectUndergroundPrime.ConsoleWindow]::Hide() } catch {}

try {
    Show-SplashScreen -OnFinished { Show-MainWindow }
} catch {
    # Fallback: open dashboard directly if splash fails
    try {
        [ProjectUndergroundPrime.ConsoleWindow]::Hide() | Out-Null
    } catch {}
    try {
        Show-MainWindow
    } catch {
        try { [ProjectUndergroundPrime.ConsoleWindow]::Show() } catch {}
        $err = $_.Exception.Message
        try {
            [System.Windows.MessageBox]::Show(("Startup failed: " + $err), "Project UndergroundPrime") | Out-Null
        } catch {
            Write-Host ("Startup failed: " + $err)
            try { Remove-Module PSReadLine -Force -ErrorAction SilentlyContinue } catch {}
            Start-Sleep -Seconds 5
        }
    }
}
